insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-014-1$dg$, $dg$III$dg$, $dg$14$dg$, $dg$s.14(1)$dg$, $dg$Registration before collecting or processing$dg$, $dg$A person shall not collect or process personal data without being registered as a data controller or a data processor under this Act.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
