insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-016-1$dg$, $dg$III$dg$, $dg$16$dg$, $dg$s.16(1)$dg$, $dg$Five year registration period$dg$, $dg$The period of registration shall be five years from the date of issuance of certificate of registration.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-016-2$dg$, $dg$III$dg$, $dg$16$dg$, $dg$s.16(2)$dg$, $dg$Renewal three months before expiry$dg$, $dg$The application for renewal shall be submitted within the period of three months before expiry in the manner prescribed in the regulations.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-018-1$dg$, $dg$III$dg$, $dg$18$dg$, $dg$s.18$dg$, $dg$Deregistration$dg$, $dg$The Commission may deregister any registration under this Act as may be prescribed in the regulations.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-019-1$dg$, $dg$III$dg$, $dg$19$dg$, $dg$s.19$dg$, $dg$No false or misleading registration information$dg$, $dg$Any person who contravenes the provisions of this Part or furnishes false or misleading information during registration or renewal, commits an offence and upon conviction shall be liable for a penalty specified under section 63.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-020-1$dg$, $dg$III$dg$, $dg$20$dg$, $dg$s.20$dg$, $dg$Appeal to the Minister on registration decisions$dg$, $dg$Any person who is aggrieved by the decision of the Commission under this Part may appeal in writing to the Minister.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-021-1$dg$, $dg$III$dg$, $dg$21$dg$, $dg$s.21$dg$, $dg$Public institutions deemed registered$dg$, $dg$Immediately after commencement of this Act, public institutions which collect and process personal data shall be deemed as registered with the Commission under this Act and shall be required to comply with the provisions of this Act.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-022-1$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$s.22(1)$dg$, $dg$Scope of Part IV$dg$, $dg$This Part shall be applicable to (a) any collection and processing of personal data performed wholly or partly by manual or automated means; (b) the processing of personal data carried out in the performance of activities of a controller domiciled in United Republic or in a territory where the laws of the United Republic apply by virtue of international public law; and (c) the processing of personal data by a data controller or data processor who is not domiciled in the United Republic, if the processing of the personal data is in United Republic and such processing is not for the purposes of mere transit of personal data through Tanzania to another country.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-022-2$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$s.22(2)$dg$, $dg$Lawful purpose and necessity for collection$dg$, $dg$A data controller shall collect personal data if (a) the personal data is collected for a lawful purpose related to a function of the data controller; and (b) the collection of the data is necessary or incidental or directly related to the lawful purpose.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-022-3$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$s.22(3)$dg$, $dg$No collection by unlawful means$dg$, $dg$A data controller shall not collect personal data by unlawful means.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-023-1$dg$, $dg$IV$dg$, $dg$23$dg$, $dg$s.23(1)$dg$, $dg$Direct collection from the data subject$dg$, $dg$Subject to subsection (3), a data controller shall collect personal data directly from the data subject concerned.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-023-2$dg$, $dg$IV$dg$, $dg$23$dg$, $dg$s.23(2)$dg$, $dg$Pre-collection notification$dg$, $dg$Before collecting data, a data controller shall ensure that the data subject is aware of (a) the purposes for which the personal data is collected; (b) the fact that collection of the personal data is for authorised purposes; and (c) any intended recipients of the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-023-3$dg$, $dg$IV$dg$, $dg$23$dg$, $dg$s.23(3)$dg$, $dg$Exceptions to direct collection$dg$, $dg$A data controller is not obliged to comply with subsection (1) where (a) the personal data is publicly available; (b) the data subject concerned authorises the collection of the personal data from a third party; (c) compliance is not reasonably practicable in the circumstances of the particular case; (d) non-compliance is necessary for compliance with other written laws; or (e) compliance would prejudice the lawful purpose of the collection.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-024-1$dg$, $dg$IV$dg$, $dg$24$dg$, $dg$s.24$dg$, $dg$Accuracy before use$dg$, $dg$Subject to the purpose for which the personal data are intended to be used, a data controller who holds personal data shall not use that personal data without taking such steps as are, in the circumstances, reasonable to ensure that the data is complete, accurate, relevant and not misleading.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-025-1$dg$, $dg$IV$dg$, $dg$25$dg$, $dg$s.25(1)$dg$, $dg$Use for the intended purpose$dg$, $dg$Personal data collected under this Act shall be used for the intended purposes.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-025-2$dg$, $dg$IV$dg$, $dg$25$dg$, $dg$s.25(2)$dg$, $dg$Permitted secondary use$dg$, $dg$Where a data controller holds personal data that was collected in connection with a particular purpose, he may use that personal data for other purposes only on the grounds listed in section 25(2)(a) to (f).$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-026-1$dg$, $dg$IV$dg$, $dg$26$dg$, $dg$s.26$dg$, $dg$Limitation on disclosure$dg$, $dg$Where a data controller holds personal data, he shall not disclose the personal data to a person, other than the data subject, except in the circumstances specified under section 25.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-027-1$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$s.27(1)$dg$, $dg$Reasonable security safeguards$dg$, $dg$A data controller and his representatives shall ensure that personal data is protected, by such security safeguards that is reasonable in the circumstances necessary for the personal data protection against negligent loss or unauthorised destruction, alteration, access or processing of the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-027-2A$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$s.27(2)(a)$dg$, $dg$Technology and cost factors$dg$, $dg$Security measures taken in accordance with subsection (1) shall ensure an appropriate level of security taking into account the state of technological advancement and the cost of implementing the measures.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-027-2B$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$s.27(2)(b)$dg$, $dg$Nature of data and risk to data subject$dg$, $dg$Security measures taken in accordance with subsection (1) shall ensure an appropriate level of security taking into account the nature of the personal data to be protected and the potential risks to the data subject.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-027-3$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$s.27(3)$dg$, $dg$Appointment of a data protection officer$dg$, $dg$The data controller and data processor, as the case may be, shall appoint a data protection officer who shall ensure that the control and security measures are in place to protect the personal data collected or being processed.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-027-4$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$s.27(4)$dg$, $dg$Contract governing the data processor$dg$, $dg$Implementation of activities of the data processor shall be governed by a contract which associates the data processor to the data controller to the effect that the data processor acts under instructions of the data controller and that the data processor is additionally responsible for ensuring compliance of the security standards as provided by this Act.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-027-5$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$s.27(5)$dg$, $dg$Security breach notification to the Commission$dg$, $dg$The data controller shall notify the Commission, without any undue delay, of any security breach affecting personal data being processed by or on behalf of the data controller.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-028-1$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$s.28(1)$dg$, $dg$Retention for the period specified in law or regulations$dg$, $dg$Where a data controller uses personal data for a specified purpose as specified under section 25, he shall retain that personal data for a period specified in the relevant laws or a period prescribed in the regulations in order to ensure that the data subject has a reasonable opportunity to access the personal data where need arises.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-028-2$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$s.28(2)$dg$, $dg$Ministerial regulations on retention and disposal$dg$, $dg$Subject to subsection (1), the Minister may, by regulations, prescribe the retention and disposal of personal data held by a data controller in accordance with the purpose of retention.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-029-1$dg$, $dg$IV$dg$, $dg$29$dg$, $dg$s.29(1)$dg$, $dg$Amendment of personal data on application$dg$, $dg$Where a document or file to which access has been given under this Act contains personal data and that data subject claims that the personal data is incomplete, incorrect or misleading, or not relevant to the purpose for which the document is held, the data controller may, subject to procedures as may be prescribed in the regulations and upon receiving and being satisfied with the application of the data subject, amend the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-029-2$dg$, $dg$IV$dg$, $dg$29$dg$, $dg$s.29(2)$dg$, $dg$Preservation of the pre-amendment record$dg$, $dg$The data controller shall, when making an amendment to personal data in a document under this section, ensure that he does not permanently delete the record of the text of the document as it existed prior to the amendment.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-029-3$dg$, $dg$IV$dg$, $dg$29$dg$, $dg$s.29(3)$dg$, $dg$Refusal with reasons$dg$, $dg$Where a data controller is not satisfied with the reasons for an application under subsection (1), he may refuse to make any amendment to the personal data and inform the applicant of the reasons for refusal.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-030-1$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$s.30(1)$dg$, $dg$Prior written consent for sensitive personal data$dg$, $dg$A person shall not process sensitive personal data without obtaining prior written consent of the data subject.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-030-2$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$s.30(2)$dg$, $dg$Withdrawal of consent$dg$, $dg$The consent under subsection (1) may be withdrawn by the data subject at any time and without any explanation or charges.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-030-3$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$s.30(3)$dg$, $dg$Circumstances where the prohibition cannot be removed by consent$dg$, $dg$The Minister may, by regulations, determine circumstances in which the prohibition to process the personal data referred to in this section cannot be removed even with the data subject consent.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-030-4$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$s.30(4)$dg$, $dg$Consent on behalf of persons unable to consent$dg$, $dg$Where the data subject from whom consent is sought is a minor, a person of unsound mind or any other person unable to consent, such person consent shall be sought from his parents, guardian, heirs, attorneys or any other person recognised by law to be acting on behalf of the person whose consent is to be sought.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-030-5$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$s.30(5)$dg$, $dg$Exceptions to the consent requirement$dg$, $dg$Subsection (1) shall not apply where the processing is necessary for compliance with other written laws; is necessary to protect the vital interests of the data subject or of another person where the data subject is incapable of giving consent or is not represented by a legal representative; is necessary for the institution, trial or defence of legal claims; relates to personal data apparently made public by the data subject; is necessary for the purposes of scientific research and the Commission has by special guidelines specified the circumstances; or is necessary for medical reasons in the interest of the data subject and is processed under the supervision of a health professional in accordance with the law governing such health care services.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-031-1$dg$, $dg$V$dg$, $dg$31$dg$, $dg$s.31(1)$dg$, $dg$Commission power to prohibit transfers$dg$, $dg$The Commission may, subject to the provisions of this Act, prohibit the transfer of personal data to a place outside the country.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-031-2$dg$, $dg$V$dg$, $dg$31$dg$, $dg$s.31(2)$dg$, $dg$Transfer to a state with adequate protection$dg$, $dg$Personal data shall be transferred to country that has a legal framework that provides for adequate data protection, if (a) the recipient establishes that the personal data is necessary for the performance of a task carried out in the public interest or pursuant to the lawful functions of a data controller; or (b) the recipient establishes the necessity of having the data transferred and there is no reason to assume that the data subject legitimate interests might be prejudiced by the transfer or the processing in the recipient country.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-031-3$dg$, $dg$V$dg$, $dg$31$dg$, $dg$s.31(3)$dg$, $dg$Provisional evaluation of necessity$dg$, $dg$The data controller shall, notwithstanding subsection (2), be required to make a provisional evaluation of the necessity for the transfer of the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-031-4$dg$, $dg$V$dg$, $dg$31$dg$, $dg$s.31(4)$dg$, $dg$Subsequent verifiability of necessity$dg$, $dg$The recipient shall ensure that the necessity for the transfer of the personal data can be subsequently verified.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-031-5$dg$, $dg$V$dg$, $dg$31$dg$, $dg$s.31(5)$dg$, $dg$Recipient processing limited to transfer purposes$dg$, $dg$The data controller shall ensure that the recipient shall process the personal data for the purposes for which it was transferred.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-032-1$dg$, $dg$V$dg$, $dg$32$dg$, $dg$s.32(1)$dg$, $dg$Transfer to other recipient states$dg$, $dg$Personal data may be transferred to recipients states other than those referred to under section 31, if an adequate level of protection is ensured in the country of the recipient and the personal data is transferred solely to permit processing authorised to be undertaken by the controller.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-032-2$dg$, $dg$V$dg$, $dg$32$dg$, $dg$s.32(2)$dg$, $dg$Adequacy assessment factors$dg$, $dg$The adequacy of the level of protection afforded by the relevant third country shall be assessed in the light of (a) all the circumstances surrounding the relevant personal data transfer; (b) nature of the personal data; (c) the purpose and duration of the proposed processing; (d) the recipient country; (e) the relevant laws in force in the third country; and (f) the professional rules and security measures which are complied within that recipient country.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-032-3$dg$, $dg$V$dg$, $dg$32$dg$, $dg$s.32(3)$dg$, $dg$Regulations specifying unauthorised transfers$dg$, $dg$The Minister shall, after consultation with Commission and by regulations, specify categories of processing for which and the circumstances in which the transfer of personal data to countries outside the United Republic is not authorised.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-032-4$dg$, $dg$V$dg$, $dg$32$dg$, $dg$s.32(4)$dg$, $dg$Derogations permitting transfer$dg$, $dg$Notwithstanding subsection (3), a transfer of personal data to a recipient in a country outside the country or to a country which does not have adequate level of protection may take place where the data subject has consented; the transfer is necessary for the performance of a contract between the data subject and the controller or pre-contractual measures at the data subject request; the transfer is necessary for the conclusion or performance of a contract between the controller and a third party in the interest of the data subject; the transfer is necessary or legally required on public interest grounds or for the institution, trial or defence of legal claims; the transfer is necessary to protect the legitimate interests of the data subject; or the transfer is made in accordance with the law and is intended to provide information to the public and is open for consultation.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-032-5$dg$, $dg$V$dg$, $dg$32$dg$, $dg$s.32(5)$dg$, $dg$Commission authorisation on adequate safeguards$dg$, $dg$Without prejudice to the provisions of this Act, the Commission may authorise a transfer of personal data to a recipient country or any other country which does not have adequate level of protection in its laws, if the data controller satisfies the Commission that there is adequate safeguards with respect to the protection of personal data, fundamental rights and freedoms of the data subject and the exercise of the data subject rights, and that such safeguards can be appropriated through adequate legal and security measures and contractual clauses in particular.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-033-1A$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$s.33(1)(a)$dg$, $dg$Right to confirmation of processing$dg$, $dg$A data subject shall be entitled to be informed by any data controller whether his personal data are being processed by or on behalf of that data controller.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-033-1B$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$s.33(1)(b)$dg$, $dg$Right to a description of the data, purposes and recipients$dg$, $dg$A data subject shall be entitled to be given by the data controller a description of the personal data of which that individual is the data subject, the purposes for which they are being processed, and the recipients or classes of recipients to whom they are or may be disclosed.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-033-1C$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$s.33(1)(c)$dg$, $dg$Right to be informed of the logic of automated decisions$dg$, $dg$Where the processing of personal data by automatic means for the purpose of evaluating matters relating to him has constituted or is likely to constitute the sole basis for any decision significantly affecting him, the data subject is entitled to be informed by the data controller of the logic involved in that decision making.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-033-2$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$s.33(2)$dg$, $dg$Exceptions to informing the data subject$dg$, $dg$A data controller is not obliged to inform the data subject where the personal data are not accurate, are involved in any investigation in accordance with the laws, or have been prohibited by court order.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-034-1$dg$, $dg$VI$dg$, $dg$34$dg$, $dg$s.34(1)$dg$, $dg$Right to prevent processing likely to cause substantial damage$dg$, $dg$A data subject is entitled to require a data controller, through procedures prescribed in the regulations, to suspend or not to begin processing of any personal data in respect of which he is the data subject, if the processing of such personal data is likely to cause substantial damage to him or to another person.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-035-1$dg$, $dg$VI$dg$, $dg$35$dg$, $dg$s.35(1)$dg$, $dg$Right to stop direct marketing$dg$, $dg$A data subject may, through the procedures prescribed in the regulations, require the data controller to stop processing his personal data for purposes of direct marketing.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-035-2$dg$, $dg$VI$dg$, $dg$35$dg$, $dg$s.35(2)$dg$, $dg$Agreement for pecuniary benefit$dg$, $dg$A data subject may enter into agreement with a data controller for purposes of using or processing his personal data for pecuniary benefits.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-036-1$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$s.36(1)$dg$, $dg$Right to require that decisions are not based solely on automated processing$dg$, $dg$A data subject may, through the procedures prescribed in the regulations, require the data controller to ensure that any decision taken by or on behalf of the data controller which significantly affects the data subject shall not be based solely on the processing by automatic means.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-036-2$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$s.36(2)$dg$, $dg$Notification and reconsideration of automated decisions$dg$, $dg$Where a decision which significantly affects a data subject is based solely on automated processing, the data controller shall as soon as practicable notify the data subject that the decision was taken on that basis, and the data subject may require the data controller to reconsider the decision.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-036-3$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$s.36(3)$dg$, $dg$Exceptions for automated decisions$dg$, $dg$This section shall not apply if the decision is necessary for entering into, or performance of, a contract between the data subject and a data controller; is authorised by any written law; or is based on the data subject explicit consent.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-037-1$dg$, $dg$VI$dg$, $dg$37$dg$, $dg$s.37(1)-(2)$dg$, $dg$Right to compensation for damage$dg$, $dg$A data subject who suffers damage by reason of any contravention of any of the requirements of this Act by a data controller or data processor shall be entitled to compensation from the data controller or data processor for that damage, on the conditions set out in section 37(2).$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-037-3$dg$, $dg$VI$dg$, $dg$37$dg$, $dg$s.37(3)$dg$, $dg$Commission order for rectification, blocking, erasure or destruction$dg$, $dg$Where the Commission is satisfied on the application of a data subject that he has suffered damage entitling him to compensation and that there is a substantial risk of further contravention, the Commission may order the rectification, blocking, erasure or destruction of any of the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-037-4$dg$, $dg$VI$dg$, $dg$37$dg$, $dg$s.37(4)-(5)$dg$, $dg$Notification of third parties following a Commission order$dg$, $dg$The Commission may, where it makes an order under subsection (3) and where it considers it reasonable, order the data controller or data processor to notify third parties to whom the personal data have been disclosed of the rectification, blocking, erasure or destruction.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-038-1$dg$, $dg$VI$dg$, $dg$38$dg$, $dg$s.38(1)-(2)$dg$, $dg$Commission order to rectify, block, erase or destroy inaccurate data$dg$, $dg$Where the Commission is satisfied on the application of a data subject that his personal data is inaccurate, the Commission may order the data controller or data processor to rectify, block, erase or destroy the personal data, whether or not the personal data is an accurate record of information received or obtained from the data subject or a third party.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-038-3$dg$, $dg$VI$dg$, $dg$38$dg$, $dg$s.38(3)$dg$, $dg$Direction to correct personal data$dg$, $dg$Where the personal data is not an accurate record of the information, the Commission may direct the data controller or processor to correct the personal data as it considers appropriate.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-038-4$dg$, $dg$VI$dg$, $dg$38$dg$, $dg$s.38(4)$dg$, $dg$Notification of third parties after rectification or erasure$dg$, $dg$Where the personal data complained of has been rectified, blocked, updated, erased or destroyed under this section, the data controller or data processor shall be required to notify third parties to whom the personal data has been previously disclosed of the rectification, blocking, updating, erasure or destruction.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-039-1$dg$, $dg$VII$dg$, $dg$39$dg$, $dg$s.39(1)-(4)$dg$, $dg$Complaints to the Commission and investigation timeline$dg$, $dg$Any person who considers that a data controller or data processor has infringed personal data protection principles may file a complaint to the Commission. Where the Commission is satisfied that there are reasonable grounds it may initiate an investigation. A complaint shall be investigated and concluded within ninety days from the date of receipt, extendable by the Commission by up to a further ninety days.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-040-1$dg$, $dg$VII$dg$, $dg$40$dg$, $dg$s.40$dg$, $dg$Notice of investigation$dg$, $dg$Before commencing an investigation of a complaint under this Act, the Commission shall, in a form prescribed in the regulations, notify the data controller or data processor concerned of the substance of the complaint and intention to carry out the investigation.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-042-1$dg$, $dg$VII$dg$, $dg$42$dg$, $dg$s.42(1)-(2)$dg$, $dg$Powers of the Commission in investigations$dg$, $dg$In the course of carrying out an investigation the Commission has power to summon a person; receive and accept evidence and other information; enter any premises occupied by any data controller or data processor for satisfying security requirements of the premises; interrogate any person or take any device with personal data in any premises entered; and examine or obtain copies of or extracts from books, documents or other records found in any such premises. The complainant and the data controller or data processor may be given an opportunity to make representations.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-042-3$dg$, $dg$VII$dg$, $dg$42$dg$, $dg$s.42(3)-(4)$dg$, $dg$No withholding of personal data from the Commission$dg$, $dg$Notwithstanding any other written law, the Commission may examine any personal data recorded in any form held by a data controller or data processor and in doing so, no personal data shall be withheld from the Commission. Any document or article produced shall be returned by the Commission within ten working days after a request is made.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-043-1$dg$, $dg$VII$dg$, $dg$43$dg$, $dg$s.43$dg$, $dg$Obstruction of the Commission$dg$, $dg$A person who obstructs or impedes the Commission in the exercise of its powers; fails to provide assistance or information requested by the Commission; refuses to allow the Commission to enter any premises or to take any document or device with personal data; or gives to the Commission any information which is false or misleading, commits an offence and shall be liable on conviction to a fine of not less than one hundred thousand shillings but not exceeding five million shillings or imprisonment to a term of not more than two years, or both.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-045-1$dg$, $dg$VII$dg$, $dg$45$dg$, $dg$s.45(1)-(2)$dg$, $dg$Enforcement notice$dg$, $dg$Where the Commission is satisfied that a person has failed to comply with any provision of this Act, the Commission may serve an enforcement notice requiring that person to rectify the failure within such period as may be specified in the notice. The notice shall specify the provision contravened, the measures to be taken, a period of not less than twenty-one days within which the measures shall be implemented, and shall state any right to appeal.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-046-1$dg$, $dg$VII$dg$, $dg$46$dg$, $dg$s.46(1)-(2)$dg$, $dg$Penalty notice and its determining factors$dg$, $dg$Where the Commission is satisfied that a person has failed or is failing to comply with an enforcement notice, the Commission may issue a penalty notice requiring payment of a fine of an amount specified in the notice. In deciding whether to give a penalty notice and determining the amount, the Commission shall have regard to the eleven factors listed in section 46(2)(a) to (k).$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-047-1$dg$, $dg$VII$dg$, $dg$47$dg$, $dg$s.47$dg$, $dg$Maximum administrative fine$dg$, $dg$The maximum amount of the penalty that may be imposed by the Commission in a penalty notice in relation to contravention of provisions of this Act is one hundred million shillings.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-048-1$dg$, $dg$VII$dg$, $dg$48$dg$, $dg$s.48$dg$, $dg$Review of a Commission decision$dg$, $dg$The Commission may, upon application or on its own motion, review its decision or direction given in accordance with the provisions of this Part, and may reverse, alter or revoke it.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-049-1$dg$, $dg$VII$dg$, $dg$49$dg$, $dg$s.49$dg$, $dg$Right of appeal to the High Court$dg$, $dg$A person who is aggrieved with the administrative action taken by the Commission, including the directions given in the enforcement notice or penalty imposed in the penalty notice, may appeal to the High Court.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-050-1$dg$, $dg$VII$dg$, $dg$50$dg$, $dg$s.50(1)$dg$, $dg$Commission order to pay compensation$dg$, $dg$Subject to the provisions of section 37, the Commission may, in addition to any penalty given under this Act, order a data controller or data processor who causes damages to the data subject following contraventions of any provisions of this Act to pay compensation to the data subject.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-050-2$dg$, $dg$VII$dg$, $dg$50$dg$, $dg$s.50(2)-(3)$dg$, $dg$Liability of controllers and processors$dg$, $dg$A data controller involved in processing of personal data shall be liable for damage caused by the processing. A data processor shall be liable for damage caused by the processing if the processor has not complied with an obligation under the Act specifically directed to data processors, or has acted contrary to the data controller lawful instructions. A data controller or data processor shall not be liable if it proves that it is not in any way responsible for the event that caused the damage.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-058-1$dg$, $dg$IX$dg$, $dg$58$dg$, $dg$s.58(1)$dg$, $dg$Exemptions do not displace the principles or security duties$dg$, $dg$Nothing under this section shall exempt the data controller or the data processor from the responsibility of complying with the principles of the law in collection and processing of personal data and taking necessary measures to ensure protection and security of the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-058-2$dg$, $dg$IX$dg$, $dg$58$dg$, $dg$s.58(2)-(3)$dg$, $dg$Exempted processing$dg$, $dg$Processing of personal data may be exempted from the provisions of this Act if such processing is held by the data subject for his personal use; in accordance with any law or court order; for purpose of safeguarding national safety and security and public interest; for the purpose of prevent or detect crimes; for the purpose of detect or prevent tax evasion; for the purpose of investigation of misappropriation of public funds; or for purposes of vetting for appointment to any public service position. The Minister may prescribe other instances.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-059-1$dg$, $dg$IX$dg$, $dg$59$dg$, $dg$s.59$dg$, $dg$Preservation order$dg$, $dg$The Commission may apply to a court for a preservation order for the expeditious preservation of any personal data including traffic personal data, where there is reasonable ground to believe that the personal data is vulnerable to loss or modification. The order shall specify a period not more than ninety days, extendable by the court.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-060-1$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$s.60(1)$dg$, $dg$Unlawful disclosure by a data controller$dg$, $dg$A data controller who, without lawful excuse, discloses personal data in any manner that is incompatible with the purpose for which such personal data has been collected commits an offence.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-060-2$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$s.60(2)$dg$, $dg$Unlawful disclosure by a data processor$dg$, $dg$A data processor who, without lawful excuse, discloses personal data processed by the data processor without the prior authority of the data controller commits an offence.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-060-3$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$s.60(3)$dg$, $dg$Unlawful obtaining or disclosure of personal data$dg$, $dg$A person who obtains personal data, or obtains any information constituting personal data, without prior authority of the data controller or data processor by whom the personal data is kept, or discloses personal data to a third party, commits an offence.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-060-4$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$s.60(4)-(5)$dg$, $dg$Offering personal data for sale$dg$, $dg$A person who offers for sale personal data of another person obtained in breach of subsection (1) commits an offence. An advertisement indicating that personal data is or may be for sale constitutes an offer for sale of the personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-061-1$dg$, $dg$IX$dg$, $dg$61$dg$, $dg$s.61$dg$, $dg$Unlawful destruction, deletion, concealment or alteration$dg$, $dg$A person who unlawfully destroys, deletes, misleads, conceals or alters personal data commits an offence and shall, upon conviction, be liable to a fine of not less than one hundred thousand shillings but not exceeding ten million shillings or to imprisonment for a term not exceeding five years or both.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-062-1$dg$, $dg$IX$dg$, $dg$62$dg$, $dg$s.62$dg$, $dg$Offences by a company or corporation$dg$, $dg$Where an offence under this Act is committed by a company or corporation, the company or corporation and every officer of the company or corporation who knowingly and willfully authorises or permits the contravention shall be liable for the offence.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-064-1$dg$, $dg$IX$dg$, $dg$64$dg$, $dg$s.64(1)-(2)$dg$, $dg$Regulations$dg$, $dg$The Minister may make regulations for giving effect to the provisions of this Act, including regulations prescribing the matters listed in section 64(2)(a) to (l).$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-065-1$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$s.65(1)$dg$, $dg$Code of ethics or policy for personal data protection$dg$, $dg$Every data controller shall draw and put in place a code of ethics or policy for personal data protection which shall prescribe for ethics and conduct to be complied with during collection or processing of personal data.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-065-2$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$s.65(2)$dg$, $dg$Submission to the Commission$dg$, $dg$Such codes or policies shall be submitted to the Commission for consideration and approval.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_requirements (framework_code, version_code, requirement_id, part_number, section_number, provision, requirement_title, requirement_text) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$REQ-065-3$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$s.65(3)$dg$, $dg$Commission consideration and amendment before approval$dg$, $dg$In considering the codes of ethics or policies, the Commission shall ascertain among other things whether the drafts submitted to it have complied with the provisions of this Act and the relevant sector and where it considers necessary, seek the views of data subjects or their representatives and consult with the data controller concerned for the purposes of undertaking necessary amendments prior to the approval.$dg$) on conflict (framework_code, version_code, requirement_id) do update set part_number=excluded.part_number, section_number=excluded.section_number, provision=excluded.provision, requirement_title=excluded.requirement_title, requirement_text=excluded.requirement_text;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-002-001$dg$, $dg$REQ-002-1$dg$, $dg$I$dg$, $dg$2$dg$, NULL, NULL, $dg$Section 2$dg$, $dg$The Act applies to Mainland Tanzania and to Tanzania Zanzibar, save that in Tanzania Zanzibar it does not apply to non-union matters.$dg$, $dg$Territorial scope determination$dg$, $dg$The organisation has determined which of its operations fall within the territorial scope of the Act, including whether any Zanzibar operations concern non-union matters.$dg$, $dg$Have you worked out which parts of your organisation and which activities the Tanzania Personal Data Protection Act applies to?$dg$, $dg$Knowing exactly where the Act applies decides which of your teams, systems and records have to follow it. Getting this wrong at the start makes every later answer unreliable.$dg$, $dg$Record the entities, branches and processing activities in scope. Note separately any activity carried out in Zanzibar that you consider a non-union matter, and the basis for that view. Whether a matter is a union matter is a constitutional question - take advice rather than deciding it informally.$dg$, $dg$A documented scoping statement listing in-scope entities, locations and processing activities, reviewed at least annually.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. An incorrect scope assessment silently invalidates the rest of the assessment, but it is a foundational rather than an operational failure.$dg$, $dg$Run a scoping workshop with legal, IT and business owners. Produce a written scope statement and have it approved by the accountable executive.$dg$, $dg$Document the territorial and organisational scope of PDPA applicability$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. Section 2 states the territorial reach of the Act. The obligation to document a scoping exercise is DataGuard implementation practice, not a statutory requirement, and adds no new legal obligation.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Scoping Statement$dg$, $dg$Data Processing Register$dg$, $dg$Group Structure Chart$dg$]::text[], true, 1) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-001$dg$, $dg$REQ-005-A$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(a)$dg$, $dg$Section 5(a)$dg$, $dg$Personal data shall be processed lawfully, fairly and transparently.$dg$, $dg$Lawful, fair and transparent processing$dg$, $dg$All processing of personal data is carried out on a lawful footing, is fair to the individuals concerned, and is explained to them openly.$dg$, $dg$Is every use you make of personal data lawful, fair to the people concerned, and openly explained to them?$dg$, $dg$This is the headline principle of the Act. If people are surprised or misled about what happens to their data, the processing is not fair or transparent even if nothing else has gone wrong.$dg$, $dg$Maintain a record of each processing activity with the lawful basis relied on, and a plain-language privacy notice that matches what actually happens. Check that the notice and the record agree.$dg$, $dg$A current processing record and a published privacy notice that accurately describe all processing activities.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$LAWFULNESS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Section 5 principles apply to every processing activity and are the benchmark against which complaints under section 39 are assessed.$dg$, $dg$Build or refresh the processing register, assign a lawful basis to each activity, then rewrite the privacy notice so it matches.$dg$, $dg$Establish a processing register with a documented lawful basis for each activity$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$The Act states the principle but does not set out an exhaustive list of lawful bases. Lawfulness is assessed against the Act as a whole and against other written laws.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Privacy Policy$dg$, $dg$Privacy Notice$dg$, $dg$Data Processing Register$dg$, $dg$Data Protection Policy$dg$]::text[], true, 2) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-002$dg$, $dg$REQ-005-B$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(b)$dg$, $dg$Section 5(b)$dg$, $dg$Personal data shall be collected for explicit, specified and legitimate purposes and not further processed in a manner incompatible with those purposes.$dg$, $dg$Purpose specification and limitation$dg$, $dg$Each collection of personal data has a stated, specific and legitimate purpose recorded in advance, and later uses are checked against that purpose.$dg$, $dg$For each set of personal data you collect, have you written down exactly why you collect it, and do you keep uses within that reason?$dg$, $dg$Purpose is the anchor for almost every other duty in the Act - how long you keep data, who you may share it with, and whether a new use is allowed.$dg$, $dg$Record a specific purpose statement per processing activity. Avoid catch-all wording such as business purposes. Route any proposed new use through a compatibility check before it starts.$dg$, $dg$Every processing activity in the register has an explicit purpose, and a documented route exists for approving new uses.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$PURPOSE_LIMITATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Purpose creep is the most common cause of downstream breaches of sections 25 and 26.$dg$, $dg$Document a purpose for each activity in the register and introduce a change-of-purpose approval step.$dg$, $dg$Record an explicit purpose for every processing activity$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Processing Register$dg$, $dg$Privacy Notice$dg$, $dg$Purpose Compatibility Assessment$dg$]::text[], true, 3) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-003$dg$, $dg$REQ-005-C$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(c)$dg$, $dg$Section 5(c)$dg$, $dg$Personal data shall be adequate, relevant and limited to what is necessary in relation to the purposes for which it is processed.$dg$, $dg$Data minimisation$dg$, $dg$The organisation collects and retains only the personal data fields that are necessary for the stated purpose.$dg$, $dg$Do you collect only the personal information you actually need for the purpose, and no more?$dg$, $dg$Every extra field you hold is extra risk if something goes wrong, and it is harder to justify to the Commission or to the person concerned.$dg$, $dg$Review forms, application screens and data feeds field by field against the recorded purpose. Remove or stop collecting fields that no longer earn their place.$dg$, $dg$A documented field-level review per collection point, with unnecessary fields removed.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$DATA_MINIMISATION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Over-collection is a standing breach of section 5(c) and increases the impact of any incident, but it rarely causes immediate harm on its own.$dg$, $dg$Run a field-level review of the highest-volume collection points first, then work down.$dg$, $dg$Review collection forms and remove unnecessary personal data fields$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Minimisation Review$dg$, $dg$Data Processing Register$dg$, $dg$Form and Screen Inventory$dg$]::text[], true, 4) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-004$dg$, $dg$REQ-005-D$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(d)$dg$, $dg$Section 5(d)$dg$, $dg$Personal data shall be accurate and where necessary kept up to date, with every reasonable step taken to ensure that any inaccurate personal data is erased or rectified without delay.$dg$, $dg$Accuracy and prompt rectification$dg$, $dg$The organisation keeps personal data accurate and up to date, and corrects or erases inaccurate data without delay once identified.$dg$, $dg$Do you keep personal information accurate and up to date, and fix or delete wrong information promptly when you find it?$dg$, $dg$Decisions made on wrong information can cause real harm to people, and the Act requires you to act without delay once you know.$dg$, $dg$Define how inaccuracies are reported and who fixes them, and set an internal turnaround target. The Act says without delay but does not fix a number of days, so any target you set is your own commitment.$dg$, $dg$A documented data quality and rectification process with a defined internal turnaround target and a log of corrections made.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$QUARTERLY$dg$, $dg$DATA_QUALITY$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Inaccuracy is directly actionable by the Commission under section 38 and can found a compensation claim under section 37.$dg$, $dg$Create a rectification workflow with an owner, a target turnaround and an audit log. Link it to the section 29 correction process.$dg$, $dg$Implement a data accuracy and rectification workflow$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$INTERPRETATION: any specific turnaround time an organisation sets is its own commitment. The Act says without delay and does not prescribe a period.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Quality Procedure$dg$, $dg$Rectification Log$dg$, $dg$Data Subject Rights Procedure$dg$]::text[], true, 5) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-005$dg$, $dg$REQ-005-E$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(e)$dg$, $dg$Section 5(e)$dg$, $dg$Personal data shall be stored in a form which permits identification of data subjects for no longer than is necessary for the purposes for which the personal data is processed.$dg$, $dg$Storage limitation$dg$, $dg$Personal data is held in identifiable form only for as long as the purpose requires, after which it is disposed of or de-identified.$dg$, $dg$Do you stop keeping personal information in a form that identifies people once you no longer need it for the purpose?$dg$, $dg$Holding identifiable data indefinitely creates risk with no offsetting benefit, and it is one of the easiest failures for a regulator to spot.$dg$, $dg$Read this together with section 28. Where a retention period is fixed by another written law or by regulations made under the Act, that period governs. Where it is not, justify the period against the purpose and record the reasoning.$dg$, $dg$A retention schedule covering all record types, with a defined end-of-life action for each.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Over-retention breaches section 5(e) and compounds the impact of any security incident.$dg$, $dg$Build a retention schedule keyed to record type and purpose, then automate or diarise the disposal step.$dg$, $dg$Produce a retention schedule covering all personal data record types$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$Section 28(2) empowers the Minister to prescribe retention and disposal by regulations. Do not assume a period that is not fixed by a relevant law or by those regulations.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Retention Schedule$dg$, $dg$Disposal Log$dg$, $dg$Data Processing Register$dg$]::text[], true, 6) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-006$dg$, $dg$REQ-005-F$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(f)$dg$, $dg$Section 5(f)$dg$, $dg$Personal data shall be processed in accordance with the rights of a data subject.$dg$, $dg$Processing consistent with data subject rights$dg$, $dg$Processing operations are designed so that the rights in Part VI of the Act can actually be exercised and honoured.$dg$, $dg$Are your systems and processes set up so that people can actually exercise their rights over their data?$dg$, $dg$Rights that cannot be delivered in practice are a compliance failure even where nobody has yet complained.$dg$, $dg$Confirm that for each system holding personal data you can locate an individual record, describe the purposes and recipients, suspend processing, and rectify or erase where required.$dg$, $dg$A rights-readiness assessment per system, with gaps tracked to closure.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Inability to serve a right is directly visible to data subjects and is the usual trigger for a section 39 complaint.$dg$, $dg$Assess each major system against the Part VI rights and remediate the systems that cannot support them.$dg$, $dg$Assess each system against the Part VI data subject rights$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Subject Rights Procedure$dg$, $dg$System Rights Readiness Assessment$dg$, $dg$Rights Request Log$dg$]::text[], true, 7) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_n