insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-007$dg$, $dg$REQ-005-G$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(g)$dg$, $dg$Section 5(g)$dg$, $dg$Personal data shall be processed in a manner that ensures appropriate security of the personal data, including protection against unauthorised or unlawful processing and against any loss, destruction or damage, using appropriate technical or organisational measures.$dg$, $dg$Security principle - technical and organisational measures$dg$, $dg$A programme of technical and organisational security measures protects personal data across its lifecycle.$dg$, $dg$Do you have a set of technical and organisational security measures that protect personal data throughout its life?$dg$, $dg$This principle sits alongside the detailed duties in section 27, and it binds data processors directly as well as data controllers.$dg$, $dg$Maintain a documented security programme and map each measure to the risk it addresses. The section 27 controls decompose this obligation further.$dg$, $dg$An approved information security policy with an inventory of implemented technical and organisational measures.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SECURITY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Security failures are the highest-impact and least reversible category of non-compliance, and section 5(g) binds processors directly, not only controllers.$dg$, $dg$Stand up a documented security programme and align it to the specific section 27 duties.$dg$, $dg$Establish and document an information security programme for personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 5 binds both the data controller and the data processor. Section 27(1) by its terms addresses the data controller and his representatives.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Security Policy$dg$, $dg$Information Security Programme$dg$, $dg$Risk Assessment$dg$, $dg$Access Control Procedure$dg$]::text[], true, 8) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-005-008$dg$, $dg$REQ-005-H$dg$, $dg$I$dg$, $dg$5$dg$, NULL, $dg$(h)$dg$, $dg$Section 5(h)$dg$, $dg$Personal data shall not be transferred abroad contrary to the provisions of this Act.$dg$, $dg$No transfer abroad contrary to the Act$dg$, $dg$Transfers of personal data outside Tanzania are only made on a basis permitted by Part V of the Act.$dg$, $dg$Do you make sure that personal data only leaves Tanzania on a basis the Act allows?$dg$, $dg$Cloud services, group companies and overseas suppliers move data across borders routinely, often without anyone noticing.$dg$, $dg$Read with sections 31 and 32. Identify every route by which data leaves the country, including remote support access and offshore backups, then confirm the basis for each.$dg$, $dg$A transfer inventory covering all cross-border flows with a recorded Part V basis for each.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Does any personal data you hold leave Tanzania - including cloud hosting, offshore backups, group systems or remote support access?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Unrecognised transfers are common and each one is a standing breach until a Part V basis is established.$dg$, $dg$Build the transfer inventory first, then assess each flow under section 31 or 32.$dg$, $dg$Build an inventory of all cross-border personal data transfers$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Inventory$dg$, $dg$Transfer Assessment$dg$, $dg$Cloud Hosting Register$dg$]::text[], true, 9) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_