insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-014-001$dg$, $dg$REQ-014-1$dg$, $dg$III$dg$, $dg$14$dg$, $dg$14(1)$dg$, NULL, $dg$Section 14(1)$dg$, $dg$A person shall not collect or process personal data without being registered as a data controller or a data processor under this Act.$dg$, $dg$Registration held before any collection or processing$dg$, $dg$The organisation holds a current registration as a data controller or data processor covering all of its collection and processing of personal data.$dg$, $dg$Is your organisation registered with the Personal Data Protection Commission as a data controller or data processor?$dg$, $dg$Registration is a precondition to collecting or processing personal data at all. Processing without it is a standing breach regardless of how well everything else is run.$dg$, $dg$Confirm which capacity applies - controller, processor, or both for different activities - and that the registration on file covers all of them. Keep the certificate accessible.$dg$, $dg$A valid certificate of registration is held, covers every capacity in which the organisation acts, and has not expired.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 14(1) is an absolute prohibition on processing without registration, and section 19 makes contravention of this Part an offence.$dg$, $dg$Stop or pause new collection where feasible and apply to the Commission for registration immediately. Take legal advice on processing already under way.$dg$, $dg$Obtain registration with the Personal Data Protection Commission$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 19 provides that contravention of this Part is an offence punishable under section 63 (fine of not less than TZS 100,000 and not exceeding TZS 5,000,000, or imprisonment not exceeding five years, or both). Section 21 deems public institutions registered.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Certificate of Registration$dg$, $dg$Registration Application$dg$, $dg$Commission Correspondence$dg$]::text[], true, 10) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-014-002$dg$, $dg$REQ-014-2$dg$, $dg$III$dg$, $dg$14$dg$, $dg$14(2)$dg$, NULL, $dg$Section 14(2)$dg$, $dg$A person who intends to collect or process personal data shall apply to the Commission for registration.$dg$, $dg$Registration application submitted before intended processing$dg$, $dg$Before starting any new collection or processing that falls outside an existing registration, an application is made to the Commission.$dg$, $dg$When you plan a new activity involving personal data that your registration does not already cover, do you apply to the Commission first?$dg$, $dg$The duty attaches to the intention to collect or process, so the application belongs at the planning stage rather than after go-live.$dg$, $dg$Add a registration check to the intake process for new products, systems and vendors. The Commission decides within a period specified in the regulations under section 14(3).$dg$, $dg$A documented gate in the change or project process that checks registration coverage before processing begins.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. New processing launched outside the scope of an existing registration reintroduces the section 14(1) breach.$dg$, $dg$Insert a registration coverage check into the project and vendor onboarding gates.$dg$, $dg$Add a PDPA registration coverage check to the new-processing intake gate$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$Section 14(3) leaves the decision period to the regulations. Section 14(5) requires the Commission to give written reasons for a rejection.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Registration Application$dg$, $dg$Project Intake Checklist$dg$, $dg$Change Approval Record$dg$]::text[], true, 11) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-014-003$dg$, $dg$REQ-014-4$dg$, $dg$III$dg$, $dg$14$dg$, $dg$14(4)$dg$, NULL, $dg$Section 14(4)$dg$, $dg$The Commission shall issue a certificate of registration to the data controller or data processor who has fulfilled the prescribed requirements and registered under this section.$dg$, $dg$Certificate of registration retained and retrievable$dg$, $dg$The certificate of registration issued by the Commission is retained, its expiry date is recorded, and it can be produced on request.$dg$, $dg$Do you hold your certificate of registration, and can you produce it and state its expiry date?$dg$, $dg$The certificate is the document that proves registration to the Commission, to customers and to counterparties.$dg$, $dg$Store the certificate in the evidence repository, record the issue and expiry dates, and set a renewal reminder.$dg$, $dg$Certificate on file with issue and expiry dates recorded and a renewal reminder set.$dg$, $dg$DOCUMENT_REQUIRED$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The certificate itself is issued by the Commission; the risk here is loss of proof and missed renewal rather than unlawful processing.$dg$, $dg$Request a copy from the Commission if mislaid, then file it and diarise the expiry.$dg$, $dg$File the certificate of registration and record its expiry date$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[]::text[], ARRAY[$dg$Certificate of Registration$dg$]::text[], true, 12) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-015-001$dg$, $dg$REQ-015-3$dg$, $dg$III$dg$, $dg$15$dg$, $dg$15(3)$dg$, NULL, $dg$Section 15(3)$dg$, $dg$A data controller or data processor may, at any time, apply to the Commission to update or change any particulars in the register.$dg$, $dg$Registered particulars kept current$dg$, $dg$When registered particulars change - contact details, the nature of processing, the responsible officer - an application to update the register is made.$dg$, $dg$When the details you gave the Commission at registration change, do you apply to have the register updated?$dg$, $dg$The register is how the Commission reaches you, including with an investigation or enforcement notice. Stale details can turn a small issue into a missed deadline.$dg$, $dg$Assign an owner for registration data and review the registered particulars at least annually and on any material change of business.$dg$, $dg$An owner is named, and there is a record of the last review of registered particulars.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Out-of-date particulars impede regulatory contact and undermine the credibility of the registration.$dg$, $dg$Name an owner and run an annual review of registered particulars.$dg$, $dg$Assign ownership and review registered particulars annually$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$ACT_DERIVED. Section 15(3) is permissive - the Act says the controller or processor may apply to update. DataGuard derives the duty to keep particulars current from section 15(3) read with section 19, which makes furnishing false or misleading information during registration or renewal an offence. It adds no new legal obligation. Section 15(2) leaves the required particulars to the regulations.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Register Update Application$dg$, $dg$Registration Review Record$dg$, $dg$Commission Correspondence$dg$]::text[], true, 13) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-015-002$dg$, $dg$REQ-015-3$dg$, $dg$III$dg$, $dg$15$dg$, $dg$15(2)$dg$, NULL, $dg$Sections 15(2) and 17$dg$, $dg$The register shall contain such particulars as may be prescribed in the regulations. Subject to prescribed procedures and payment of prescribed fees, the Commission may permit any person to inspect and extract any entry in the register.$dg$, $dg$Awareness that registered particulars are publicly inspectable$dg$, $dg$The organisation understands that entries in the register may be inspected and extracted by any person the Commission permits, and reviews its entries accordingly.$dg$, $dg$Are you aware that the details recorded about you in the Commission register can be inspected by others, and have you reviewed those details with that in mind?$dg$, $dg$Anything in the register may end up in front of a competitor, a journalist or a customer. It is worth knowing what is there.$dg$, $dg$Review the registered particulars for accuracy and for anything you would not want disclosed, and raise any concern with the Commission rather than omitting required information.$dg$, $dg$Registered particulars have been reviewed on the assumption that they are inspectable.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$WEAK$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$LOW$dg$, $dg$DataGuard default risk classification: Low. Section 17 is a power of the Commission, not an obligation on the organisation. This control exists to prompt awareness, not to test compliance.$dg$, $dg$Review your register entry once and record that you have done so.$dg$, $dg$Review the register entry on the basis that it is publicly inspectable$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$INTERPRETATION$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$INTERPRETATION. Section 17 addresses the Commission, not the data controller. The particulars in the register are to be prescribed by regulations that are not reproduced in the Act.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Registration Review Record$dg$]::text[], false, 14) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-016-001$dg$, $dg$REQ-016-1$dg$, $dg$III$dg$, $dg$16$dg$, $dg$16(1)$dg$, NULL, $dg$Section 16(1)$dg$, $dg$The period of registration shall be five years from the date of issuance of certificate of registration.$dg$, $dg$Registration expiry tracked$dg$, $dg$The five year expiry date of the registration is recorded and monitored so that the organisation never processes on a lapsed registration.$dg$, $dg$Do you know the date your registration expires, and is that date being tracked?$dg$, $dg$Registration runs for five years. If it lapses, you are back in breach of the prohibition in section 14(1) without anything else having changed.$dg$, $dg$Record the certificate issue date, calculate the five year expiry, and set reminders at twelve, six and four months before expiry.$dg$, $dg$Expiry date recorded with automated reminders configured.$dg$, $dg$DATE$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. A lapsed registration reinstates the section 14(1) prohibition, and lapse through inattention is a common and entirely avoidable failure.$dg$, $dg$Record the expiry date in the compliance calendar and configure reminders.$dg$, $dg$Record the registration expiry date and configure renewal reminders$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[]::text[], ARRAY[$dg$Certificate of Registration$dg$, $dg$Compliance Calendar$dg$]::text[], true, 15) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-016-002$dg$, $dg$REQ-016-2$dg$, $dg$III$dg$, $dg$16$dg$, $dg$16(2)$dg$, NULL, $dg$Section 16(2)$dg$, $dg$The application for renewal shall be submitted within the period of three months before expiry in the manner prescribed in the regulations.$dg$, $dg$Renewal submitted within the three month window$dg$, $dg$The renewal application is submitted within the three month period before the registration expires, in the manner prescribed by the regulations.$dg$, $dg$Do you submit your renewal application during the three months before your registration expires?$dg$, $dg$The Act sets a specific window. Applying too late risks a gap in registration; the manner of applying is set by regulations.$dg$, $dg$Diarise the start of the three month window, not just the expiry date. Confirm the prescribed manner of renewal against the current regulations before submitting.$dg$, $dg$Renewal is submitted inside the statutory window with proof of submission retained.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Missing the renewal window can lead to expiry of the registration and a resulting prohibition on processing.$dg$, $dg$Add the renewal window opening date to the compliance calendar with an owner.$dg$, $dg$Diarise the opening of the three month registration renewal window$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$The manner of renewal is left to the regulations and is not specified in the Act.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Renewal Application$dg$, $dg$Proof of Submission$dg$, $dg$Compliance Calendar$dg$]::text[], true, 16) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_