insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-018-001$dg$, $dg$REQ-018-1$dg$, $dg$III$dg$, $dg$18$dg$, NULL, NULL, $dg$Section 18$dg$, $dg$The Commission may deregister any registration under this Act as may be prescribed in the regulations.$dg$, $dg$Response to deregistration by the Commission$dg$, $dg$The organisation has a defined internal response if the Commission deregisters it, recognising that the section 14(1) prohibition then applies again.$dg$, $dg$Do you have a plan for what happens to your processing if the Commission deregisters you?$dg$, $dg$Deregistration removes the basis on which you may collect or process personal data at all. It needs an escalation path decided in advance, not invented on the day.$dg$, $dg$Name an executive owner, define the escalation path, and identify which processing would have to stop. The grounds and procedure for deregistration are left to the regulations.$dg$, $dg$A documented escalation procedure naming an owner and the processing that would be suspended.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Deregistration is a low-likelihood but very high-impact event, and the Act gives no notice period on the face of section 18.$dg$, $dg$Add deregistration to the escalation procedure with a named executive owner.$dg$, $dg$Define an internal response procedure for deregistration by the Commission$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$INTERPRETATION$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$INTERPRETATION. Section 18 confers a power on the Commission and imposes no obligation on the organisation. The consequence for the organisation is derived from section 14(1). Grounds and procedure are left to the regulations.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Incident and Escalation Procedure$dg$, $dg$Business Continuity Plan$dg$]::text[], false, 17) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-019-001$dg$, $dg$REQ-019-1$dg$, $dg$III$dg$, $dg$19$dg$, NULL, NULL, $dg$Section 19$dg$, $dg$Any person who contravenes the provisions of this Part or furnishes false or misleading information during registration or renewal, commits an offence and upon conviction shall be liable for a penalty specified under section 63.$dg$, $dg$Accuracy of information given at registration and renewal$dg$, $dg$Information submitted to the Commission at registration and renewal is verified for accuracy and completeness before submission, and a copy is retained.$dg$, $dg$Is the information you give the Commission at registration and renewal checked for accuracy before you send it, and do you keep a copy?$dg$, $dg$Furnishing false or misleading information at registration or renewal is a criminal offence under the Act, not merely an administrative slip.$dg$, $dg$Require a named reviewer to verify the submission against source records before it is sent, and retain the submitted version alongside the supporting records.$dg$, $dg$A retained copy of each submission with evidence of pre-submission review by a named person.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. This provision carries criminal liability under section 63 and is entirely within the organisation control to avoid.$dg$, $dg$Introduce a documented review and sign-off step before any submission to the Commission.$dg$, $dg$Introduce pre-submission review and retention for Commission filings$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 63 provides a fine of not less than TZS 100,000 and not exceeding TZS 5,000,000, or imprisonment for a term not exceeding five years, or both. This penalty applies to section 19 because section 19 expressly refers to it.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Registration Application$dg$, $dg$Renewal Application$dg$, $dg$Pre-submission Review Record$dg$]::text[], true, 18) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-020-001$dg$, $dg$REQ-020-1$dg$, $dg$III$dg$, $dg$20$dg$, NULL, NULL, $dg$Section 20$dg$, $dg$Any person who is aggrieved by the decision of the Commission under this Part may appeal in writing to the Minister.$dg$, $dg$Awareness of the registration appeal route$dg$, $dg$The organisation knows that a decision of the Commission under Part III may be appealed in writing to the Minister, and who internally would handle such an appeal.$dg$, $dg$If the Commission refused or cancelled your registration, do you know that you can appeal in writing to the Minister and who would handle it?$dg$, $dg$Appeal rights are only useful if somebody knows they exist at the moment the decision lands.$dg$, $dg$Record the appeal route in the compliance procedure with a named owner. The Act does not state a time limit for this appeal on the face of section 20 - confirm any deadline in the regulations or with counsel.$dg$, $dg$The appeal route and internal owner are documented in the compliance procedure.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$WEAK$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$LOW$dg$, $dg$DataGuard default risk classification: Low. This is a right rather than a duty. It is recorded so the organisation does not lose it through unawareness.$dg$, $dg$Add the section 20 appeal route and its owner to the compliance procedure.$dg$, $dg$Document the section 20 appeal route to the Minister$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: section 20 does not state a period within which the appeal to the Minister must be lodged. Any internal deadline is INTERPRETATION until confirmed by regulations or advice.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Compliance Procedure$dg$, $dg$Regulatory Escalation Matrix$dg$]::text[], false, 19) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-021-001$dg$, $dg$REQ-021-1$dg$, $dg$III$dg$, $dg$21$dg$, NULL, NULL, $dg$Section 21$dg$, $dg$Immediately after commencement of this Act, public institutions which collect and process personal data shall be deemed as registered with the Commission under this Act and shall be required to comply with the provisions of this Act.$dg$, $dg$Public institution deemed registration and full compliance$dg$, $dg$A public institution that collects and processes personal data recognises that it is deemed registered and that it remains bound by every other provision of the Act.$dg$, $dg$If you are a public institution, do you understand that you are treated as already registered but still have to comply with everything else in the Act?$dg$, $dg$Deemed registration removes the application step. It does not reduce any other obligation, and the assumption that it does is a common misreading.$dg$, $dg$Record the basis of deemed registration in the compliance file and confirm with the Commission what particulars, if any, it expects the institution to supply.$dg$, $dg$The deemed registration basis is documented and the institution is assessed against the full control matrix.$dg$, $dg$YES_NO$dg$, $dg$ROLE_SPECIFIC$dg$, $dg$Is your organisation a public institution?$dg$, $dg$PUBLIC_INSTITUTION$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$REGISTRATION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The registration risk is removed by statute, but the misconception that deemed registration implies broader exemption is a real and material risk.$dg$, $dg$Document the deemed registration basis and run the full assessment regardless.$dg$, $dg$Document deemed registration status and complete the full PDPA assessment$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not define public institution for this purpose, nor state what particulars a deemed-registered institution must supply for the register under section 15.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Compliance File Note$dg$, $dg$Commission Correspondence$dg$, $dg$Establishing Instrument$dg$]::text[], true, 20) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-022-001$dg$, $dg$REQ-022-1$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$22(1)$dg$, NULL, $dg$Section 22(1)(a)-(c)$dg$, $dg$Part IV applies to any collection and processing performed wholly or partly by manual or automated means; to processing carried out in the performance of activities of a controller domiciled in the United Republic or in a territory where the laws of the United Republic apply by virtue of international public law; and to processing by a controller or processor not domiciled in the United Republic where the processing takes place in the United Republic and is not for mere transit through Tanzania.$dg$, $dg$Part IV scope assessment including manual records and non-domiciled processing$dg$, $dg$The organisation has assessed which of its processing falls within section 22(1), expressly including paper and other manual records, and processing carried out in Tanzania by entities domiciled elsewhere.$dg$, $dg$Have you identified all processing that falls under Part IV, including paper records and any processing you carry out in Tanzania from a business based abroad?$dg$, $dg$Paper files and offshore group entities are the two things most often left out of a data inventory, and section 22(1) puts both squarely in scope.$dg$, $dg$Extend the processing inventory to manual filing systems. For non-domiciled entities, determine where the processing physically takes place, and note that mere transit of data through Tanzania is excluded.$dg$, $dg$A processing inventory that covers automated and manual processing and records the domicile and processing location for each activity.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Processing left outside the scope assessment is processing that nobody is controlling.$dg$, $dg$Extend the inventory to manual records and confirm the processing location for each non-domiciled entity.$dg$, $dg$Extend the processing inventory to manual records and non-domiciled processing$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 22(1)(c) expressly excludes processing for the purposes of mere transit of personal data through Tanzania to another country.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Processing Register$dg$, $dg$Scoping Statement$dg$, $dg$Records Inventory$dg$]::text[], true, 21) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-022-002$dg$, $dg$REQ-022-2$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$22(2)$dg$, $dg$(a)$dg$, $dg$Section 22(2)(a)$dg$, $dg$A data controller shall collect personal data if the personal data is collected for a lawful purpose related to a function of the data controller.$dg$, $dg$Collection tied to a lawful purpose related to a function of the controller$dg$, $dg$Every collection of personal data is tied to a lawful purpose that relates to an actual function of the organisation.$dg$, $dg$Is every collection of personal data linked to a lawful purpose that relates to something your organisation actually does?$dg$, $dg$The Act does not allow collection just because the data might be useful one day. The purpose must connect to a function you actually perform.$dg$, $dg$For each collection point in the register, record the organisational function it serves alongside the purpose. Challenge any entry where the function cannot be named.$dg$, $dg$Each collection activity in the register names both a lawful purpose and the organisational function it supports.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$LAWFULNESS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Collection with no lawful purpose related to a function of the controller is unlawful at the point of collection and cannot be cured later.$dg$, $dg$Add a function column to the processing register and complete it for every collection.$dg$, $dg$Map every collection activity to a lawful purpose and an organisational function$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Processing Register$dg$, $dg$Purpose and Function Mapping$dg$, $dg$Privacy Notice$dg$]::text[], true, 22) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-022-003$dg$, $dg$REQ-022-2$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$22(2)$dg$, $dg$(b)$dg$, $dg$Section 22(2)(b)$dg$, $dg$A data controller shall collect personal data if the collection of the data is necessary or incidental or directly related to the lawful purpose.$dg$, $dg$Necessity test applied at the point of collection$dg$, $dg$Each data element collected is tested as necessary, incidental to, or directly related to the lawful purpose before collection begins.$dg$, $dg$Have you checked that each piece of information you collect is necessary for, incidental to, or directly related to the purpose?$dg$, $dg$This is the statutory version of only collect what you need, and it applies element by element rather than form by form.$dg$, $dg$Run a field-level necessity test when a form or integration is designed or changed, and record the outcome. Note the test is broader than strict necessity - incidental and directly related also qualify.$dg$, $dg$A recorded necessity assessment per collection point, refreshed when the form or feed changes.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$DATA_MINIMISATION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The section 22(2)(b) test is broader than strict necessity, so failures tend to be at the margin, but they are cumulative.$dg$, $dg$Add a field-level necessity test to the design review for forms and integrations.$dg$, $dg$Apply and record a necessity test at each collection point$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Necessity Assessment$dg$, $dg$Data Minimisation Review$dg$, $dg$Form and Screen Inventory$dg$]::text[], true, 23) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-022-004$dg$, $dg$REQ-022-3$dg$, $dg$IV$dg$, $dg$22$dg$, $dg$22(3)$dg$, NULL, $dg$Section 22(3)$dg$, $dg$A data controller shall not collect personal data by unlawful means.$dg$, $dg$No collection by unlawful means$dg$, $dg$Collection methods are lawful - no covert acquisition, scraping in breach of law, deception, or purchase of data obtained unlawfully.$dg$, $dg$Are you satisfied that none of your methods of obtaining personal data are unlawful, including data bought or scraped from elsewhere?$dg$, $dg$Data acquired unlawfully stays unlawful no matter how carefully it is handled afterwards, and section 60 makes some acquisition routes a criminal offence.$dg$, $dg$Screen third party data sources and list acquisition methods. Require the supplier to state how the data was obtained and on what basis it may be passed on.$dg$, $dg$A documented review of acquisition methods and third party data sources with a lawfulness conclusion for each.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$LAWFULNESS$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Unlawful acquisition taints every subsequent use and engages the criminal offences in section 60, particularly obtaining personal data without the authority of the controller by whom it is kept.$dg$, $dg$Inventory third party data sources, obtain provenance declarations, and stop any acquisition route that cannot be justified.$dg$, $dg$Review acquisition methods and third party data sources for lawfulness$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 60(3) makes it an offence to obtain personal data without the prior authority of the data controller or data processor by whom the personal data is kept.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Source Register$dg$, $dg$Supplier Data Provenance Declaration$dg$, $dg$Data Protection Policy$dg$]::text[], true, 24) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-023-001$dg$, $dg$REQ-023-1$dg$, $dg$IV$dg$, $dg$23$dg$, $dg$23(1)$dg$, NULL, $dg$Section 23(1)$dg$, $dg$Subject to subsection (3), a data controller shall collect personal data directly from the data subject concerned.$dg$, $dg$Collection directly from the data subject$dg$, $dg$Personal data is collected directly from the individual concerned unless one of the section 23(3) exceptions applies and has been recorded.$dg$, $dg$Do you collect personal data directly from the person it is about, rather than from someone else?$dg$, $dg$Direct collection is the default under the Act. Indirect collection is allowed only in defined circumstances, and you must be able to point to which one.$dg$, $dg$Record the source for each collection activity. Where the source is not the data subject, link the entry to the specific section 23(3) exception relied on.$dg$, $dg$The processing register records the source of each collection, with an exception cited wherever the source is not the data subject.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$COLLECTION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Indirect collection without an applicable exception breaches section 23(1) and usually also undermines the notification duty in section 23(2).$dg$, $dg$Add a source field to the processing register and reconcile every indirect collection to a section 23(3) exception.$dg$, $dg$Record the source of collection for every processing activity$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Processing Register$dg$, $dg$Data Source Register$dg$, $dg$Collection Procedure$dg$]::text[], true, 25) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-023-002$dg$, $dg$REQ-023-2$dg$, $dg$IV$dg$, $dg$23$dg$, $dg$23(2)$dg$, $dg$(a)-(c)$dg$, $dg$Section 23(2)(a)-(c)$dg$, $dg$Before collecting data, a data controller shall ensure that the data subject is aware of the purposes for which the personal data is collected, the fact that collection is for authorised purposes, and any intended recipients of the personal data.$dg$, $dg$Pre-collection notice - purposes, authorised purposes and intended recipients$dg$, $dg$Before any collection, the data subject is made aware of the purposes, the fact that collection is for authorised purposes, and the intended recipients of the data.$dg$, $dg$Before you collect someone information, do you tell them why you are collecting it and who you intend to share it with?$dg$, $dg$The Act requires awareness before collection, not afterwards. All three elements must be covered, and intended recipients is the one most often left out.$dg$, $dg$Audit every collection point - forms, call scripts, apps, contracts - and confirm the notice covers all three elements and is presented before the data is captured. Keep dated versions of each notice.$dg$, $dg$Every collection point carries a pre-collection notice covering purposes, authorised purposes and intended recipients, with versions retained.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$TRANSPARENCY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. This is an express, testable duty that applies at every collection point and is highly visible to data subjects and to the Commission.$dg$, $dg$Inventory collection points, then update each notice to cover the three statutory elements and place it before the point of capture.$dg$, $dg$Audit all collection points for a compliant pre-collection notice$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 23(2) requires that the data subject is aware. The Act does not prescribe a form or medium for the notice.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Privacy Notice$dg$, $dg$Collection Point Notice Inventory$dg$, $dg$Call Script$dg$, $dg$Consent Record$dg$]::text[], true, 26) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-023-003$dg$, $dg$REQ-023-3$dg$, $dg$IV$dg$, $dg$23$dg$, $dg$23(3)$dg$, $dg$(a)-(e)$dg$, $dg$Section 23(3)(a)-(e)$dg$, $dg$A data controller is not obliged to collect directly from the data subject where the personal data is publicly available; the data subject authorises collection from a third party; compliance is not reasonably practicable in the circumstances; non-compliance is necessary for compliance with other written laws; or compliance would prejudice the lawful purpose of the collection.$dg$, $dg$Documented reliance on exceptions to direct collection$dg$, $dg$Where data is collected indirectly, the specific section 23(3) exception relied on is identified and recorded before collection.$dg$, $dg$Where you collect personal data from someone other than the person it is about, have you recorded which legal exception allows that?$dg$, $dg$The exceptions are narrow and specific. Recording which one applies at the time is far easier than reconstructing it during an investigation.$dg$, $dg$Give each indirect collection an exception code (a to e) with a short justification and the date the assessment was made. Reassess when the collection changes.$dg$, $dg$Every indirect collection has a recorded exception, justification and assessment date.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you collect any personal data from a source other than the person it is about?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$COLLECTION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The exceptions are lawful routes, so the risk lies in relying on one without analysis rather than in indirect collection itself.$dg$, $dg$Create an exception register and complete it for each indirect collection, taking advice on borderline cases.$dg$, $dg$Record the section 23(3) exception relied on for each indirect collection$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$INTERPRETATION: not reasonably practicable and would prejudice the lawful purpose are open-textured tests. The Act gives no further criteria.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Exception Register$dg$, $dg$Data Source Register$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 27) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-024-001$dg$, $dg$REQ-024-1$dg$, $dg$IV$dg$, $dg$24$dg$, NULL, NULL, $dg$Section 24$dg$, $dg$Subject to the purpose for which the personal data are intended to be used, a data controller who holds personal data shall not use that personal data without taking such steps as are, in the circumstances, reasonable to ensure that the data is complete, accurate, relevant and not misleading.$dg$, $dg$Reasonable steps to verify data before use$dg$, $dg$Before personal data is used, reasonable steps are taken to confirm it is complete, accurate, relevant and not misleading, judged against the intended use.$dg$, $dg$Before you use personal information to make a decision or take an action, do you take reasonable steps to check it is complete, accurate, relevant and not misleading?$dg$, $dg$Section 24 is a check at the point of use, not just a general data quality aspiration. What counts as reasonable scales with how much the decision matters to the person.$dg$, $dg$Define verification steps proportionate to the consequence of the use - light touch for a mailing list, substantive for a credit or employment decision. Record what the steps are for each high-impact use.$dg$, $dg$Documented verification steps for each high-impact use of personal data, with evidence they are applied.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$DATA_QUALITY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Use of inaccurate data is the most direct route to demonstrable damage under section 37 and to a Commission order under section 38.$dg$, $dg$Identify the uses where inaccuracy would harm someone, and design proportionate verification into those processes first.$dg$, $dg$Define and implement pre-use verification for high-impact uses of personal data$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$INTERPRETATION: the Act uses the standard of steps that are reasonable in the circumstances and does not prescribe specific verification methods.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Quality Procedure$dg$, $dg$Verification Control Design$dg$, $dg$System Validation Rules$dg$, $dg$Audit Report$dg$]::text[], true, 28) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-025-001$dg$, $dg$REQ-025-1$dg$, $dg$IV$dg$, $dg$25$dg$, $dg$25(1)$dg$, NULL, $dg$Section 25(1)$dg$, $dg$Personal data collected under this Act shall be used for the intended purposes.$dg$, $dg$Use confined to the intended purpose$dg$, $dg$Personal data is used only for the purpose for which it was collected, unless a section 25(2) ground applies.$dg$, $dg$Do you use personal data only for the purpose you originally collected it for?$dg$, $dg$Reusing data for a new purpose is one of the easiest things to do accidentally, particularly when analytics or marketing teams gain access to operational systems.$dg$, $dg$Restrict system access by purpose where the platform allows. Require a documented secondary-use approval before data collected for one purpose is used for another.$dg$, $dg$Purpose is recorded per dataset and a secondary-use approval process exists and is used.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$PURPOSE_LIMITATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Section 26 makes the section 25 grounds the gateway for disclosure as well as use, so a failure here propagates.$dg$, $dg$Introduce a secondary-use approval step and record the purpose against each dataset.$dg$, $dg$Implement a secondary-use approval process for personal data$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Processing Register$dg$, $dg$Secondary Use Approval Record$dg$, $dg$Access Control Procedure$dg$]::text[], true, 29) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-025-002$dg$, $dg$REQ-025-2$dg$, $dg$IV$dg$, $dg$25$dg$, $dg$25(2)$dg$, $dg$(a)-(f)$dg$, $dg$Section 25(2)(a)-(f)$dg$, $dg$Personal data held for a particular purpose may be used for another purpose only where the data subject authorises that other use; the other use is authorised or required by law; the other purpose is directly related to the purpose of collection; the data is used in a non-identifying form or for statistical or research purposes not published in identifying form; the controller believes on reasonable grounds that the use is necessary to prevent or lessen a serious and imminent threat to life, health or public health or safety; or the use is necessary for compliance with the laws.$dg$, $dg$Secondary use limited to a recorded section 25(2) ground$dg$, $dg$Any use of personal data for a purpose other than that of collection is mapped to one of the six grounds in section 25(2) and recorded before the use begins.$dg$, $dg$When you use personal data for a new purpose, do you record which of the permitted legal grounds allows it?$dg$, $dg$These six grounds are exhaustive. If a proposed new use does not fit one of them, it is not permitted, however commercially sensible it seems.$dg$, $dg$Build a secondary-use assessment template listing grounds (a) to (f). Require the requester to select a ground and give a justification, and require sign-off by the data protection officer.$dg$, $dg$A secondary use register recording the ground, justification, approver and date for each approved secondary use.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you use any personal data for a purpose other than the one it was originally collected for?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$PURPOSE_LIMITATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The grounds are exhaustive, and an unrecorded secondary use is indefensible during a section 39 investigation.$dg$, $dg$Create the secondary use register, populate it for existing secondary uses, and stop any use that fits no ground.$dg$, $dg$Create a secondary use register mapped to the section 25(2) grounds$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 25(2)(d)(ii) permits statistical or research use provided the results are not published in a form that could reasonably be expected to identify the data subject.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Secondary Use Register$dg$, $dg$Purpose Compatibility Assessment$dg$, $dg$DPO Approval Record$dg$, $dg$Consent Record$dg$]::text[], true, 30) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-026-001$dg$, $dg$REQ-026-1$dg$, $dg$IV$dg$, $dg$26$dg$, NULL, NULL, $dg$Section 26$dg$, $dg$Where a data controller holds personal data, he shall not disclose the personal data to a person other than the data subject except in the circumstances specified under section 25.$dg$, $dg$Disclosure restricted to the section 25 circumstances$dg$, $dg$Personal data is disclosed to third parties only where one of the circumstances in section 25 applies, and each disclosure route is recorded.$dg$, $dg$Do you share personal data with anyone other than the person it is about only where the law allows, and do you keep a record of who you share it with?$dg$, $dg$Disclosure is the point at which you lose control of the data. Section 26 ties every disclosure back to the section 25 grounds, and unlawful disclosure is a criminal offence under section 60.$dg$, $dg$Maintain a disclosure register listing each recipient, the data disclosed, the section 25 ground and the safeguards in place. Include routine feeds, regulatory reporting and group sharing.$dg$, $dg$A complete disclosure register with a recorded section 25 ground for every recipient.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DISCLOSURE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 60(1) makes disclosure incompatible with the purpose of collection a criminal offence carrying a fine of up to TZS 5,000,000,000 for a company or corporation.$dg$, $dg$Build the disclosure register, assess each existing route against section 25, and terminate or re-paper any route without a ground.$dg$, $dg$Build a disclosure register mapping every recipient to a section 25 ground$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 60(6) sets the penalty for unlawful disclosure offences: for an individual, a fine of not less than TZS 100,000 and not exceeding TZS 20,000,000 or imprisonment not exceeding ten years or both; for a company or corporation, a fine of not less than TZS 1,000,000 and not exceeding TZS 5,000,000,000.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Disclosure Register$dg$, $dg$Data Sharing Agreement$dg$, $dg$Processor Agreement$dg$, $dg$Secondary Use Register$dg$]::text[], true, 31) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-001$dg$, $dg$REQ-027-1$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(1)$dg$, NULL, $dg$Section 27(1)$dg$, $dg$A data controller and his representatives shall ensure that personal data is protected by such security safeguards as are reasonable in the circumstances necessary for the protection of personal data.$dg$, $dg$Reasonable security safeguards programme$dg$, $dg$A documented set of security safeguards protects personal data, and their reasonableness in the circumstances has been assessed and recorded.$dg$, $dg$Do you have reasonable safeguards in place that protect personal data, and have you written down why they are the right ones for your circumstances?$dg$, $dg$This is the umbrella security duty in the Act. The standard is what is reasonable in your circumstances, so the reasoning behind your choices matters as much as the controls themselves.$dg$, $dg$Maintain an approved security policy and a register of implemented safeguards. Record the assessment of reasonableness against the four factors in section 27(2), which are assessed separately by controls PDPA-027-007 to PDPA-027-010.$dg$, $dg$An approved security policy, a safeguards register, and a documented reasonableness assessment reviewed at least annually.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$SECURITY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 27(1) is the central security obligation of the Act and underpins the section 5(g) principle and the section 27(5) breach duty.$dg$, $dg$Approve a security policy, inventory current safeguards, and document the reasonableness assessment against the section 27(2) factors.$dg$, $dg$Establish and document reasonable security safeguards for personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(1) by its terms binds the data controller and his representatives. Section 5(g) applies the security principle to data processors as well, and section 27(4) makes the processor responsible for compliance with security standards.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Security Policy$dg$, $dg$Safeguards Register$dg$, $dg$Risk Assessment$dg$, $dg$Audit Report$dg$]::text[], true, 32) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-002$dg$, $dg$REQ-027-1$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(1)$dg$, NULL, $dg$Section 27(1)$dg$, $dg$A data controller and his representatives shall ensure that personal data is protected by such security safeguards as are reasonable in the circumstances necessary for the protection of personal data against negligent loss.$dg$, $dg$Protection against negligent loss$dg$, $dg$Specific technical and organisational safeguards address the risk of negligent loss of personal data, and their operation is evidenced.$dg$, $dg$Are you protected against personal data being lost through carelessness - for example lost laptops, lost files, or failed backups?$dg$, $dg$Section 27(1) names negligent loss as a distinct harm to protect against. Treating it separately makes it clear whether you actually have a control for it rather than a general assurance that security is handled.$dg$, $dg$Cover device encryption and asset tracking, backup and restore testing, physical file custody, and secure transfer of media. Test restores rather than assuming backups work.$dg$, $dg$Named safeguards addressing negligent loss are implemented, owned, and evidenced by operating records rather than by policy text alone.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SECURITY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Negligent loss is expressly named in section 27(1) and is the most frequent cause of reportable incidents.$dg$, $dg$Identify the systems holding personal data, select proportionate safeguards against negligent loss, assign an owner, and produce operating evidence.$dg$, $dg$Implement and evidence controls against negligent loss of personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(1) lists negligent loss and unauthorised destruction, alteration, access and processing as separate harms. DataGuard maps each to its own control so that partial coverage is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Backup and Restore Test Records$dg$, $dg$Asset Register$dg$, $dg$Device Encryption Report$dg$, $dg$Security Policy$dg$]::text[], true, 33) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-003$dg$, $dg$REQ-027-1$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(1)$dg$, NULL, $dg$Section 27(1)$dg$, $dg$A data controller and his representatives shall ensure that personal data is protected by such security safeguards as are reasonable in the circumstances necessary for the protection of personal data against unauthorised destruction.$dg$, $dg$Protection against unauthorised destruction$dg$, $dg$Specific technical and organisational safeguards address the risk of unauthorised destruction of personal data, and their operation is evidenced.$dg$, $dg$Are you protected against personal data being destroyed or deleted by someone who should not be doing that?$dg$, $dg$Section 27(1) names unauthorised destruction as a distinct harm to protect against. Treating it separately makes it clear whether you actually have a control for it rather than a general assurance that security is handled.$dg$, $dg$Restrict delete and purge rights, log deletions, keep immutable or offline backup copies, and require dual authorisation for bulk deletion.$dg$, $dg$Named safeguards addressing unauthorised destruction are implemented, owned, and evidenced by operating records rather than by policy text alone.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SECURITY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Unauthorised destruction is expressly named in section 27(1) and is separately criminalised by section 61.$dg$, $dg$Identify the systems holding personal data, select proportionate safeguards against unauthorised destruction, assign an owner, and produce operating evidence.$dg$, $dg$Restrict and log deletion rights over personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(1) lists negligent loss and unauthorised destruction, alteration, access and processing as separate harms. DataGuard maps each to its own control so that partial coverage is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Access Control Procedure$dg$, $dg$Deletion Authorisation Records$dg$, $dg$Backup Policy$dg$, $dg$Audit Log Configuration$dg$]::text[], true, 34) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-004$dg$, $dg$REQ-027-1$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(1)$dg$, NULL, $dg$Section 27(1)$dg$, $dg$A data controller and his representatives shall ensure that personal data is protected by such security safeguards as are reasonable in the circumstances necessary for the protection of personal data against unauthorised alteration.$dg$, $dg$Protection against unauthorised alteration$dg$, $dg$Specific technical and organisational safeguards address the risk of unauthorised alteration of personal data, and their operation is evidenced.$dg$, $dg$Are you protected against personal data being changed by someone who is not authorised to change it?$dg$, $dg$Section 27(1) names unauthorised alteration as a distinct harm to protect against. Treating it separately makes it clear whether you actually have a control for it rather than a general assurance that security is handled.$dg$, $dg$Enforce write permissions by role, keep tamper-evident change logs, and reconcile critical fields periodically. This control also supports the section 29(2) duty to preserve pre-amendment records.$dg$, $dg$Named safeguards addressing unauthorised alteration are implemented, owned, and evidenced by operating records rather than by policy text alone.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SECURITY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Unauthorised alteration is expressly named in section 27(1), is criminalised by section 61, and silently corrupts the accuracy duties in sections 5(d) and 24.$dg$, $dg$Identify the systems holding personal data, select proportionate safeguards against unauthorised alteration, assign an owner, and produce operating evidence.$dg$, $dg$Enforce and log write access controls over personal data$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(1) lists negligent loss and unauthorised destruction, alteration, access and processing as separate harms. DataGuard maps each to its own control so that partial coverage is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Access Control Procedure$dg$, $dg$Change and Audit Logs$dg$, $dg$Segregation of Duties Matrix$dg$]::text[], true, 35) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-005$dg$, $dg$REQ-027-1$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(1)$dg$, NULL, $dg$Section 27(1)$dg$, $dg$A data controller and his representatives shall ensure that personal data is protected by such security safeguards as are reasonable in the circumstances necessary for the protection of personal data against unauthorised access.$dg$, $dg$Protection against unauthorised access$dg$, $dg$Specific technical and organisational safeguards address the risk of unauthorised access of personal data, and their operation is evidenced.$dg$, $dg$Are you protected against people seeing personal data when they have no business reason to see it?$dg$, $dg$Section 27(1) names unauthorised access as a distinct harm to protect against. Treating it separately makes it clear whether you actually have a control for it rather than a general assurance that security is handled.$dg$, $dg$Apply least privilege, review access periodically, enforce strong authentication, and log and monitor access to sensitive records.$dg$, $dg$Named safeguards addressing unauthorised access are implemented, owned, and evidenced by operating records rather than by policy text alone.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SECURITY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Unauthorised access is expressly named in section 27(1) and is the precondition for most unlawful disclosure offences under section 60.$dg$, $dg$Identify the systems holding personal data, select proportionate safeguards against unauthorised access, assign an owner, and produce operating evidence.$dg$, $dg$Implement least privilege and periodic access reviews for personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(1) lists negligent loss and unauthorised destruction, alteration, access and processing as separate harms. DataGuard maps each to its own control so that partial coverage is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Access Control Procedure$dg$, $dg$Access Review Records$dg$, $dg$Authentication Policy$dg$, $dg$Access Logs$dg$]::text[], true, 36) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
