insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-007$dg$, $dg$REQ-027-2A$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(2)$dg$, $dg$(a)$dg$, $dg$Section 27(2)(a)$dg$, $dg$Security measures shall ensure an appropriate level of security taking into account the state of technological advancement.$dg$, $dg$State of technological advancement considered$dg$, $dg$The organisation demonstrably weighs this statutory factor when selecting and reviewing security measures.$dg$, $dg$When you choose security measures, do you take account of what current technology makes possible - and revisit that as technology moves?$dg$, $dg$A measure that was appropriate five years ago may not be today. The Act builds this movement into the standard itself.$dg$, $dg$Record the technology baseline assumed by your security design, and review it on a set cycle or when a material change occurs, such as a cryptographic algorithm being deprecated.$dg$, $dg$A documented technology review cycle for security measures, with the last review dated.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SECURITY$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. This is a factor the Act requires you to weigh rather than a standalone safeguard, but neglecting it makes the whole programme drift out of date.$dg$, $dg$Incorporate this factor explicitly into the security risk assessment methodology and record the outcome.$dg$, $dg$Establish a periodic technology review of security measures$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(2) requires that the appropriate level of security take these factors into account. DataGuard assesses each factor separately so that a gap in any one of them is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Security Architecture Review$dg$, $dg$Technology Refresh Plan$dg$, $dg$Risk Assessment$dg$]::text[], true, 38) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-008$dg$, $dg$REQ-027-2A$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(2)$dg$, $dg$(a)$dg$, $dg$Section 27(2)(a)$dg$, $dg$Security measures shall ensure an appropriate level of security taking into account the cost of implementing the measures.$dg$, $dg$Cost of implementation considered$dg$, $dg$The organisation demonstrably weighs this statutory factor when selecting and reviewing security measures.$dg$, $dg$When you decide on security measures, do you record how you weighed their cost against the protection they give?$dg$, $dg$The Act expressly allows cost to be weighed. That works in your favour only if the reasoning is recorded at the time rather than argued after an incident.$dg$, $dg$Where a measure is rejected or deferred on cost grounds, record the decision, the residual risk accepted, who accepted it, and when it will be revisited.$dg$, $dg$A risk acceptance record for each security measure deferred or rejected on cost grounds.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SECURITY$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Cost is an express statutory factor. Undocumented cost-based decisions are the ones that look like neglect after the event.$dg$, $dg$Incorporate this factor explicitly into the security risk assessment methodology and record the outcome.$dg$, $dg$Document cost and residual risk decisions for security measures$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(2) requires that the appropriate level of security take these factors into account. DataGuard assesses each factor separately so that a gap in any one of them is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Risk Acceptance Record$dg$, $dg$Security Business Case$dg$, $dg$Risk Register$dg$]::text[], true, 39) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-009$dg$, $dg$REQ-027-2B$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(2)$dg$, $dg$(b)$dg$, $dg$Section 27(2)(b)$dg$, $dg$Security measures shall ensure an appropriate level of security taking into account the nature of the personal data to be protected.$dg$, $dg$Nature of the personal data considered$dg$, $dg$The organisation demonstrably weighs this statutory factor when selecting and reviewing security measures.$dg$, $dg$Do you apply stronger protection to more sensitive categories of personal data than to routine data?$dg$, $dg$A single level of protection across everything either over-protects routine data or under-protects the data that would cause real harm if exposed.$dg$, $dg$Classify personal data holdings, treating sensitive personal data as defined in section 3 as its own tier, and map the safeguards required at each tier.$dg$, $dg$A data classification scheme with safeguards mapped to each tier and applied in practice.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SECURITY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Sensitive personal data attracts specific statutory treatment under section 30, and failing to distinguish it undermines both duties at once.$dg$, $dg$Incorporate this factor explicitly into the security risk assessment methodology and record the outcome.$dg$, $dg$Classify personal data holdings and map safeguards to each classification tier$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(2) requires that the appropriate level of security take these factors into account. DataGuard assesses each factor separately so that a gap in any one of them is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Classification Policy$dg$, $dg$Data Inventory with Classification$dg$, $dg$Security Policy$dg$]::text[], true, 40) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-010$dg$, $dg$REQ-027-2B$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(2)$dg$, $dg$(b)$dg$, $dg$Section 27(2)(b)$dg$, $dg$Security measures shall ensure an appropriate level of security taking into account the potential risks to the data subject.$dg$, $dg$Potential risks to the data subject considered$dg$, $dg$The organisation demonstrably weighs this statutory factor when selecting and reviewing security measures.$dg$, $dg$When you assess security risk, do you assess the harm to the individuals concerned, not just the harm to your organisation?$dg$, $dg$The Act asks about risk to the data subject. An incident that is minor for the business can be severe for the person whose data it is.$dg$, $dg$Include a harm-to-individual dimension in the security risk assessment, covering identity theft, discrimination, physical safety and financial loss, and let it drive control selection.$dg$, $dg$Risk assessments record impact on data subjects as a distinct dimension from organisational impact.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SECURITY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Risk to the data subject is an express statutory factor, and it is the dimension organisations most often omit from a security risk register.$dg$, $dg$Incorporate this factor explicitly into the security risk assessment methodology and record the outcome.$dg$, $dg$Add data subject harm as a distinct dimension of the security risk assessment$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 27(2) requires that the appropriate level of security take these factors into account. DataGuard assesses each factor separately so that a gap in any one of them is visible.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Risk Assessment$dg$, $dg$Risk Assessment Methodology$dg$, $dg$Data Protection Impact Analysis$dg$]::text[], true, 41) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-011$dg$, $dg$REQ-027-3$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(3)$dg$, NULL, $dg$Section 27(3)$dg$, $dg$The data controller and data processor, as the case may be, shall appoint a data protection officer.$dg$, $dg$Data protection officer appointed$dg$, $dg$A named individual has been formally appointed as data protection officer for the organisation in its capacity as controller or processor.$dg$, $dg$Have you formally appointed someone as your data protection officer?$dg$, $dg$The Act requires an appointment. Naming a person informally is not the same thing, and the appointment is one of the first things a regulator will ask to see.$dg$, $dg$Issue a signed appointment letter identifying the individual, the effective date, the reporting line and the authority granted. Record the contact details and keep them current.$dg$, $dg$A signed, dated appointment letter is on file for a currently serving data protection officer.$dg$, $dg$DOCUMENT_REQUIRED$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. The appointment is mandatory for both controllers and processors, it is binary and easily verified, and its absence is a visible failure that undermines every other control.$dg$, $dg$Select a suitable individual, issue a signed appointment letter, and record the appointment in the compliance file.$dg$, $dg$Appoint a data protection officer and issue a signed appointment letter$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$Section 64(2)(c) allows regulations to prescribe the functions of the data protection officer. The Act itself does not set qualifications, independence requirements, or whether the role may be shared across a group. A statement such as we have a DPO with no appointment document is WEAK evidence.$dg$, ARRAY[]::text[], ARRAY[$dg$DPO Appointment Letter$dg$, $dg$Board or Management Resolution$dg$, $dg$Organisation Chart$dg$]::text[], true, 42) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-012$dg$, $dg$REQ-027-3$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(3)$dg$, NULL, $dg$Section 27(3)$dg$, $dg$The data protection officer shall ensure that the control and security measures are in place to protect the personal data collected or being processed.$dg$, $dg$Data protection officer verifies control and security measures$dg$, $dg$The data protection officer actively verifies that control and security measures are in place, and reports on that verification.$dg$, $dg$Does your data protection officer actually check that the controls and security measures are working, and report on what they find?$dg$, $dg$Section 27(3) gives the officer a substantive job, not a title. A DPO with no mandate, no access and no reporting line cannot discharge it.$dg$, $dg$Define the officer verification programme - what is reviewed, how often, and to whom findings are reported. Retain the reports. Ensure the officer has access to systems and to senior management.$dg$, $dg$A documented DPO verification programme with dated reports to senior management.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The statutory function is verification. An appointment without verification activity satisfies the form of section 27(3) but not its substance.$dg$, $dg$Agree a DPO work plan with defined review cycles and a standing reporting slot at management level.$dg$, $dg$Establish a DPO verification and reporting programme$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$DPO Report$dg$, $dg$DPO Work Plan$dg$, $dg$Management Review Minutes$dg$, $dg$Audit Report$dg$]::text[], true, 43) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=ex