insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-013$dg$, $dg$REQ-027-4$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(4)$dg$, NULL, $dg$Section 27(4)$dg$, $dg$Implementation of activities of the data processor shall be governed by a contract which associates the data processor to the data controller.$dg$, $dg$Written contract in place with every data processor$dg$, $dg$Every processor that handles personal data on the organisation behalf is engaged under a contract governing the implementation of its activities.$dg$, $dg$Is there a signed contract in place with every supplier or partner that handles personal data on your behalf?$dg$, $dg$Section 27(4) requires the relationship to be governed by a contract. Suppliers engaged on a purchase order or a handshake leave the obligation unmet.$dg$, $dg$Maintain a processor inventory. For each processor, confirm a signed contract exists and covers the section 27(4) elements assessed at PDPA-027-014 and PDPA-027-015.$dg$, $dg$A processor inventory in which every entry is linked to a signed, in-force contract.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Does any third party process personal data on your behalf?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$THIRD_PARTY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. This is an express contractual requirement, it is binary, and an unpapered processor relationship is both a breach and an uncontrolled exposure.$dg$, $dg$Build the processor inventory, identify unpapered relationships, and put compliant contracts in place, prioritising those handling sensitive personal data.$dg$, $dg$Put a compliant written contract in place with every data processor$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Processor Agreement$dg$, $dg$Data Processing Agreement$dg$, $dg$Processor Inventory$dg$, $dg$Signed Contract$dg$]::text[], true, 44) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-014$dg$, $dg$REQ-027-4$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(4)$dg$, NULL, $dg$Section 27(4)$dg$, $dg$The contract shall be to the effect that the data processor acts under instructions of the data controller.$dg$, $dg$Contract requires the processor to act on controller instructions$dg$, $dg$Each processor contract states that the processor acts under the instructions of the controller, and instructions are given and recorded in practice.$dg$, $dg$Does each processor contract say the processor must act on your instructions, and do you actually give and record those instructions?$dg$, $dg$This clause defines the boundary between processor and controller. Section 50(2)(b) makes a processor liable for damage where it acts contrary to the controller lawful instructions.$dg$, $dg$Include an explicit instructions clause in every processor contract, and keep a record of documented instructions - the scope of processing, permitted sub-processing, and any change requests.$dg$, $dg$An instructions clause in every processor contract, supported by a record of documented instructions.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Does any third party process personal data on your behalf?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$THIRD_PARTY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Without a clear instructions boundary, responsibility for a processor failure is unclear, and section 50(2)(b) liability turns on exactly this point.$dg$, $dg$Add or strengthen the instructions clause at the next contract review, and start recording instructions.$dg$, $dg$Add a controller instructions clause to all processor contracts$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Processor Agreement$dg$, $dg$Documented Processing Instructions$dg$, $dg$Contract Clause Review$dg$]::text[], true, 45) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-015$dg$, $dg$REQ-027-4$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(4)$dg$, NULL, $dg$Section 27(4)$dg$, $dg$The contract shall provide that the data processor is additionally responsible for ensuring compliance of the security standards as provided by this Act.$dg$, $dg$Processor contractually responsible for security standards$dg$, $dg$Each processor contract makes the processor responsible for compliance with the security standards required by the Act, and that responsibility is monitored.$dg$, $dg$Does each processor contract make the processor responsible for meeting the security standards the Act requires, and do you check that they do?$dg$, $dg$Section 27(4) places security responsibility on the processor in addition to the controller. Outsourcing the work does not outsource the exposure.$dg$, $dg$Include a security standards clause and a right to obtain assurance - certification, audit report or questionnaire. Record the assurance obtained for each processor and refresh it periodically.$dg$, $dg$A security clause in every processor contract plus current assurance evidence per processor.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Does any third party process personal data on your behalf?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$THIRD_PARTY$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Processor security failures produce controller-level consequences, and section 27(5) requires the controller to notify breaches occurring on its behalf.$dg$, $dg$Add the security standards clause, then collect assurance evidence starting with processors handling sensitive personal data.$dg$, $dg$Obtain security assurance evidence from every data processor$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$Section 64(2)(h) allows regulations to prescribe appropriate standards relating to security of information to be met by data controllers. Until those are made, the applicable standards are those derivable from sections 5(g) and 27.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Processor Agreement$dg$, $dg$Processor Security Assurance$dg$, $dg$Audit Report$dg$, $dg$Certification Evidence$dg$]::text[], true, 46) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-016$dg$, $dg$REQ-027-5$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(5)$dg$, NULL, $dg$Section 27(5)$dg$, $dg$The data controller shall notify the Commission, without any undue delay, of any security breach affecting personal data being processed by or on behalf of the data controller.$dg$, $dg$Security breach notification to the Commission without undue delay$dg$, $dg$A documented procedure ensures the Commission is notified without undue delay of any security breach affecting personal data processed by or on behalf of the organisation.$dg$, $dg$Do you have a procedure that notifies the Commission without undue delay whenever there is a security breach affecting personal data - including breaches at your suppliers?$dg$, $dg$The duty covers breaches at your processors as well as your own systems, and the clock is described as without undue delay. A procedure written after the breach is already too late.$dg$, $dg$Document the notification procedure with named roles, a decision path, and contract terms obliging processors to alert you promptly. Rehearse it. The Act sets no fixed hour count, so any internal deadline you adopt is your own commitment.$dg$, $dg$An approved breach notification procedure, tested at least annually, with processor notification obligations in contracts.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$BREACH_NOTIFICATION$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. This is an express, time-bound duty owed directly to the regulator, and section 46(2)(g) treats how a failure came to the attention of the Commission as a factor in setting any penalty.$dg$, $dg$Write and approve the breach notification procedure, add processor alerting obligations to contracts, and run a tabletop exercise.$dg$, $dg$Implement and test a security breach notification procedure$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not define security breach, does not fix a period for without undue delay, does not prescribe the content or form of the notification, and does not require notification to affected data subjects. Do not import a 72-hour deadline or a data subject notification duty from another regime; neither appears in this Act.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Incident Response Procedure$dg$, $dg$Breach Notification Log$dg$, $dg$Breach Response Test Record$dg$, $dg$Processor Agreement$dg$]::text[], true, 47) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-027-017$dg$, $dg$REQ-027-5$dg$, $dg$IV$dg$, $dg$27$dg$, $dg$27(5)$dg$, NULL, $dg$Section 27(5)$dg$, $dg$The controller must be able to identify security breaches affecting personal data processed by or on behalf of the controller in order to notify the Commission without undue delay.$dg$, $dg$Breach detection capability$dg$, $dg$Monitoring, logging and reporting channels exist that would actually surface a security breach, including one occurring at a processor.$dg$, $dg$Would you find out if personal data were breached - in your own systems and at your suppliers?$dg$, $dg$You cannot notify a breach you never detect. The notification duty is only meaningful if something is watching.$dg$, $dg$Ensure logging and alerting on systems holding personal data, provide a staff reporting channel, and require processors to notify you promptly. Review whether the coverage matches where the data actually is.$dg$, $dg$Monitoring and reporting channels cover all systems holding personal data, and processor notification duties are in contracts.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$QUARTERLY$dg$, $dg$BREACH_NOTIFICATION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Detection is the precondition for the section 27(5) duty. Undetected breaches also mean the failure reaches the Commission from another source, which section 46(2)(g) treats as relevant to penalty.$dg$, $dg$Map systems holding personal data against monitoring coverage and close the gaps, starting with the highest-sensitivity holdings.$dg$, $dg$Establish breach detection coverage across all systems holding personal data$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. The Act imposes no express detection duty. This control is derived from the notification duty in section 27(5) read with the safeguards duty in section 27(1), and adds no new legal obligation.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Monitoring and Alerting Configuration$dg$, $dg$Incident Reporting Channel$dg$, $dg$Processor Agreement$dg$, $dg$Incident Log$dg$]::text[], true, 48) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-028-001$dg$, $dg$REQ-028-1$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$28(1)$dg$, NULL, $dg$Section 28(1)$dg$, $dg$Personal data used for a specified purpose shall be retained for a period specified in the relevant laws or a period prescribed in the regulations.$dg$, $dg$Retention periods sourced from law or regulations$dg$, $dg$For each category of personal data, the retention period is taken from the relevant written law or from regulations made under the Act, and the source is cited.$dg$, $dg$For each type of personal data you hold, have you identified the retention period set by the relevant law or regulations, and recorded where it comes from?$dg$, $dg$Section 28(1) points to periods fixed elsewhere in law rather than periods you choose. Citing the source is what makes the schedule defensible.$dg$, $dg$Build the retention schedule with a citation column. Where no law or regulation fixes a period, record that fact explicitly rather than inventing a number, and justify the period against the purpose under section 5(e).$dg$, $dg$A retention schedule in which every record type has either a cited legal source or an explicit note that none was found, with a purpose-based justification.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Retention is expressly regulated by section 28 and is one of the few duties where the correct answer is fixed externally rather than chosen by the organisation.$dg$, $dg$Research the sectoral laws applying to each record type, then complete the citation column of the retention schedule.$dg$, $dg$Identify and cite the legal retention period for each personal data record type$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$REGULATORY_DETAIL_PENDING. The Act itself prescribes no retention periods. Do not populate this control with invented periods. Where regulations under section 28(2) or 64(2)(j) are in force, they govern.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Retention Schedule$dg$, $dg$Legal Retention Research Note$dg$, $dg$Data Processing Register$dg$]::text[], true, 49) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-028-002$dg$, $dg$REQ-028-1$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$28(1)$dg$, NULL, $dg$Section 28(1)$dg$, $dg$Retention shall ensure that the data subject has a reasonable opportunity to access the personal data where need arises.$dg$, $dg$Retention supports the data subject opportunity to access$dg$, $dg$Retention arrangements are set so that a data subject retains a reasonable opportunity to access their personal data while it is held.$dg$, $dg$While you hold personal data, can the person it is about still get access to it if they ask?$dg$, $dg$Section 28(1) ties the retention duty to access. Data held in a form nobody can retrieve - deep archive, unindexed backups - defeats the purpose the Act gives for keeping it.$dg$, $dg$Confirm that data held under the retention schedule remains retrievable for a section 33 access request throughout the retention period, including archived and backup copies.$dg$, $dg$Retrievability confirmed for every record type in the retention schedule, including archives.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Unretrievable retained data frustrates section 33 access rights, though it is less directly harmful than over- or under-retention.$dg$, $dg$Test retrieval from archive and backup for each retained record type and remediate where retrieval fails.$dg$, $dg$Test retrievability of archived personal data for access requests$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Retention Schedule$dg$, $dg$Archive Retrieval Test Record$dg$, $dg$Data Subject Rights Procedure$dg$]::text[], true, 50) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-028-003$dg$, $dg$REQ-028-1$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$28(1)$dg$, NULL, $dg$Section 28(1) read with section 5(e)$dg$, $dg$Retention is tied to the purpose for which the personal data is used under section 25, and section 5(e) requires storage in identifiable form for no longer than is necessary for that purpose.$dg$, $dg$Purpose-based retention decisions documented$dg$, $dg$Each retention decision records the purpose it serves and the reasoning behind the period chosen.$dg$, $dg$For each type of personal data, have you written down why you keep it for as long as you do?$dg$, $dg$Where no law fixes a period, the purpose is what justifies the period. Recording the reasoning is the only way to show the decision was made rather than defaulted into.$dg$, $dg$Add purpose and rationale columns to the retention schedule. Have the data protection officer review and date the decisions.$dg$, $dg$A retention schedule with a recorded purpose, rationale, decision owner and decision date per record type.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Undocumented retention decisions are difficult to defend and tend to drift towards keeping everything forever.$dg$, $dg$Complete purpose and rationale columns for the retention schedule and have them approved.$dg$, $dg$Document the purpose and rationale behind each retention period$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED from sections 28(1), 25 and 5(e) read together. The requirement to document the reasoning is IMPLEMENTATION_GUIDANCE, not a statutory duty in its own terms.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Retention Schedule$dg$, $dg$Retention Decision Record$dg$, $dg$DPO Approval Record$dg$]::text[], true, 51) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-028-004$dg$, $dg$REQ-028-2$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$28(2)$dg$, NULL, $dg$Section 28(2) read with section 64(2)(j)$dg$, $dg$The Minister may by regulations prescribe the retention and disposal of personal data held by a data controller in accordance with the purpose of retention. Section 64(2)(j) allows regulations prescribing procedures for retention and disposal of personal data held by data controllers.$dg$, $dg$Secure disposal at the end of the retention period$dg$, $dg$Personal data is securely disposed of at the end of its retention period, following any procedure prescribed by regulations, and disposal is recorded.$dg$, $dg$When personal data reaches the end of its retention period, is it securely disposed of, and do you keep a record that this happened?$dg$, $dg$Disposal is the step that actually reduces risk. Without a record, you cannot show it happened, and data assumed deleted has a habit of resurfacing in backups.$dg$, $dg$Define disposal methods per medium - electronic, paper, portable media - and record each disposal event. Cover archives and backup copies. Check the current regulations for any prescribed procedure before finalising the method.$dg$, $dg$A documented disposal procedure covering all media, with a disposal log evidencing execution.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Data retained past its period is exposed for no lawful reason, and the absence of a disposal record makes over-retention indistinguishable from deliberate hoarding.$dg$, $dg$Write a disposal procedure covering every medium including backups, then start a disposal log.$dg$, $dg$Implement a secure disposal procedure and disposal log$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$REGULATORY_DETAIL_PENDING. The disposal procedure is to be prescribed by regulations. Note the tension with section 29(2), which forbids permanent deletion of the pre-amendment record, and with section 59 preservation orders. Disposal must be sequenced around both.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Disposal Procedure$dg$, $dg$Disposal Log$dg$, $dg$Certificate of Destruction$dg$, $dg$Retention Schedule$dg$]::text[], true, 52) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-028-005$dg$, $dg$REQ-028-2$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$28(2)$dg$, NULL, $dg$Section 28 read with section 64(2)(j)$dg$, $dg$The retention and disposal of personal data is to be carried out in accordance with the purpose of retention, as may be prescribed by regulations.$dg$, $dg$Periodic review of the retention schedule$dg$, $dg$The retention schedule is reviewed on a defined cycle and whenever a relevant law or regulation changes.$dg$, $dg$Do you review your retention schedule regularly and update it when the law changes?$dg$, $dg$Retention periods are set outside the Act, in sectoral laws and in regulations still to be made. A schedule that is never revisited goes stale without anyone noticing.$dg$, $dg$Set an annual review with a named owner, and add a trigger for reviewing when regulations under section 28(2) or 64(2)(j) are made or amended.$dg$, $dg$A dated review record for the retention schedule with a named owner and a next-review date.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$LOW$dg$, $dg$DataGuard default risk classification: Low. Review cadence is good practice that keeps the schedule current; the Act does not impose a review cycle.$dg$, $dg$Add the retention schedule review to the annual compliance calendar.$dg$, $dg$Schedule an annual review of the retention schedule$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$IMPLEMENTATION_GUIDANCE$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$IMPLEMENTATION_GUIDANCE. The Act imposes no periodic review duty for retention schedules. This control exists so that the organisation notices when regulations are made.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Retention Schedule Review Record$dg$, $dg$Compliance Calendar$dg$, $dg$Regulatory Change Log$dg$]::text[], false, 53) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-028-006$dg$, $dg$REQ-028-1$dg$, $dg$IV$dg$, $dg$28$dg$, $dg$28(1)$dg$, NULL, $dg$Section 28(1)$dg$, $dg$Retention shall be for a period specified in the relevant laws, which requires identification of the laws relevant to the data controller records.$dg$, $dg$Identification of applicable sectoral retention laws$dg$, $dg$The organisation has identified the written laws that fix retention periods for its records, such as tax, company, employment, health or financial services legislation.$dg$, $dg$Have you identified the other laws that tell you how long to keep your records - tax, employment, company or sector rules?$dg$, $dg$Section 28(1) sends you to the relevant laws. If you have not found them, you cannot know whether your retention periods are right.$dg$, $dg$Ask counsel or the compliance function to produce a list of retention-relevant statutes for your sector, and map each to the record types affected.$dg$, $dg$A dated legal research note listing applicable retention statutes mapped to record types.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$RETENTION$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Without this research the retention schedule rests on assumption, though the underlying failure surfaces through PDPA-028-001.$dg$, $dg$Commission a legal review of sectoral retention obligations and map the results.$dg$, $dg$Identify the sectoral laws that fix retention periods for your records$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED from section 28(1). DataGuard must not pre-populate Tanzanian sectoral retention periods; they lie outside this Act.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Legal Retention Research Note$dg$, $dg$Retention Schedule$dg$, $dg$External Counsel Advice$dg$]::text[], true, 54) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-029-001$dg$, $dg$REQ-029-1$dg$, $dg$IV$dg$, $dg$29$dg$, $dg$29(1)$dg$, NULL, $dg$Section 29(1)$dg$, $dg$Where a data subject claims that personal data in a document to which access has been given is incomplete, incorrect or misleading, or not relevant to the purpose for which the document is held, the data controller may, subject to prescribed procedures and upon being satisfied with the application, amend the personal data.$dg$, $dg$Correction request procedure$dg$, $dg$A documented procedure receives, assesses and decides applications from data subjects to amend personal data, and records the outcome.$dg$, $dg$Do you have a procedure for handling requests from people to correct their personal data, and do you record what you decided?$dg$, $dg$Correction requests arrive by whatever channel the person happens to use. Without a procedure they get lost, and a lost request tends to become a complaint to the Commission.$dg$, $dg$Define intake channels, the assessment step, the decision maker and the record kept. The Act frames amendment as something the controller may do once satisfied, so the assessment reasoning matters and should be recorded.$dg$, $dg$An approved correction procedure with a request log recording each request, decision and reasoning.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Correction requests are a common trigger for section 39 complaints and for Commission orders under section 38.$dg$, $dg$Write and approve the correction procedure, publish the intake channel, and start the request log.$dg$, $dg$Implement a personal data correction request procedure$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$The procedure for applications is to be prescribed by regulations. OPEN_QUESTION: the Act sets no time limit for deciding a correction application, and section 29(1) is framed as a discretion (may amend) exercisable once the controller is satisfied.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Subject Rights Procedure$dg$, $dg$Correction Request Log$dg$, $dg$Rectification Log$dg$]::text[], true, 55) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-029-002$dg$, $dg$REQ-029-2$dg$, $dg$IV$dg$, $dg$29$dg$, $dg$29(2)$dg$, NULL, $dg$Section 29(2)$dg$, $dg$The data controller shall, when making an amendment to personal data in a document under this section, ensure that he does not permanently delete the record of the text of the document as it existed prior to the amendment.$dg$, $dg$Pre-amendment record preserved on correction$dg$, $dg$When personal data is amended, the text of the document as it existed before the amendment is preserved and is not permanently deleted.$dg$, $dg$When you correct someone personal data, do you keep a copy of what the record said before you changed it?$dg$, $dg$This is one of the few places where the Act dictates system behaviour directly. Overwriting a record in place, with no prior version retained, breaches section 29(2) even where the correction itself was right.$dg$, $dg$IMPLEMENTATION_GUIDANCE: maintain an auditable history or version of corrected information rather than permanently overwriting the previous record. In practice this means append-only history tables, versioned documents, or an equivalent immutable audit trail on any system holding personal data that can be amended. Retention and access rules for the preserved prior version should be defined, since it remains personal data.$dg$, $dg$Every system that can amend personal data retains the prior version in a retrievable, tamper-evident form.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DATA_INTEGRITY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The duty is express and absolute in its terms, and a system that overwrites in place breaches it on every correction without anyone noticing.$dg$, $dg$Audit systems for in-place overwrite behaviour on personal data fields and introduce version history where it is missing.$dg$, $dg$Ensure all systems preserve the pre-amendment record when personal data is corrected$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$This provision has direct architectural consequences for DataGuard itself: compliance records that are corrected must retain an auditable history rather than being overwritten. The statutory requirement is the non-deletion of the prior text; the versioning and audit-trail design described above is DataGuard implementation guidance, not a statutory prescription. OPEN_QUESTION: the Act does not say for how long the prior version must be preserved, nor how it interacts with the disposal duty under section 28.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$System Version History Configuration$dg$, $dg$Audit Log Sample$dg$, $dg$Correction Request Log$dg$, $dg$Technical Design Document$dg$]::text[], true, 56) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-029-003$dg$, $dg$REQ-029-3$dg$, $dg$IV$dg$, $dg$29$dg$, $dg$29(3)$dg$, NULL, $dg$Section 29(3)$dg$, $dg$Where a data controller is not satisfied with the reasons for an application under subsection (1), he may refuse to make any amendment to the personal data and inform the applicant of the reasons for refusal.$dg$, $dg$Refusal of a correction request with reasons given$dg$, $dg$Where a correction request is refused, the applicant is informed of the reasons and the reasoning is recorded.$dg$, $dg$If you refuse to correct someone data, do you tell them why, and do you keep a record of your reasons?$dg$, $dg$Refusing without reasons turns a defensible decision into an apparent brush-off, and it is what usually pushes the person to complain to the Commission instead.$dg$, $dg$Use a standard refusal notice template capturing the reasons and the date sent, and retain it with the request record. Mention the availability of a complaint to the Commission under section 39.$dg$, $dg$A refusal notice template in use, with issued notices retained against the request log.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Have you ever refused, or might you refuse, a request to correct personal data?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Refusal is expressly permitted by the Act; the failure mode is refusing without communicating reasons.$dg$, $dg$Create a refusal notice template and require its use for every refusal.$dg$, $dg$Create a correction refusal notice template that states reasons$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Refusal Notice Template$dg$, $dg$Correction Request Log$dg$, $dg$Issued Refusal Notices$dg$]::text[], true, 57) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-001$dg$, $dg$REQ-030-1$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(1)$dg$, NULL, $dg$Section 30(1) read with the definition of sensitive personal data in section 3$dg$, $dg$A person shall not process sensitive personal data without obtaining prior written consent of the data subject. Sensitive personal data includes genetic data, data related to children, data related to offences, financial transactions of the individual, security measure or biometric data; data processed for what they reveal about racial or ethnic origin, political opinions, religious or philosophical beliefs, affiliation, trade-union membership, gender and data concerning health or sex life; and any personal data otherwise considered under the laws of the country as presenting a major risk to the rights and interests of the data subject.$dg$, $dg$Identification of sensitive personal data holdings$dg$, $dg$The organisation has identified where it holds sensitive personal data as defined in section 3, and has flagged those holdings in its inventory.$dg$, $dg$Have you identified everywhere you hold sensitive personal data - such as health, biometric, genetic, financial transaction, children data, criminal offence data, or data revealing race, religion, political opinion, trade union membership, gender or sex life?$dg$, $dg$The definition in this Act is broader than many people expect - it includes financial transactions, data about children and security measures. Everything else in section 30 depends on knowing where this data is.$dg$, $dg$Flag sensitive holdings in the processing register against each limb of the section 3 definition. Note that data related to children is sensitive in its own right, and that data becomes sensitive where it is processed for what it reveals.$dg$, $dg$The processing register flags every sensitive personal data holding against the specific limb of the definition it falls under.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 30(1) prohibits processing sensitive personal data without prior written consent unless an exception applies. An organisation that has not identified its sensitive holdings cannot know whether it is inside that prohibition.$dg$, $dg$Run a data discovery exercise against each limb of the section 3 definition and flag the results in the register.$dg$, $dg$Identify and flag all sensitive personal data holdings$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$The section 3 definition uses includes, so the list is not exhaustive. Limb (c) extends to personal data otherwise considered under the laws of the country as presenting a major risk to the rights and interests of the data subject.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Processing Register$dg$, $dg$Data Classification Policy$dg$, $dg$Sensitive Data Inventory$dg$]::text[], true, 58) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-002$dg$, $dg$REQ-030-1$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(1)$dg$, NULL, $dg$Section 30(1)$dg$, $dg$A person shall not process sensitive personal data without obtaining prior written consent of the data subject.$dg$, $dg$Prior written consent obtained for sensitive personal data$dg$, $dg$Where sensitive personal data is processed on the basis of consent, that consent is written, obtained before processing begins, and retained as a record.$dg$, $dg$Where you process sensitive personal data on the basis of consent, did you get that consent in writing before you started, and can you produce it?$dg$, $dg$The Act requires the consent to be written and prior. Consent gathered afterwards, or given verbally, does not meet the section as drafted.$dg$, $dg$Capture consent in a retained written form linked to the individual record, with the date and the specific processing consented to. Where consent is not the basis, record the section 30(5) exception instead - see PDPA-030-005.$dg$, $dg$A retrievable written consent record per data subject for each consent-based sensitive processing activity.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process any sensitive personal data on the basis of consent?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SENSITIVE_DATA$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 30(1) is a prohibition. Processing sensitive personal data without written prior consent and without an applicable exception is unlawful from the first record.$dg$, $dg$Identify consent-based sensitive processing, put written consent capture in place, and either re-obtain consent or move to a documented section 30(5) exception.$dg$, $dg$Implement written prior consent capture for sensitive personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 30(1) is subject to the exceptions in section 30(5). Do not assume all sensitive data processing requires consent - see PDPA-030-005. OPEN_QUESTION: the Act does not define the form or content requirements for written consent.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Consent Record$dg$, $dg$Consent Form Template$dg$, $dg$Consent Management System Export$dg$]::text[], true, 59) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-003$dg$, $dg$REQ-030-2$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(2)$dg$, NULL, $dg$Section 30(2)$dg$, $dg$The consent under subsection (1) may be withdrawn by the data subject at any time and without any explanation or charges.$dg$, $dg$Consent withdrawal at any time, free of charge and without explanation$dg$, $dg$Data subjects can withdraw consent to sensitive data processing at any time, without giving a reason and without any charge, and withdrawal takes effect in the systems.$dg$, $dg$Can people withdraw their consent at any time, without giving a reason and without paying anything - and does that actually stop the processing?$dg$, $dg$The Act is explicit that withdrawal is free and needs no explanation. A withdrawal route that is hard to find, or that logs the request but does not stop the processing, does not satisfy it.$dg$, $dg$Provide a withdrawal channel at least as easy as the channel used to give consent. Ensure withdrawal propagates to downstream systems and to processors. Never require a reason and never charge a fee.$dg$, $dg$A working, free withdrawal channel with evidence that withdrawal stops the processing in all systems.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process any sensitive personal data on the basis of consent?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SENSITIVE_DATA$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Continuing to process after withdrawal removes the lawful basis and returns the processing to the section 30(1) prohibition.$dg$, $dg$Build the withdrawal channel, test that withdrawal propagates downstream, and remove any fee or explanation requirement.$dg$, $dg$Implement a free, no-explanation consent withdrawal channel$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Consent Withdrawal Procedure$dg$, $dg$Withdrawal Log$dg$, $dg$System Configuration Evidence$dg$, $dg$Consent Record$dg$]::text[], true, 60) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-004$dg$, $dg$REQ-030-4$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(4)$dg$, NULL, $dg$Section 30(4)$dg$, $dg$Where the data subject from whom consent is sought is a minor, a person of unsound mind or any other person unable to consent, such consent shall be sought from his parents, guardian, heirs, attorneys or any other person recognised by law to be acting on behalf of that person.$dg$, $dg$Consent obtained from the authorised representative where the data subject cannot consent$dg$, $dg$Where the data subject is a minor, of unsound mind, or otherwise unable to consent, consent is sought from the parent, guardian, heir, attorney or other legally recognised representative, and the authority is verified.$dg$, $dg$Where the person cannot give consent themselves - for example a child - do you obtain consent from their parent, guardian or other authorised representative, and do you check that authority?$dg$, $dg$Data related to children is sensitive personal data under this Act in its own right, so any service that touches children data engages both section 30(1) and section 30(4).$dg$, $dg$Identify processing involving minors or persons unable to consent. Define how representative authority is verified and recorded. Note that child takes its meaning from the Child Act.$dg$, $dg$Representative consent records held, with the basis of authority verified and recorded.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process personal data of children, or of anyone who may be unable to give their own consent?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Data related to children is expressly sensitive personal data under section 3, so a defective consent chain here breaches the section 30(1) prohibition directly.$dg$, $dg$Identify processing involving minors, implement representative consent capture, and verify authority before processing.$dg$, $dg$Implement representative consent capture for minors and persons unable to consent$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Child has the meaning ascribed to it under the Child Act (section 3). OPEN_QUESTION: the Act does not prescribe how age or capacity is to be verified.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Consent Record$dg$, $dg$Guardian Authority Verification Record$dg$, $dg$Age Verification Procedure$dg$]::text[], true, 61) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-005$dg$, $dg$REQ-030-5$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(5)$dg$, $dg$(a)-(f)$dg$, $dg$Section 30(5)(a)-(f)$dg$, $dg$The consent requirement in subsection (1) does not apply where the processing is necessary for compliance with other written laws; is necessary to protect the vital interests of the data subject or another person where the data subject is incapable of consenting or is not represented; is necessary for the institution, trial or defence of legal claims; relates to personal data apparently made public by the data subject; is necessary for scientific research where the Commission has by special guidelines specified the circumstances; or is necessary for medical reasons in the interest of the data subject under the supervision of a health professional.$dg$, $dg$Documented reliance on the sensitive data consent exceptions$dg$, $dg$Where sensitive personal data is processed without consent, the specific section 30(5) exception relied on is identified, justified and recorded.$dg$, $dg$Where you process sensitive personal data without consent, have you recorded which legal exception allows it?$dg$, $dg$The Act does provide exceptions, so not all sensitive processing needs consent. But the exception has to be identified and justified, not assumed.$dg$, $dg$For each sensitive processing activity without consent, record the exception limb, the justification and the assessment date. Have the data protection officer review. Note that reliance on the research exception depends on Commission guidelines existing - see PDPA-030-006.$dg$, $dg$A sensitive data exception register with a limb, justification, reviewer and date for each entry.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process any sensitive personal data without the consent of the data subject?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The exceptions are lawful routes, so the risk is relying on one without analysis. An unrecorded exception is indistinguishable from no exception during an investigation.$dg$, $dg$Create the exception register, complete it for existing non-consent sensitive processing, and take advice on marginal cases.$dg$, $dg$Record the section 30(5) exception relied on for each non-consent sensitive processing activity$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Do not treat all sensitive personal data processing as unlawful without consent. Section 30(5) provides six express exceptions.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Sensitive Data Exception Register$dg$, $dg$Legal Assessment Note$dg$, $dg$DPO Approval Record$dg$]::text[], true, 62) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-006$dg$, $dg$REQ-030-5$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(5)$dg$, $dg$(e)$dg$, $dg$Section 30(5)(e)$dg$, $dg$Subsection (1) shall not apply where the processing is necessary for the purposes of scientific research and the Commission has, by special guidelines, specified the circumstances under which such processing may be carried out.$dg$, $dg$Scientific research exception conditional on Commission guidelines$dg$, $dg$Reliance on the scientific research exception is conditional on the Commission having issued special guidelines specifying the circumstances, and on the processing falling within them.$dg$, $dg$If you process sensitive personal data for scientific research without consent, have you confirmed that the Commission has issued guidelines covering it and that you fall within them?$dg$, $dg$This exception is not self-executing. On the wording of the Act it depends on the Commission having issued special guidelines, so the exception cannot be assumed to be available.$dg$, $dg$Confirm the existence and terms of any Commission special guidelines before relying on this limb. If none exist, do not rely on it - seek consent or another exception, or take legal advice.$dg$, $dg$A documented confirmation of the applicable Commission guidelines, or a decision not to rely on this exception.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process sensitive personal data for scientific research purposes without consent?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. If no guidelines exist, reliance on this limb leaves the processing inside the section 30(1) prohibition.$dg$, $dg$Confirm the position with the Commission or with counsel before relying on the research exception.$dg$, $dg$Confirm the availability of the section 30(5)(e) scientific research exception$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$REGULATORY_DETAIL_PENDING. OPEN_QUESTION: whether the Commission has issued the special guidelines referred to in section 30(5)(e) is outside the Act and must be verified. DataGuard must not presume they exist.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Commission Guidelines Reference$dg$, $dg$Research Ethics Approval$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 63) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-007$dg$, $dg$REQ-030-5$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(5)$dg$, $dg$(f)$dg$, $dg$Section 30(5)(f)$dg$, $dg$Subsection (1) shall not apply where the processing is necessary for the purposes of medical reasons in the interest of the data subject, and the sensitive personal data concerned is processed under the supervision of a health professional in accordance with the law governing such health care services.$dg$, $dg$Medical processing supervised by a health professional$dg$, $dg$Sensitive personal data processed for medical reasons without consent is processed under the supervision of a health professional in accordance with the law governing health care services.$dg$, $dg$Where you process health-related sensitive data for medical reasons without consent, is that processing supervised by a recognised health professional?$dg$, $dg$The exception has two limbs: the medical purpose in the interest of the data subject, and supervision by a health professional. Both must hold.$dg$, $dg$Record the supervising health professional and the basis of their recognition under the relevant law. Health professional is defined in section 3 as a person providing health care services and recognised as such by the relevant law.$dg$, $dg$A record of the supervising health professional for each medical processing activity relying on this exception.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process sensitive personal data for medical reasons without the consent of the data subject?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Without the supervision limb the exception fails and the processing falls back inside the section 30(1) prohibition.$dg$, $dg$Identify the supervising health professional for each activity and record the basis of their recognition.$dg$, $dg$Record health professional supervision for medical sensitive data processing$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Health Professional Supervision Record$dg$, $dg$Professional Registration Evidence$dg$, $dg$Clinical Governance Policy$dg$]::text[], true, 64) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-008$dg$, $dg$REQ-030-3$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(3)$dg$, NULL, $dg$Section 30(3)$dg$, $dg$The Minister may, by regulations, determine circumstances in which the prohibition to process the personal data referred to in this section cannot be removed even with the data subject consent.$dg$, $dg$Monitoring of absolute prohibitions on sensitive data processing$dg$, $dg$The organisation monitors for regulations made under section 30(3) that would prohibit certain sensitive data processing even with consent, and checks its processing against them.$dg$, $dg$Do you check whether any regulations forbid certain sensitive data processing outright, even where you have consent?$dg$, $dg$Section 30(3) allows for categories of processing that no consent can authorise. If such regulations are made, consent-based processing in those categories becomes unlawful overnight.$dg$, $dg$Add section 30(3) regulations to the regulatory monitoring list. Where regulations exist, check each sensitive processing activity against them and stop any that falls inside an absolute prohibition.$dg$, $dg$A regulatory monitoring record covering section 30(3), with an assessment against any regulations in force.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process any sensitive personal data?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The obligation is contingent on regulations that may not yet exist, but the consequence if they are made and missed is that consent-based processing becomes unlawful.$dg$, $dg$Add section 30(3) to the regulatory monitoring list with a named owner.$dg$, $dg$Monitor for regulations made under section 30(3)$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$REGULATORY_DETAIL_PENDING. The Act does not itself identify any such circumstance. DataGuard must not pre-populate any absolute prohibition.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Change Log$dg$, $dg$Legal Assessment Note$dg$, $dg$Sensitive Data Exception Register$dg$]::text[], false, 65) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-009$dg$, $dg$REQ-030-1$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(1)$dg$, NULL, $dg$Section 30 read with section 27(2)(b)$dg$, $dg$Section 27(2)(b) requires the level of security to take into account the nature of the personal data to be protected and the potential risks to the data subject. Section 30 subjects sensitive personal data to a specific prohibition and consent regime.$dg$, $dg$Enhanced security and access restriction for sensitive personal data$dg$, $dg$Sensitive personal data is subject to stricter access restrictions and stronger safeguards than other personal data, in proportion to its nature and the risk to data subjects.$dg$, $dg$Is access to sensitive personal data more tightly restricted than access to your ordinary personal data?$dg$, $dg$The Act treats sensitive data as a distinct category with its own regime. Applying identical controls to all data means the sensitive holdings are under-protected.$dg$, $dg$Restrict access to sensitive holdings to named roles, log access, and apply stronger authentication and encryption. Review the access list on a defined cycle.$dg$, $dg$A documented enhanced control set applied to sensitive holdings, with periodic access reviews evidenced.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process any sensitive personal data?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$SENSITIVE_DATA$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Exposure of sensitive personal data carries the highest potential harm to data subjects, which is itself an express section 27(2)(b) factor.$dg$, $dg$Define a sensitive data control tier, apply it to the flagged holdings, and start periodic access reviews.$dg$, $dg$Apply enhanced access restrictions to sensitive personal data holdings$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED from sections 27(2)(b) and 30 read together. It adds no new legal obligation; it applies the existing security duty at the level the nature of the data requires.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Access Control Procedure$dg$, $dg$Access Review Records$dg$, $dg$Data Classification Policy$dg$, $dg$Encryption Standard$dg$]::text[], true, 66) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-030-010$dg$, $dg$REQ-030-1$dg$, $dg$IV$dg$, $dg$30$dg$, $dg$30(1)$dg$, NULL, $dg$Section 30 read with section 27(3)$dg$, $dg$Compliance with section 30 requires the controller to be able to show, for each sensitive processing activity, whether it rests on prior written consent or on a section 30(5) exception.$dg$, $dg$Documentation of sensitive personal data processing$dg$, $dg$A consolidated record shows, for each sensitive processing activity, the data category, the legal footing relied on, the consent or exception evidence, and the responsible owner.$dg$, $dg$Do you keep a single record showing every use of sensitive personal data and what makes each one lawful?$dg$, $dg$When the Commission asks about sensitive data, it will ask activity by activity. A consolidated record is the difference between answering in an hour and answering in a month.$dg$, $dg$Extend the processing register with a sensitive data view combining the flags from PDPA-030-001, the consent records, the section 30(5) exception entries and the owner. Have the data protection officer review it periodically.$dg$, $dg$A maintained sensitive processing record reviewed by the data protection officer at least annually.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you process any sensitive personal data?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$SENSITIVE_DATA$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Without this record the organisation cannot demonstrate the lawfulness of its sensitive processing, even where each individual activity happens to be lawful.$dg$, $dg$Build the consolidated sensitive processing view and assign it to the data protection officer for periodic review.$dg$, $dg$Maintain a consolidated record of all sensitive personal data processing$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$INTERPRETATION$dg$, $dg$NONE$dg$, $dg$INTERPRETATION. The Act does not expressly require a sensitive data register. DataGuard treats it as the practical means of demonstrating compliance with section 30 and of supporting the data protection officer function under section 27(3).$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Sensitive Data Inventory$dg$, $dg$Data Processing Register$dg$, $dg$DPO Report$dg$, $dg$Consent Record$dg$]::text[], true, 67) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-001$dg$, $dg$REQ-031-2$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(2)$dg$, NULL, $dg$Sections 31 and 32 read with section 5(h)$dg$, $dg$Part V governs transborder flow, defined in section 3 as any international cross-border flows of personal data by means of electronic transmission or other means. Compliance requires the controller to know which transfers it makes.$dg$, $dg$Identification and inventory of international transfers$dg$, $dg$All transborder flows of personal data are identified and recorded, including electronic transmission and any other means.$dg$, $dg$Have you listed every occasion on which personal data leaves Tanzania, by any means?$dg$, $dg$The statutory definition covers transfers by electronic transmission or other means. Cloud hosting, offshore support access, group reporting and even couriered paper all count.$dg$, $dg$Build a transfer inventory covering hosting and cloud services, offshore support and administration access, intra-group reporting, offshore backups and disaster recovery, and any physical movement of records. Record recipient, destination country, data categories and purpose for each.$dg$, $dg$A complete transfer inventory, reviewed at least annually and on any change of supplier or hosting arrangement.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Does any personal data you hold leave Tanzania by any means?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Everything else in Part V depends on knowing which transfers exist. Undiscovered transfers are unassessed transfers.$dg$, $dg$Interview IT and business owners, review supplier contracts and hosting arrangements, and build the inventory before assessing any individual transfer.$dg$, $dg$Build a complete inventory of transborder personal data flows$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. The Act does not expressly require a transfer inventory. It is the practical precondition for demonstrating compliance with sections 31 and 32.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Inventory$dg$, $dg$Cloud Hosting Register$dg$, $dg$Data Flow Diagram$dg$, $dg$Processor Inventory$dg$]::text[], true, 68) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-002$dg$, $dg$REQ-031-2$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(2)$dg$, NULL, $dg$Section 31(2)$dg$, $dg$Personal data shall be transferred to a country that has a legal framework that provides for adequate data protection.$dg$, $dg$Destination country legal framework assessed$dg$, $dg$For each destination, the organisation has assessed whether that country has a legal framework providing adequate data protection, and has recorded the assessment.$dg$, $dg$For each country you send personal data to, have you assessed whether its laws provide adequate data protection, and written that assessment down?$dg$, $dg$Section 31 applies to countries with an adequate legal framework and section 32 to those without. Which section governs a transfer depends on this assessment.$dg$, $dg$Assess each destination country using the section 32(2) factors, which supply the statutory criteria for adequacy. Record the conclusion, the date and who made it. Reassess when the destination law changes.$dg$, $dg$A dated adequacy assessment per destination country, held with the transfer inventory.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The adequacy conclusion determines which statutory route applies, and getting it wrong invalidates the basis for every transfer to that destination.$dg$, $dg$Commission a country-by-country assessment against the section 32(2) factors, starting with your highest-volume destinations.$dg$, $dg$Assess the data protection legal framework of each destination country$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$DataGuard must not hard-code any country as adequate or inadequate. The Act contains no list of adequate countries, and no adequacy decision is reproduced in it. Adequacy is assessed by the data controller under section 32(2), subject to the Commission powers under sections 31(1) and 32(5) and to any regulations under section 32(3).$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Assessment$dg$, $dg$Legal Assessment Note$dg$, $dg$External Counsel Advice$dg$]::text[], true, 69) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-003$dg$, $dg$REQ-031-2$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(2)$dg$, $dg$(a)-(b)$dg$, $dg$Section 31(2)(a)-(b)$dg$, $dg$A transfer to a country with an adequate legal framework requires that the recipient establishes either that the personal data is necessary for the performance of a task carried out in the public interest or pursuant to the lawful functions of a data controller, or that there is a necessity for the transfer and no reason to assume that the data subject legitimate interests might be prejudiced by the transfer or by the processing in the recipient country.$dg$, $dg$Recipient establishes the statutory ground for the transfer$dg$, $dg$For each transfer under section 31, the recipient has established one of the two statutory grounds, and the organisation holds that record.$dg$, $dg$For each transfer, has the recipient shown you why the data is needed, and have you kept that in writing?$dg$, $dg$The Act puts the burden on the recipient to establish the ground. If the recipient has never been asked, the ground has not been established.$dg$, $dg$Ask the recipient to state in writing which ground applies and why. For the second ground, record the assessment that the data subject legitimate interests would not be prejudiced.$dg$, $dg$A written statement from each recipient establishing the ground, held with the transfer record.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data to a country you have assessed as having an adequate legal framework?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Without the recipient statement the transfer has no established ground, and the record cannot be reconstructed after the fact.$dg$, $dg$Request written necessity statements from existing recipients and build the request into the onboarding process for new ones.$dg$, $dg$Obtain written necessity statements from transfer recipients$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Recipient Necessity Statement$dg$, $dg$Transfer Assessment$dg$, $dg$Data Sharing Agreement$dg$]::text[], true, 70) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-004$dg$, $dg$REQ-031-3$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(3)$dg$, NULL, $dg$Section 31(3)$dg$, $dg$The data controller shall, notwithstanding subsection (2), be required to make a provisional evaluation of the necessity for the transfer of the personal data.$dg$, $dg$Controller provisional evaluation of transfer necessity$dg$, $dg$Before transferring, the controller carries out and records its own provisional evaluation of whether the transfer is necessary, independently of the recipient statement.$dg$, $dg$Before you send personal data abroad, do you make and record your own judgement that the transfer is necessary?$dg$, $dg$The Act imposes this duty on the controller in addition to the recipient having to establish a ground. Relying only on what the recipient says does not discharge it.$dg$, $dg$Complete a short provisional evaluation per transfer: what data, why it must go, whether a lesser alternative would work, and who decided. Do it before the transfer starts.$dg$, $dg$A dated provisional evaluation on file for every transfer, completed before the transfer began.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. This is an express, controller-specific duty that is separate from the recipient obligation and is frequently overlooked.$dg$, $dg$Create a provisional evaluation template and complete it retrospectively for live transfers, then make it a pre-transfer gate.$dg$, $dg$Complete a provisional necessity evaluation for every cross-border transfer$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not define what a provisional evaluation must contain, nor when it ceases to be provisional.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Assessment$dg$, $dg$Provisional Necessity Evaluation$dg$, $dg$DPO Approval Record$dg$]::text[], true, 71) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-005$dg$, $dg$REQ-031-4$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(4)$dg$, NULL, $dg$Section 31(4)$dg$, $dg$The recipient shall ensure that the necessity for the transfer of the personal data can be subsequently verified.$dg$, $dg$Recipient maintains verifiable evidence of necessity$dg$, $dg$Transfer arrangements require the recipient to keep records that allow the necessity for the transfer to be verified later.$dg$, $dg$Have you required your overseas recipients to keep records that would let the necessity for the transfer be checked afterwards?$dg$, $dg$The duty falls on the recipient, but you are the one who will be asked. A contractual record-keeping obligation is how you make it real.$dg$, $dg$Include a record-keeping and verification clause in the transfer agreement, with a right to request evidence. Note that this obligation is placed on the recipient by the Act.$dg$, $dg$A verification and record-keeping clause in every cross-border transfer agreement.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The statutory duty is on the recipient, so the controller exposure is indirect, but without the clause the controller has no way to obtain the evidence.$dg$, $dg$Add a verification clause at the next contract renewal for each recipient.$dg$, $dg$Add a necessity verification clause to cross-border transfer agreements$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 31(4) imposes the duty on the recipient. DataGuard treats securing it contractually as the controller practical route, which is IMPLEMENTATION_GUIDANCE rather than a statutory duty on the controller.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Sharing Agreement$dg$, $dg$Processor Agreement$dg$, $dg$Transfer Assessment$dg$]::text[], true, 72) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-006$dg$, $dg$REQ-031-5$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(5)$dg$, NULL, $dg$Section 31(5)$dg$, $dg$The data controller shall ensure that the recipient shall process the personal data for the purposes for which it was transferred.$dg$, $dg$Recipient processing limited to the transfer purpose$dg$, $dg$The controller ensures, contractually and in practice, that the recipient processes the transferred data only for the purposes for which it was transferred.$dg$, $dg$Do you make sure your overseas recipients only use the data for the purpose you sent it for?$dg$, $dg$The Act makes this the controller responsibility, not the recipient. Sending the data does not transfer the accountability.$dg$, $dg$State the permitted purposes explicitly in the transfer agreement, prohibit onward use and onward transfer without consent, and seek periodic confirmation of compliance.$dg$, $dg$Purpose limitation clauses in every transfer agreement plus periodic confirmation from the recipient.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The duty to ensure rests expressly on the controller, so recipient misuse is a controller failure.$dg$, $dg$Add explicit purpose limitation and onward transfer clauses, and introduce annual confirmation requests.$dg$, $dg$Bind recipients to the transfer purpose and obtain periodic confirmation$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Sharing Agreement$dg$, $dg$Processor Agreement$dg$, $dg$Recipient Compliance Confirmation$dg$]::text[], true, 73) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-031-007$dg$, $dg$REQ-031-1$dg$, $dg$V$dg$, $dg$31$dg$, $dg$31(1)$dg$, NULL, $dg$Section 31(1)$dg$, $dg$The Commission may, subject to the provisions of this Act, prohibit the transfer of personal data to a place outside the country.$dg$, $dg$Compliance with Commission transfer prohibitions$dg$, $dg$The organisation monitors for and complies with any prohibition issued by the Commission on transfers to a place outside the country.$dg$, $dg$Do you check whether the Commission has prohibited transfers to any of the places you send data to, and could you stop such a transfer quickly?$dg$, $dg$A prohibition can arrive at any time. Being able to identify and suspend the affected flows quickly is what turns a notice into a manageable event.$dg$, $dg$Add Commission announcements to the regulatory monitoring list. Ensure the transfer inventory is structured so affected flows can be identified and suspended by destination.$dg$, $dg$Regulatory monitoring covers Commission transfer prohibitions, and the transfer inventory supports suspension by destination.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. A prohibition is a contingent event, but continuing a prohibited transfer would be a direct and serious contravention.$dg$, $dg$Add Commission transfer prohibitions to the regulatory monitoring list and confirm the inventory can be filtered by destination.$dg$, $dg$Monitor for and be able to act on Commission transfer prohibitions$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Change Log$dg$, $dg$Transfer Inventory$dg$, $dg$Incident and Escalation Procedure$dg$]::text[], true, 74) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-032-001$dg$, $dg$REQ-032-1$dg$, $dg$V$dg$, $dg$32$dg$, $dg$32(1)$dg$, NULL, $dg$Section 32(1)$dg$, $dg$Personal data may be transferred to recipient states other than those referred to under section 31 if an adequate level of protection is ensured in the country of the recipient and the personal data is transferred solely to permit processing authorised to be undertaken by the controller.$dg$, $dg$Transfer solely to permit processing authorised to the controller$dg$, $dg$Transfers under section 32(1) are limited to processing that the controller is itself authorised to undertake, and this limitation is documented and enforced.$dg$, $dg$Where you transfer data under section 32, is it only so the recipient can carry out processing you are yourself authorised to do?$dg$, $dg$A transfer cannot be used to have someone abroad do something you could not lawfully do yourself. This limit is easy to breach when a supplier offers an extra service.$dg$, $dg$Map the recipient processing operations back to the controller own authorised purposes. Reject any recipient activity that exceeds them.$dg$, $dg$A documented mapping of recipient processing to the controller authorised processing for each section 32 transfer.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data to a country not assessed under section 31 as having an adequate legal framework?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Transfers that enable processing beyond the controller own authority breach both section 32(1) and the purpose limitation duties in sections 25 and 26.$dg$, $dg$Compare each recipient scope of processing against your own authorised purposes and narrow the contract where it exceeds them.$dg$, $dg$Map recipient processing to the controller authorised processing for section 32 transfers$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Assessment$dg$, $dg$Data Sharing Agreement$dg$, $dg$Data Processing Register$dg$]::text[], true, 75) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-032-002$dg$, $dg$REQ-032-2$dg$, $dg$V$dg$, $dg$32$dg$, $dg$32(2)$dg$, $dg$(a)-(f)$dg$, $dg$Section 32(2)(a)-(f)$dg$, $dg$The adequacy of the level of protection afforded by the relevant third country shall be assessed in the light of all the circumstances surrounding the transfer, the nature of the personal data, the purpose and duration of the proposed processing, the recipient country, the relevant laws in force in the third country, and the professional rules and security measures complied with in that country.$dg$, $dg$Adequacy assessment against the six statutory factors$dg$, $dg$Each destination country adequacy assessment addresses all six factors listed in section 32(2) and records the conclusion.$dg$, $dg$Does your assessment of each destination country cover all six factors the Act lists, including the laws in force there and the security measures actually followed?$dg$, $dg$The Act enumerates the factors. An assessment that skips some of them is incomplete on the face of the section, whatever its conclusion.$dg$, $dg$Use an assessment template with one section per factor (a) to (f). Record the evidence considered, the conclusion and the date, and have the data protection officer approve it.$dg$, $dg$A completed six-factor assessment per destination country, approved and dated, reviewed at least annually.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The factors are enumerated in the Act, so an incomplete assessment is visibly deficient and cannot support the transfer.$dg$, $dg$Adopt a six-factor template and rework existing assessments against it, taking legal input on the third country laws factor.$dg$, $dg$Complete a six-factor adequacy assessment for each destination country$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$DataGuard must not pre-populate conclusions for any country. Factor (e), the relevant laws in force in the third country, generally requires legal input.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Assessment$dg$, $dg$Adequacy Assessment Template$dg$, $dg$External Counsel Advice$dg$, $dg$DPO Approval Record$dg$]::text[], true, 76) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-032-003$dg$, $dg$REQ-032-3$dg$, $dg$V$dg$, $dg$32$dg$, $dg$32(3)$dg$, NULL, $dg$Section 32(3) read with section 64(2)(k)$dg$, $dg$The Minister shall, after consultation with the Commission and by regulations, specify categories of processing for which and the circumstances in which the transfer of personal data to countries outside the United Republic is not authorised.$dg$, $dg$Monitoring of prohibited transfer categories set by regulations$dg$, $dg$The organisation monitors for regulations specifying categories of processing and circumstances in which transfers are not authorised, and checks its transfers against them.$dg$, $dg$Do you check whether regulations forbid transferring certain categories of data or in certain circumstances?$dg$, $dg$Section 32(3) uses shall, so these regulations are contemplated rather than optional. When they arrive they may prohibit transfers you are currently making.$dg$, $dg$Add section 32(3) regulations to the regulatory monitoring list. When made, assess every entry in the transfer inventory against them.$dg$, $dg$A regulatory monitoring record covering section 32(3), with an assessment of the transfer inventory against any regulations in force.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data outside Tanzania?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The obligation is contingent on regulations, but a prohibited transfer that continues unnoticed is a serious contravention.$dg$, $dg$Add section 32(3) and section 64(2)(k) to the regulatory monitoring list.$dg$, $dg$Monitor for regulations prohibiting categories of transborder transfer$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$REGULATORY_DETAIL_PENDING. The Act does not itself specify any prohibited category. DataGuard must not pre-populate one.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Change Log$dg$, $dg$Transfer Inventory$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 77) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-032-004$dg$, $dg$REQ-032-4$dg$, $dg$V$dg$, $dg$32$dg$, $dg$32(4)$dg$, $dg$(a)-(f)$dg$, $dg$Section 32(4)(a)-(f)$dg$, $dg$A transfer to a country outside the United Republic or to a country without an adequate level of protection may take place where the data subject has consented to the proposed transfer; the transfer is necessary for the performance of a contract between the data subject and the controller or for pre-contractual measures taken at the data subject request; the transfer is necessary for the conclusion or performance of a contract between the controller and a third party in the interest of the data subject; the transfer is necessary or legally required on public interest grounds or for the institution, trial or defence of legal claims; the transfer is necessary to protect the legitimate interests of the data subject; or the transfer is made in accordance with the law and is intended to provide information to the public and is open for consultation.$dg$, $dg$Documented reliance on a section 32(4) transfer derogation$dg$, $dg$Where a transfer relies on a derogation, the specific limb of section 32(4) is identified, justified and recorded before the transfer.$dg$, $dg$Where you transfer data to a country without adequate protection, have you recorded which specific legal exception allows it?$dg$, $dg$The derogations are specific and mostly narrow. Recording which one applies is what distinguishes a considered decision from an unexamined transfer.$dg$, $dg$Record the limb, the justification, the approver and the date for each transfer relying on a derogation. Where consent is relied on, hold the consent record and confirm it covers the proposed transfer specifically.$dg$, $dg$A derogation register with limb, justification, approver and date for every transfer relying on section 32(4).$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you transfer personal data to a country that does not have an adequate level of protection?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. A transfer to an inadequate destination with no recorded derogation has no lawful basis, and the derogations cannot be reconstructed retrospectively with any credibility.$dg$, $dg$Create the derogation register, assess each existing transfer to an inadequate destination, and suspend any transfer with no available limb.$dg$, $dg$Record the section 32(4) derogation relied on for each transfer$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Transfer Derogation Register$dg$, $dg$Consent Record$dg$, $dg$Contract$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 78) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-032-005$dg$, $dg$REQ-032-5$dg$, $dg$V$dg$, $dg$32$dg$, $dg$32(5)$dg$, NULL, $dg$Section 32(5)$dg$, $dg$The Commission may authorise a transfer of personal data to a country which does not have an adequate level of protection if the data controller satisfies the Commission that there are adequate safeguards with respect to the protection of personal data, fundamental rights and freedoms of the data subject and the exercise of the data subject rights, and that such safeguards can be appropriated through adequate legal and security measures and contractual clauses in particular.$dg$, $dg$Commission authorisation on the basis of adequate safeguards$dg$, $dg$Where a transfer to an inadequate destination proceeds on the basis of safeguards, the organisation has satisfied the Commission and holds the authorisation.$dg$, $dg$Where you rely on safeguards such as contract clauses to transfer data to a country without adequate protection, have you obtained the Commission authorisation?$dg$, $dg$On the wording of section 32(5) the safeguards route runs through the Commission. Putting contractual clauses in place is the evidence you present, not the authorisation itself.$dg$, $dg$Assemble the safeguards package - contractual clauses, security measures, and how data subject rights will be exercised - and apply to the Commission. Retain the authorisation and the conditions attached to it.$dg$, $dg$A Commission authorisation on file for each transfer relying on the safeguards route, with the safeguards package retained.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you rely on contractual clauses or other safeguards to transfer personal data to a country without adequate protection?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$CROSS_BORDER_TRANSFER$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Relying on safeguards without the Commission authorisation leaves an ongoing transfer to an inadequate destination with no lawful footing.$dg$, $dg$Prepare the safeguards package and apply to the Commission, or move the transfer onto a section 32(4) derogation, or suspend it.$dg$, $dg$Obtain Commission authorisation for safeguards-based transfers$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not prescribe the application procedure, the form of the safeguards, or the time within which the Commission must decide. It also does not publish approved standard contractual clauses.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Commission Authorisation$dg$, $dg$Contractual Safeguards Package$dg$, $dg$Transfer Assessment$dg$, $dg$Security Measures Description$dg$]::text[], true, 79) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-033-001$dg$, $dg$REQ-033-1A$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$33(1)$dg$, $dg$(a)$dg$, $dg$Section 33(1)(a)$dg$, $dg$A data subject shall be entitled to be informed by any data controller whether his personal data are being processed by or on behalf of that data controller.$dg$, $dg$Right of access - confirmation of processing$dg$, $dg$On request, the organisation can confirm to an individual whether it processes their personal data, including processing carried out on its behalf.$dg$, $dg$If someone asks whether you hold or use their personal data, can you find out and tell them - including data held by your suppliers on your behalf?$dg$, $dg$This is the first step of the access right. Answering it requires being able to search across your systems and your processors, which many organisations cannot do quickly.$dg$, $dg$Define the request intake channel, identity verification, and the systems and processors to be searched. Keep a request log. Test the search end to end at least annually.$dg$, $dg$A documented access request procedure with a search map covering all systems and processors, and a request log.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Access is the most frequently exercised right and the most common subject of complaints to a regulator.$dg$, $dg$Write the access procedure, map where personal data lives, and rehearse a request end to end.$dg$, $dg$Implement a data subject access request procedure$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not prescribe a response time, a form of request, or any fee for access requests under section 33.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Subject Rights Procedure$dg$, $dg$Rights Request Log$dg$, $dg$System Search Map$dg$, $dg$Processor Agreement$dg$]::text[], true, 80) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-033-002$dg$, $dg$REQ-033-1B$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$33(1)$dg$, $dg$(b)$dg$, $dg$Section 33(1)(b)(i)-(iii)$dg$, $dg$A data subject shall be entitled to be given a description of the personal data of which that individual is the data subject, the purposes for which they are being processed, and the recipients or classes of recipients to whom they are or may be disclosed.$dg$, $dg$Right of access - description of data, purposes and recipients$dg$, $dg$The organisation can provide a description of the personal data held about an individual, the purposes of processing, and the recipients or classes of recipients.$dg$, $dg$Can you tell someone what personal data you hold about them, why you use it, and who you share it with?$dg$, $dg$All three elements are required. The recipients element is the one most often missed, and it depends on having a disclosure register.$dg$, $dg$Use a response template covering all three elements. Draw the purposes from the processing register and the recipients from the disclosure register so the answer is consistent with your other records.$dg$, $dg$A response template covering the three statutory elements, with completed responses retained.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. An incomplete access response is itself a contravention and is easy for the Commission to verify against your own registers.$dg$, $dg$Build the response template and link it to the processing and disclosure registers.$dg$, $dg$Create an access response template covering data, purposes and recipients$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Access Response Template$dg$, $dg$Rights Request Log$dg$, $dg$Data Processing Register$dg$, $dg$Disclosure Register$dg$]::text[], true, 81) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-033-003$dg$, $dg$REQ-033-1C$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$33(1)$dg$, $dg$(c)$dg$, $dg$Section 33(1)(c)$dg$, $dg$Where processing by automatic means for the purpose of evaluating matters relating to the data subject has constituted or is likely to constitute the sole basis for any decision significantly affecting him, the data subject is entitled to be informed of the logic involved in that decision making.$dg$, $dg$Disclosure of the logic involved in automated decision making$dg$, $dg$Where an automated evaluation is or is likely to be the sole basis of a significant decision, the organisation can explain the logic involved to the data subject.$dg$, $dg$Where a computer alone makes or is likely to make a decision that significantly affects someone, can you explain to them how that decision is reached?$dg$, $dg$This obliges you to be able to describe how your model or rule set reaches a decision. Systems bought or built without that in mind cannot meet it later without rework.$dg$, $dg$Inventory automated evaluation and scoring systems. For each, prepare a plain-language description of the logic. Note that the right attaches where such processing is likely to constitute the sole basis, not only where it already has.$dg$, $dg$A maintained inventory of automated decision systems, each with an approved plain-language logic description.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you use automated processing to evaluate people in a way that is, or could be, the sole basis of a decision significantly affecting them?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$AUTOMATED_DECISION_MAKING$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Automated evaluation carries significant potential for harm, and the inability to explain the logic is often structural rather than procedural.$dg$, $dg$Inventory automated evaluation systems and commission a plain-language logic description for each, starting with those affecting credit, employment or access to services.$dg$, $dg$Prepare plain-language logic descriptions for automated decision systems$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not define significantly affecting or specify the required depth of the logic description.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Automated Decision System Inventory$dg$, $dg$Model Logic Description$dg$, $dg$Access Response Template$dg$, $dg$Technical Design Document$dg$]::text[], true, 82) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-033-004$dg$, $dg$REQ-033-2$dg$, $dg$VI$dg$, $dg$33$dg$, $dg$33(2)$dg$, $dg$(a)-(c)$dg$, $dg$Section 33(2)(a)-(c)$dg$, $dg$A data controller is not obliged to inform the data subject where the personal data are not accurate, are involved in any investigation in accordance with the laws, or have been prohibited by court order.$dg$, $dg$Documented reliance on access exceptions$dg$, $dg$Where an access request is refused in reliance on section 33(2), the specific ground is identified and recorded.$dg$, $dg$Where you decline to give someone information about their data, have you recorded which of the three legal grounds applies?$dg$, $dg$The grounds are narrow and specific. Recording which one applies protects the decision if it is later challenged.$dg$, $dg$Record the ground and the reasoning against the request log. For the investigation ground, record the investigation reference. For the court order ground, retain the order.$dg$, $dg$Every refused access request has a recorded ground, reasoning and supporting document where applicable.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Have you refused, or might you refuse, an access request?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The exceptions are lawful, so the risk is over-reliance on them without a recorded basis.$dg$, $dg$Add a ground field to the request log and require it for every refusal.$dg$, $dg$Record the section 33(2) ground for each refused access request$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 33(2)(a) removes the obligation where the personal data are not accurate. INTERPRETATION: this ground is unusual and its scope is not elaborated in the Act. Take advice before relying on it.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Rights Request Log$dg$, $dg$Refusal Notice Template$dg$, $dg$Court Order$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 83) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-034-001$dg$, $dg$REQ-034-1$dg$, $dg$VI$dg$, $dg$34$dg$, $dg$34(1)$dg$, NULL, $dg$Section 34(1)$dg$, $dg$A data subject is entitled to require a data controller, through procedures prescribed in the regulations, to suspend or not to begin processing of any personal data in respect of which he is the data subject, if the processing is likely to cause substantial damage to him or to another person.$dg$, $dg$Right to prevent processing likely to cause substantial damage$dg$, $dg$A procedure receives and assesses requests to suspend or not begin processing on substantial damage grounds, and can technically implement a suspension.$dg$, $dg$If someone asks you to stop or not start processing their data because it would cause them substantial damage, can you assess that and actually suspend the processing?$dg$, $dg$Suspension has to work in the systems, not just on paper. Many platforms can delete a record but cannot pause processing of it.$dg$, $dg$Define intake, assessment criteria and the decision maker, and confirm each relevant system can suspend rather than only delete. Record the decision and its reasons either way.$dg$, $dg$A documented procedure plus verified technical capability to suspend processing on a per-record basis.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DATA_SUBJECT_RIGHTS$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. The right is engaged precisely where substantial damage is in prospect, so a failure here coincides with the greatest potential harm.$dg$, $dg$Add the right to the rights procedure and verify suspension capability in each system holding personal data.$dg$, $dg$Implement the right to prevent processing, including technical suspension capability$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$The procedure is to be prescribed by regulations. Section 34(2) provides that the right does not apply in the exceptions provided under the Act. OPEN_QUESTION: substantial damage is not defined, and section 34(2) does not identify which exceptions it refers to.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Subject Rights Procedure$dg$, $dg$Rights Request Log$dg$, $dg$System Suspension Capability Evidence$dg$]::text[], true, 84) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-035-001$dg$, $dg$REQ-035-1$dg$, $dg$VI$dg$, $dg$35$dg$, $dg$35(1)$dg$, NULL, $dg$Section 35(1) and 35(3)$dg$, $dg$A data subject may, through the procedures prescribed in the regulations, require the data controller to stop processing his personal data for purposes of direct marketing. Direct marketing includes the communication by whatever means of any advertising or marketing material which is directed at an individual.$dg$, $dg$Right to stop direct marketing$dg$, $dg$A working opt-out mechanism stops direct marketing to an individual on request, across all channels and all marketing systems.$dg$, $dg$If someone asks you to stop marketing to them, does that stop across every channel you use - email, SMS, phone, post and any other?$dg$, $dg$The definition covers advertising or marketing material by whatever means. An opt-out that only stops email leaves the obligation unmet.$dg$, $dg$Maintain a suppression list that all marketing systems consult, including any run by agencies or partners. Test that an opt-out propagates within a defined internal period, and record opt-outs.$dg$, $dg$A central suppression list honoured by every marketing channel and by third party marketing partners, with propagation tested.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you carry out direct marketing to individuals by any means?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$DIRECT_MARKETING$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Failures are immediately visible to the individual, easily evidenced by them, and typically repeat with every campaign until fixed.$dg$, $dg$Consolidate suppression into a single list, connect every marketing system to it, and extend the obligation to agencies contractually.$dg$, $dg$Implement a cross-channel marketing suppression capability$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$The procedure is to be prescribed by regulations. OPEN_QUESTION: the Act sets no period within which marketing must cease after a request.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Suppression List Configuration$dg$, $dg$Marketing Opt-out Log$dg$, $dg$Data Subject Rights Procedure$dg$, $dg$Agency Agreement$dg$]::text[], true, 85) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-035-002$dg$, $dg$REQ-035-2$dg$, $dg$VI$dg$, $dg$35$dg$, $dg$35(2)$dg$, NULL, $dg$Section 35(2)$dg$, $dg$A data subject may enter into agreement with a data controller for purposes of using or processing his personal data for pecuniary benefits.$dg$, $dg$Agreements for use of personal data for pecuniary benefit$dg$, $dg$Where an individual agrees to their personal data being used for pecuniary benefit, that agreement is documented and its scope is respected.$dg$, $dg$Do you have any arrangements where people agree to let you use their personal data in return for a payment or benefit, and are those agreements documented?$dg$, $dg$The Act expressly contemplates these arrangements. They still have to respect the rest of the Act, including the marketing opt-out right in section 35(1).$dg$, $dg$Document the agreement, its scope and its duration. Confirm the arrangement does not override the individual ability to withdraw or to stop marketing, and take advice where the arrangement involves sensitive personal data.$dg$, $dg$Written agreements on file with defined scope and duration, and no conflict with other rights under the Act.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you have arrangements where individuals receive payment or another benefit for the use of their personal data?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$DIRECT_MARKETING$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The arrangement is expressly permitted, so the risk lies in undocumented scope or in the agreement being treated as overriding other rights.$dg$, $dg$Document existing arrangements and review them against the rest of the Act.$dg$, $dg$Document any agreements for use of personal data for pecuniary benefit$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not set conditions or limits for these agreements beyond section 35(2) itself.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Use Agreement$dg$, $dg$Consent Record$dg$, $dg$Legal Assessment Note$dg$]::text[], false, 86) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggeste