insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-036-001$dg$, $dg$REQ-036-1$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$36(1)$dg$, NULL, $dg$Section 36(1)$dg$, $dg$A data subject may, through the procedures prescribed in the regulations, require the data controller to ensure that any decision taken by or on behalf of the data controller which significantly affects the data subject shall not be based solely on the processing by automatic means.$dg$, $dg$Right to require human involvement in significant decisions$dg$, $dg$On request, the organisation can ensure that a decision significantly affecting the individual is not based solely on automated processing.$dg$, $dg$If someone asks that a significant decision about them is not made by computer alone, can you arrange for a person to be involved?$dg$, $dg$Meeting this request requires a real human review path, with someone who has the authority and information to reach a different outcome.$dg$, $dg$Identify decisions that are solely automated and significant. Establish a human review path with a named reviewer able to change the outcome, and record each review.$dg$, $dg$A documented human review path for each solely automated significant decision, with reviews logged.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you make decisions that significantly affect people based solely on automated processing?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$AUTOMATED_DECISION_MAKING$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Solely automated significant decisions concentrate potential harm, and a review path that cannot change the outcome is not a review path.$dg$, $dg$Inventory solely automated significant decisions and build a genuine human review path for each.$dg$, $dg$Establish a human review path for solely automated significant decisions$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$The procedure for exercising the right is to be prescribed by regulations.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Automated Decision System Inventory$dg$, $dg$Human Review Procedure$dg$, $dg$Review Decision Log$dg$]::text[], true, 87) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_gu