insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-036-002$dg$, $dg$REQ-036-2$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$36(2)$dg$, $dg$(a)$dg$, $dg$Section 36(2)(a)$dg$, $dg$Where a decision which significantly affects a data subject is based solely on automated processing, the data controller shall, as soon as practicable, notify the data subject that the decision was taken on that basis.$dg$, $dg$Proactive notification of solely automated decisions$dg$, $dg$Where a significant decision is based solely on automated processing, the individual is notified of that fact as soon as practicable, without waiting to be asked.$dg$, $dg$When a computer alone makes a significant decision about someone, do you tell them that is how the decision was made?$dg$, $dg$This duty is proactive. Unlike the other rights in Part VI it is not triggered by a request, so it must be built into the decision process itself.$dg$, $dg$Add the notification to the decision output - the letter, email or portal message. Retain evidence that it was sent.$dg$, $dg$Notification text embedded in every solely automated significant decision output, with dispatch evidence retained.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you make decisions that significantly affect people based solely on automated processing?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$AUTOMATED_DECISION_MAKING$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. This is a proactive duty that operates on every affected decision, so a gap is systematic rather than occasional.$dg$, $dg$Add the notification into the decision output templates and confirm dispatch is logged.$dg$, $dg$Add automated decision notification to decision output templates$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: as soon as practicable is not defined in the Act.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Decision Notification Template$dg$, $dg$Sent Notification Records$dg$, $dg$Automated Decision System Inventory$dg$]::text[], true, 88) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.cont