insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-036-003$dg$, $dg$REQ-036-2$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$36(2)$dg$, $dg$(b)$dg$, $dg$Section 36(2)(b)$dg$, $dg$The data subject may require the data controller to reconsider a decision which significantly affects him and which is based solely on automated processing.$dg$, $dg$Reconsideration of a solely automated decision on request$dg$, $dg$A procedure allows a data subject to require reconsideration of a solely automated significant decision, and reconsiderations are carried out and recorded.$dg$, $dg$If someone asks you to reconsider a decision that was made by computer alone, do you have a process to do that and record the outcome?$dg$, $dg$Reconsideration must be capable of producing a different answer. A rerun of the same model is not a reconsideration.$dg$, $dg$Define who reconsiders, what information they see, the outcome options, and how the result is communicated. Log each reconsideration and its outcome.$dg$, $dg$A reconsideration procedure with a log recording each request, reviewer, outcome and date.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you make decisions that significantly affect people based solely on automated processing?$dg$, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$AUTOMATED_DECISION_MAKING$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Reconsideration is the individual practical remedy against an automated decision, and its absence leaves them with only a complaint to the Commission.$dg$, $dg$Write the reconsideration procedure, name the reviewers, and start the log.$dg$, $dg$Implement a reconsideration process for automated decisions$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not state what reconsideration must involve or within what period it must be completed.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Reconsideration Procedure$dg$, $dg$Reconsideration Log$dg$, $dg$Rights Request Log$dg$]::text[], true, 89) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-036-004$dg$, $dg$REQ-036-3$dg$, $dg$VI$dg$, $dg$36$dg$, $dg$36(3)$dg$, $dg$(a)-(c)$dg$, $dg$Section 36(3)(a)-(c)$dg$, $dg$Section 36 shall not apply if the decision is necessary for entering into, or performance of, a contract between the data subject and a data controller; is authorised by any written law; or is based on the data subject explicit consent.$dg$, $dg$Documented reliance on automated decision exceptions$dg$, $dg$Where section 36 is treated as inapplicable, the specific exception is identified and recorded per decision type.$dg$, $dg$Where you treat the automated decision rules as not applying, have you recorded which of the three exceptions you rely on?$dg$, $dg$Two of the exceptions - contractual necessity and explicit consent - are frequently asserted and rarely documented. The record is what makes the position defensible.$dg$, $dg$Record the exception per decision type with a justification. Where explicit consent is relied on, hold the consent record and confirm it covers automated decision making specifically.$dg$, $dg$An exception record per automated decision type, with supporting consent or contract evidence.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you make decisions that significantly affect people based solely on automated processing?$dg$, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$AUTOMATED_DECISION_MAKING$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The exceptions are lawful, so the risk is asserting one without analysis rather than the exception itself.$dg$, $dg$Document the exception relied on for each automated decision type and verify the supporting evidence exists.$dg$, $dg$Record the section 36(3) exception relied on for each automated decision type$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Note that section 36(3) disapplies section 36 as a whole, including the notification duty in section 36(2)(a). The section 33(1)(c) right to be informed of the logic involved is in a different section and is not disapplied by section 36(3).$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Automated Decision System Inventory$dg$, $dg$Consent Record$dg$, $dg$Contract$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 90) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-037-001$dg$, $dg$REQ-037-1$dg$, $dg$VI$dg$, $dg$37$dg$, $dg$37(1)$dg$, NULL, $dg$Sections 37(1) and 37(2)$dg$, $dg$A data subject who suffers damage by reason of any contravention of any of the requirements of this Act by a data controller or data processor shall be entitled to compensation from the data controller or data processor for that damage, where the complainant is the affected data subject or a representative of a data subject who is a child or a person of unsound mind, the rights have been infringed by reason of the contravention, and the damage relates to processing in contravention of the Act.$dg$, $dg$Handling of compensation claims from data subjects$dg$, $dg$A defined process receives, assesses and responds to claims for compensation for damage caused by a contravention of the Act.$dg$, $dg$If someone claims they have been harmed by the way you handled their data and asks for compensation, do you have a process to assess and respond to that?$dg$, $dg$Compensation claims can be brought directly and may also come through the Commission under section 50. Handling the first one without a process usually goes badly.$dg$, $dg$Define intake, legal assessment, escalation and record keeping. Preserve evidence relating to the alleged contravention as soon as a claim arrives. Notify insurers where relevant.$dg$, $dg$A documented claims handling procedure with a claims register and defined evidence preservation steps.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The exposure is real but reactive. The primary defence is compliance with the substantive controls rather than the claims process itself.$dg$, $dg$Write the claims handling procedure and agree the escalation path with legal and finance.$dg$, $dg$Establish a procedure for handling data subject compensation claims$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 50(4) defines damage as including financial loss and damage not involving financial loss. Section 50(3) provides a defence where the controller or processor proves it was not in any way responsible for the event that caused the damage.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Claims Handling Procedure$dg$, $dg$Claims Register$dg$, $dg$Incident Response Procedure$dg$, $dg$Legal Assessment Note$dg$]::text[], true, 91) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-037-002$dg$, $dg$REQ-037-3$dg$, $dg$VI$dg$, $dg$37$dg$, $dg$37(3)$dg$, NULL, $dg$Section 37(3)$dg$, $dg$Where the Commission is satisfied that a data subject has suffered damage entitling him to compensation and that there is a substantial risk of further contravention, the Commission may order the rectification, blocking, erasure or destruction of any of the personal data.$dg$, $dg$Capability to execute a Commission rectification, blocking, erasure or destruction order$dg$, $dg$The organisation can technically and procedurally execute an order to rectify, block, erase or destroy specified personal data, and evidence that it has done so.$dg$, $dg$If the Commission ordered you to correct, block, erase or destroy specific personal data, could you do it across all your systems and prove it?$dg$, $dg$Blocking in particular is a capability most systems lack. An order arrives with a deadline, which is the wrong moment to discover the gap.$dg$, $dg$Verify each system can rectify, block, erase and destroy at record level, including archives, backups and copies held by processors. Define how execution is evidenced. Sequence any erasure against the section 29(2) preservation duty.$dg$, $dg$Verified rectify, block, erase and destroy capability across all systems holding personal data, with an evidencing method defined.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. An order carries a deadline, and inability to comply escalates directly into the enforcement and penalty regime in sections 45 to 47.$dg$, $dg$Assess each system for the four capabilities and remediate gaps, prioritising blocking, which is most often missing.$dg$, $dg$Verify rectify, block, erase and destroy capability across all systems$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$System Capability Assessment$dg$, $dg$Order Execution Log$dg$, $dg$Processor Agreement$dg$, $dg$Technical Design Document$dg$]::text[], true, 92) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-037-003$dg$, $dg$REQ-037-4$dg$, $dg$VI$dg$, $dg$37$dg$, $dg$37(4)$dg$, NULL, $dg$Sections 37(4) and 37(5)$dg$, $dg$The Commission may, where it makes an order under subsection (3) and where it considers it reasonable, order the data controller or data processor to notify third parties to whom the personal data have been disclosed of the rectification, blocking, erasure or destruction. In determining whether it is reasonably practicable to require the notification, the Commission shall have regard in particular to the number of persons who need to be notified.$dg$, $dg$Ability to notify third party recipients following a Commission order$dg$, $dg$The organisation can identify and notify the third parties to whom affected personal data was disclosed, when ordered to do so.$dg$, $dg$Could you identify and contact everyone you have shared a person data with, if the Commission ordered you to tell them about a correction or deletion?$dg$, $dg$This depends entirely on the disclosure register. Without a record of who received what, the order cannot be complied with at all.$dg$, $dg$Keep the disclosure register at a level of detail that allows recipients to be identified per data subject. Hold current contact details for each recipient and prepare a notification template.$dg$, $dg$A disclosure register that supports per-data-subject recipient identification, with recipient contacts current.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The duty is contingent on a Commission order, but the underlying record keeping must be in place well before one arrives.$dg$, $dg$Enrich the disclosure register so recipients can be traced per data subject, and keep recipient contacts current.$dg$, $dg$Ensure the disclosure register supports per-data-subject recipient notification$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Disclosure Register$dg$, $dg$Recipient Contact List$dg$, $dg$Notification Template$dg$, $dg$Order Execution Log$dg$]::text[], true, 93) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-038-001$dg$, $dg$REQ-038-1$dg$, $dg$VI$dg$, $dg$38$dg$, $dg$38(1)$dg$, NULL, $dg$Sections 38(1) and 38(2)$dg$, $dg$Where the Commission is satisfied on the application of a data subject that his personal data is inaccurate, the Commission may order the data controller or data processor to rectify, block, erase or destroy the personal data. This applies whether or not the personal data is an accurate record of information received or obtained by the data controller from the data subject or a third party.$dg$, $dg$Compliance with a Commission order on inaccurate personal data$dg$, $dg$The organisation can comply with a Commission order to rectify, block, erase or destroy inaccurate personal data, including data accurately recorded from a third party source.$dg$, $dg$If the Commission ordered you to correct or remove inaccurate personal data, could you comply - even where you recorded it accurately from someone else?$dg$, $dg$Section 38(2) is explicit: it does not matter that you faithfully recorded what a third party told you. Accurate transcription of wrong information is still inaccurate personal data.$dg$, $dg$Confirm you can correct data originating from third party sources without the correction being overwritten at the next data refresh. Record the order and the action taken.$dg$, $dg$Verified ability to correct third party sourced data durably, with an order execution log.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Failing to comply with a Commission order leads directly to enforcement under section 45 and a penalty notice under section 46.$dg$, $dg$Test correction of third party sourced records and confirm the correction survives the next data refresh.$dg$, $dg$Verify durable correction of third party sourced personal data$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Order Execution Log$dg$, $dg$System Capability Assessment$dg$, $dg$Data Source Register$dg$, $dg$Rectification Log$dg$]::text[], true, 94) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-038-002$dg$, $dg$REQ-038-3$dg$, $dg$VI$dg$, $dg$38$dg$, $dg$38(3)$dg$, NULL, $dg$Section 38(3)$dg$, $dg$Where the personal data is not an accurate record of the information, the Commission may direct the data controller or processor to correct the personal data as it considers appropriate.$dg$, $dg$Compliance with a Commission direction to correct personal data$dg$, $dg$The organisation can implement a correction in the specific terms directed by the Commission and evidence that it has done so.$dg$, $dg$If the Commission directed you to correct data in a particular way, could you carry that out exactly and show that you did?$dg$, $dg$A direction may specify the correction in particular terms. Implementing something approximate is not compliance.$dg$, $dg$Record the direction, the correction implemented, the date and the person responsible. Preserve the pre-amendment record in accordance with section 29(2).$dg$, $dg$An order execution log linking each direction to the correction made and to the preserved prior version.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Non-compliance with a direction escalates to an enforcement notice and then to a penalty notice.$dg$, $dg$Establish an order execution log and link it to the correction and version history processes.$dg$, $dg$Establish an execution log for Commission directions and orders$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Order Execution Log$dg$, $dg$Rectification Log$dg$, $dg$System Version History Configuration$dg$]::text[], true, 95) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.requi