insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-038-003$dg$, $dg$REQ-038-4$dg$, $dg$VI$dg$, $dg$38$dg$, $dg$38(4)$dg$, NULL, $dg$Section 38(4)$dg$, $dg$Where the personal data complained of has been rectified, blocked, updated, erased or destroyed under this section, the data controller or data processor shall be required to notify third parties to whom the personal data has been previously disclosed of the rectification, blocking, updating, erasure or destruction.$dg$, $dg$Notification of third parties after action under section 38$dg$, $dg$After personal data is rectified, blocked, updated, erased or destroyed under section 38, third parties previously given the data are notified.$dg$, $dg$After you correct or remove data under a Commission order, do you tell everyone you previously shared that data with?$dg$, $dg$Unlike section 37(4), this duty is not expressed as contingent on a further Commission order - section 38(4) states that the controller or processor shall be required to notify.$dg$, $dg$Trigger third party notification automatically as part of the section 38 execution process. Use the disclosure register to identify recipients and retain proof of notification.$dg$, $dg$Third party notification built into the section 38 execution process, with dispatch evidence retained.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. This duty is expressed in mandatory terms and is a second, separate contravention if missed after an order has already been made.$dg$, $dg$Add a mandatory notification step to the order execution process and pre-draft the notification template.$dg$, $dg$Build third party notification into the section 38 execution process$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$INTERPRETATION: section 38(4) is drafted in mandatory terms (shall be required to notify) and does not on its face require a further order, in contrast to section 37(4). Take advice if relying on the narrower reading.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Disclosure Register$dg$, $dg$Third Party Notification Records$dg$, $dg$Order Execution Log$dg$, $dg$Notification Template$dg$]::text[], true, 96) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-039-001$dg$, $dg$REQ-039-1$dg$, $dg$VII$dg$, $dg$39$dg$, $dg$39(1)$dg$, NULL, $dg$Section 39(1) and 39(3)$dg$, $dg$Any person who considers that a data controller or data processor has infringed personal data protection principles may file a complaint to the Commission. A complaint shall be investigated and concluded within ninety days from the date of receipt.$dg$, $dg$Internal complaint handling and readiness for Commission complaints$dg$, $dg$An internal channel receives and resolves data protection complaints, and the organisation is prepared to respond to a complaint escalated to the Commission.$dg$, $dg$Do you have a way for people to complain to you about how you handle their data, and are you ready to respond if they complain to the Commission instead?$dg$, $dg$Most complaints to a regulator start as complaints to the organisation that went unanswered. A working internal channel is the cheapest form of enforcement risk reduction.$dg$, $dg$Publish a complaint channel, log complaints with outcomes, and define who leads the response if the Commission opens an investigation. The Commission timeline is ninety days, extendable by up to a further ninety.$dg$, $dg$A published complaint channel, a complaint log with outcomes, and a named regulatory response lead.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$QUARTERLY$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The Act imposes no express internal complaints duty, but unresolved complaints are the main route into a section 39 investigation.$dg$, $dg$Publish the complaint channel, start the log, and name the regulatory response lead.$dg$, $dg$Establish an internal data protection complaints channel and log$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. Section 39 confers a right to complain to the Commission and sets the Commission timeline. It imposes no express obligation to operate an internal complaints channel; DataGuard treats that as derived good practice, not a statutory duty.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Complaints Procedure$dg$, $dg$Complaint Log$dg$, $dg$Privacy Notice$dg$, $dg$Regulatory Response Plan$dg$]::text[], true, 97) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-040-001$dg$, $dg$REQ-040-1$dg$, $dg$VII$dg$, $dg$40$dg$, NULL, NULL, $dg$Section 40$dg$, $dg$Before commencing an investigation of a complaint, the Commission shall notify the data controller or data processor concerned of the substance of the complaint and its intention to carry out the investigation, in a form prescribed in the regulations.$dg$, $dg$Handling of a notice of investigation$dg$, $dg$A defined process receives a notice of investigation from the Commission, routes it immediately to the accountable owner, and starts evidence preservation.$dg$, $dg$If a notice of investigation arrived from the Commission today, do you know who would receive it, who would own the response, and what would be preserved?$dg$, $dg$The notice tells you the substance of the complaint before the investigation starts. That window is only useful if the notice reaches the right person immediately.$dg$, $dg$Name the recipient and the response owner, define an internal acknowledgement time, and trigger a litigation-style hold on relevant records the moment a notice arrives.$dg$, $dg$A documented regulatory notice handling procedure naming the recipient, the owner and the preservation steps.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Poor handling wastes the notice period and can lead to loss of records that would have supported the organisation position.$dg$, $dg$Write the regulatory notice handling procedure and communicate it to reception, legal and IT.$dg$, $dg$Define a handling procedure for Commission notices of investigation$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$ACT_DERIVED. Section 40 imposes the duty on the Commission. The internal handling procedure is DataGuard implementation practice. The form of the notice is left to the regulations.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Response Plan$dg$, $dg$Escalation Matrix$dg$, $dg$Evidence Preservation Procedure$dg$]::text[], true, 98) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-042-001$dg$, $dg$REQ-042-1$dg$, $dg$VII$dg$, $dg$42$dg$, $dg$42(1)$dg$, $dg$(a)-(e)$dg$, $dg$Section 42(1)(a)-(e) and 42(2)$dg$, $dg$In the course of an investigation the Commission may summon a person, receive evidence, enter premises occupied by a data controller or data processor, interrogate any person or take any device with personal data in such premises, and examine or obtain copies of books, documents or records found there. The complainant and the controller or processor may be given an opportunity to make representations.$dg$, $dg$Cooperation with Commission investigation powers$dg$, $dg$Staff know how to respond when the Commission exercises its investigation powers, including attendance at premises, and the organisation can make representations.$dg$, $dg$Would your staff know what to do if officers from the Commission arrived to inspect your premises, records or devices?$dg$, $dg$The powers include entry, interrogation and taking devices. Section 43 makes obstruction a criminal offence, and an untrained receptionist can create one by accident.$dg$, $dg$Write a short regulatory visit protocol: verify identity and authority, notify legal and the data protection officer immediately, cooperate, log what is taken, and do not obstruct. Brief front-of-house and IT staff. Prepare to make representations under section 42(2).$dg$, $dg$A regulatory visit protocol issued and briefed to front-of-house, IT and management staff.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. An untrained response can create a section 43 obstruction offence, which is a criminal matter distinct from the underlying complaint.$dg$, $dg$Write and brief the regulatory visit protocol, focusing on reception and IT.$dg$, $dg$Issue and brief a Commission regulatory visit protocol$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. Section 42 confers powers on the Commission. The duty not to obstruct arises under section 43. Section 42(4) requires the Commission to return documents or articles within ten working days of a request.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Visit Protocol$dg$, $dg$Training Records$dg$, $dg$Regulatory Response Plan$dg$]::text[], true, 99) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-042-002$dg$, $dg$REQ-042-3$dg$, $dg$VII$dg$, $dg$42$dg$, $dg$42(3)$dg$, NULL, $dg$Section 42(3)$dg$, $dg$Notwithstanding any other written law, the Commission may examine any personal data recorded in any form held by a data controller or data processor and in doing so, no personal data shall be withheld from the Commission.$dg$, $dg$No personal data withheld from the Commission$dg$, $dg$The organisation understands that no personal data may be withheld from the Commission during an examination, notwithstanding other written laws, and its staff and advisers act accordingly.$dg$, $dg$Do the people who would handle a Commission examination understand that personal data cannot be withheld from it, even where another law might otherwise suggest confidentiality?$dg$, $dg$The provision overrides other written laws in this respect. Withholding data in good faith reliance on a confidentiality obligation would still be a failure, and may amount to obstruction under section 43.$dg$, $dg$State the position clearly in the regulatory visit protocol. Where a genuine conflict with another law or with privilege is asserted, escalate to counsel immediately rather than withholding unilaterally.$dg$, $dg$The regulatory visit protocol records the position and the escalation route for any asserted conflict.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The exposure arises only during an examination, but a refusal in the moment can convert a civil matter into a section 43 offence.$dg$, $dg$Add the section 42(3) position and the escalation route to the regulatory visit protocol.$dg$, $dg$Record the section 42(3) position in the regulatory visit protocol$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not address how section 42(3) interacts with legal professional privilege. Take advice rather than deciding this in the moment.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Visit Protocol$dg$, $dg$Legal Assessment Note$dg$, $dg$Training Records$dg$]::text[], true, 100) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-043-001$dg$, $dg$REQ-043-1$dg$, $dg$VII$dg$, $dg$43$dg$, NULL, $dg$(a)-(d)$dg$, $dg$Section 43(a)-(d)$dg$, $dg$A person who obstructs or impedes the Commission in the exercise of its powers, fails to provide assistance or information requested by the Commission, refuses to allow the Commission to enter any premises or to take any document or device with personal data, or gives to the Commission any information which is false or misleading, commits an offence.$dg$, $dg$Non-obstruction of the Commission$dg$, $dg$The organisation does not obstruct or impede the Commission, provides requested assistance and information, permits lawful entry, and gives accurate information.$dg$, $dg$Are your people instructed to cooperate fully with the Commission, allow lawful entry, and never give it information that is false or misleading?$dg$, $dg$Each of the four limbs is a criminal offence carrying a fine of up to five million shillings or up to two years imprisonment, or both - independent of the original complaint.$dg$, $dg$Set the cooperation expectation in policy and in the regulatory visit protocol. Require accuracy checks before any information is submitted to the Commission, and record what was provided and when.$dg$, $dg$A cooperation policy, verification of submissions before dispatch, and a record of information provided to the Commission.$dg$, $dg$YES_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Section 43 creates a criminal offence with an express penalty, and it can be committed by an individual employee acting without instruction.$dg$, $dg$Issue the cooperation policy, brief staff, and introduce a review step before any submission to the Commission.$dg$, $dg$Issue a Commission cooperation policy and brief relevant staff$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 43 provides a fine of not less than TZS 100,000 and not exceeding TZS 5,000,000, or imprisonment for not more than two years, or both. This penalty applies to section 43 specifically.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Visit Protocol$dg$, $dg$Data Protection Policy$dg$, $dg$Submission Review Record$dg$, $dg$Training Records$dg$]::text[], true, 101) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-045-001$dg$, $dg$REQ-045-1$dg$, $dg$VII$dg$, $dg$45$dg$, $dg$45(1)$dg$, NULL, $dg$Sections 45(1) and 45(2)$dg$, $dg$Where the Commission is satisfied that a person has failed to comply with any provision of this Act, it may serve an enforcement notice requiring that person to rectify the failure within the period specified in the notice. The notice shall specify the provision contravened, the measures to be taken, a period of not less than twenty-one days within which the measures shall be implemented, and shall state any right to appeal.$dg$, $dg$Compliance with an enforcement notice within the specified period$dg$, $dg$A process tracks enforcement notices, implements the specified measures within the stated period, and evidences completion.$dg$, $dg$If you received an enforcement notice, could you implement the required measures within the period given and prove you had done so?$dg$, $dg$The minimum period is twenty-one days. Failure to comply is what triggers a penalty notice under section 46, so this is the last off-ramp before a fine.$dg$, $dg$Log the notice, the provision cited, the measures required and the deadline. Assign an executive owner, track to completion, and write to the Commission with evidence before the deadline. Note the notice must state any right to appeal - see PDPA-049-001.$dg$, $dg$An enforcement notice register with owner, deadline, evidence of completion and confirmation sent to the Commission.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Non-compliance with an enforcement notice is the express precondition for a penalty notice under section 46 and moves the matter from remediable to punitive.$dg$, $dg$Create the enforcement notice register and agree the executive escalation path before any notice arrives.$dg$, $dg$Establish an enforcement notice tracking and remediation process$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$The period specified in the notice shall not be less than twenty-one days. The Act does not set a maximum.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Enforcement Notice Register$dg$, $dg$Remediation Plan$dg$, $dg$Completion Evidence$dg$, $dg$Commission Correspondence$dg$]::text[], true, 102) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-046-001$dg$, $dg$REQ-046-1$dg$, $dg$VII$dg$, $dg$46$dg$, $dg$46(2)$dg$, $dg$(a)-(k)$dg$, $dg$Section 46(2)(a)-(k)$dg$, $dg$In deciding whether to give a penalty notice and determining the amount, the Commission shall have regard to the nature, gravity and duration of the failure; its intentional or negligent character; action taken to mitigate damage including technical and organisational measures; previous failures; the degree of cooperation with the Commission; the categories of personal data affected; the manner in which the failure became known including whether the controller or processor notified the Commission; compliance with previous notices; adherence to codes of ethics or terms of registration; whether the penalty would be effective; and any other aggravating or mitigating factor including financial benefits gained or losses suffered.$dg$, $dg$Readiness to evidence the section 46(2) mitigating factors$dg$, $dg$The organisation maintains records that would evidence the mitigating factors the Commission must weigh when deciding on and setting a penalty.$dg$, $dg$If the Commission were deciding whether to fine you, could you produce evidence of your safeguards, your cooperation, your self-reporting and your code of ethics?$dg$, $dg$The eleven factors are set out in the Act, and several of them are things you either recorded at the time or cannot show at all - self-notification, cooperation, and mitigation measures in particular.$dg$, $dg$Map the factors to existing records: safeguards to the security programme, mitigation to the incident log, self-notification to the breach notification log, cooperation to Commission correspondence, and adherence to the section 65 code of ethics. Keep them retrievable together.$dg$, $dg$A mapping of the section 46(2) factors to retrievable evidence, reviewed annually.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. This does not prevent a contravention, but it materially affects the outcome. It is not itself a statutory duty.$dg$, $dg$Map the eleven factors to your existing evidence and close the gaps in record keeping.$dg$, $dg$Map the section 46(2) penalty factors to retrievable evidence$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. Section 46(2) directs the Commission, not the organisation. DataGuard must not convert these factors into a compliance score or represent evidence readiness as reducing any legal liability.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Incident Log$dg$, $dg$Breach Notification Log$dg$, $dg$Commission Correspondence$dg$, $dg$Code of Ethics$dg$, $dg$Security Policy$dg$]::text[], false, 103) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-047-001$dg$, $dg$REQ-047-1$dg$, $dg$VII$dg$, $dg$47$dg$, NULL, NULL, $dg$Section 47$dg$, $dg$The maximum amount of the penalty that may be imposed by the Commission in a penalty notice in relation to contravention of provisions of this Act is one hundred million shillings.$dg$, $dg$Reference record - statutory ceiling on administrative fines$dg$, $dg$Reference record capturing the statutory maximum administrative penalty. It is not an assessable control and must not be used to score risk.$dg$, $dg$Reference only - no response required. The maximum administrative penalty the Commission may impose in a penalty notice is TZS 100,000,000.$dg$, $dg$This is the statutory ceiling for administrative fines under section 47. It is not the penalty for any particular control, and it is separate from the criminal penalties in sections 43, 60, 61 and 63.$dg$, $dg$Use this record for reference in board reporting only. Do not attribute this figure to any individual control, and do not use it to derive risk scores.$dg$, $dg$Not applicable. This is a reference record.$dg$, $dg$TEXT$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$NOT_APPLICABLE$dg$, $dg$NOT_APPLICABLE$dg$, $dg$ON_LEGISLATIVE_CHANGE$dg$, $dg$ENFORCEMENT$dg$, $dg$LOW$dg$, $dg$DataGuard default risk classification: Low. This is a reference record, not a control. The Act does not attach this maximum to any specific provision.$dg$, $dg$None. Reference record only.$dg$, $dg$$dg$, $dg$NONE$dg$, $dg$REFERENCE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Do not state that any individual control carries a TZS 100,000,000 penalty. Section 47 sets a ceiling for administrative penalty notices under section 46 and says nothing about which contraventions attract what amount.$dg$, ARRAY[]::text[], ARRAY[]::text[], false, 104) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, 