insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-048-001$dg$, $dg$REQ-048-1$dg$, $dg$VII$dg$, $dg$48$dg$, NULL, NULL, $dg$Section 48$dg$, $dg$The Commission may, upon application or on its own motion, review its decision or direction given in accordance with the provisions of this Part, and after review may reverse, alter or revoke it.$dg$, $dg$Use of the review of decision route$dg$, $dg$The organisation knows it may apply to the Commission for review of a decision or direction, and who internally would prepare such an application.$dg$, $dg$Do you know that you can ask the Commission to review a decision or direction it has given, and who would prepare that request?$dg$, $dg$Review is often quicker and less costly than appealing to the High Court, but only if the option is known while the deadline for the alternative is still open.$dg$, $dg$Record the review route in the regulatory response plan alongside the section 49 appeal route, with a named owner and a decision point for choosing between them.$dg$, $dg$Review and appeal routes documented in the regulatory response plan with a named owner.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$WEAK$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$LOW$dg$, $dg$DataGuard default risk classification: Low. This is a remedy available to the organisation, not a duty imposed on it.$dg$, $dg$Add the review route to the regulatory response plan.$dg$, $dg$Document the section 48 review route in the regulatory response plan$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act sets no time limit for applying for a review under section 48.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Response Plan$dg$, $dg$Escalation Matrix$dg$]::text[], false, 105) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-049-001$dg$, $dg$REQ-049-1$dg$, $dg$VII$dg$, $dg$49$dg$, NULL, NULL, $dg$Section 49$dg$, $dg$A person who is aggrieved with the administrative action taken by the Commission, including the directions given in the enforcement notice or penalty imposed in the penalty notice, may appeal to the High Court.$dg$, $dg$Awareness and preparedness for appeal to the High Court$dg$, $dg$The organisation knows that administrative action by the Commission may be appealed to the High Court, and has a route to instruct counsel promptly.$dg$, $dg$If you disagreed with an enforcement notice or a penalty, do you know that you can appeal to the High Court and who would instruct counsel?$dg$, $dg$An enforcement notice must state any right to appeal. Being ready to act on it quickly preserves options that a delayed response can close off.$dg$, $dg$Record the appeal route in the regulatory response plan with counsel contact details. Note that an enforcement notice under section 45(2)(d) must state any right to appeal.$dg$, $dg$The appeal route and counsel contacts are recorded in the regulatory response plan.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$WEAK$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$LOW$dg$, $dg$DataGuard default risk classification: Low. This is a right, not a duty. It is recorded so it is not lost through delay.$dg$, $dg$Add the section 49 appeal route and counsel contacts to the regulatory response plan.$dg$, $dg$Document the section 49 High Court appeal route$dg$, $dg$LOW$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not state the period within which an appeal to the High Court must be lodged.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Response Plan$dg$, $dg$External Counsel Retainer$dg$, $dg$Escalation Matrix$dg$]::text[], false, 106) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-050-001$dg$, $dg$REQ-050-1$dg$, $dg$VII$dg$, $dg$50$dg$, $dg$50(1)$dg$, NULL, $dg$Section 50(1)$dg$, $dg$Subject to the provisions of section 37, the Commission may, in addition to any penalty given under this Act, order a data controller or data processor who causes damages to the data subject following contraventions of any provisions of this Act to pay compensation to the data subject.$dg$, $dg$Compliance with a Commission compensation order$dg$, $dg$The organisation can identify affected data subjects and make payment in compliance with a Commission compensation order, and records the outcome.$dg$, $dg$If the Commission ordered you to pay compensation to affected individuals, could you identify them, pay them and evidence that you had?$dg$, $dg$Compensation may be ordered in addition to a penalty. Identifying affected individuals depends on record keeping that has to exist before the order arrives.$dg$, $dg$Ensure incident records identify affected data subjects. Define the payment authorisation route with finance and confirm the position with insurers in advance.$dg$, $dg$Incident records that identify affected data subjects, plus a defined compensation payment route.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Compensation is ordered after a contravention has already been established, so the primary control is upstream compliance.$dg$, $dg$Ensure incident records capture affected data subjects and agree the compensation payment route with finance.$dg$, $dg$Ensure incident records identify affected data subjects for compensation purposes$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 50(4) defines damage as including financial loss and damage not involving financial loss. Compensation under section 50 is in addition to any penalty.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Incident Log$dg$, $dg$Claims Register$dg$, $dg$Payment Records$dg$, $dg$Insurance Policy$dg$]::text[], true, 107) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-050-002$dg$, $dg$REQ-050-2$dg$, $dg$VII$dg$, $dg$50$dg$, $dg$50(2)$dg$, $dg$(b)$dg$, $dg$Sections 50(2)(b) and 50(3)$dg$, $dg$A data processor involved in processing of personal data shall be liable for damage caused by the processing if the processor has not complied with an obligation under the Act specifically directed to data processors, or has acted contrary to the data controller lawful instructions. A data controller or data processor shall not be liable if it proves that it is not in any way responsible for the event that caused the damage.$dg$, $dg$Processor compliance with controller lawful instructions$dg$, $dg$Acting as a data processor, the organisation processes only on the controller documented lawful instructions and retains records evidencing that it did.$dg$, $dg$Where you process personal data for someone else, do you keep records showing you acted only on their lawful instructions?$dg$, $dg$Section 50(2)(b) makes processor liability turn on exactly this point, and section 50(3) allows a defence only where the processor proves it was not in any way responsible.$dg$, $dg$Keep documented instructions from each controller, log deviations and the authority for them, and record refusals of unlawful instructions. Identify the processor-specific duties in the Act, notably sections 5, 27(4) and 42(3).$dg$, $dg$A documented instruction record per controller engagement, with deviations and refusals logged.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$ROLE_SPECIFIC$dg$, $dg$Do you process personal data on behalf of another organisation?$dg$, $dg$PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$THIRD_PARTY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. This provision is the basis of direct processor liability for damage, and the evidence for it must be contemporaneous.$dg$, $dg$Collect and file documented instructions from each controller and start logging deviations.$dg$, $dg$Maintain documented controller instructions for all processor engagements$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Documented Processing Instructions$dg$, $dg$Processor Agreement$dg$, $dg$Instruction Deviation Log$dg$]::text[], true, 108) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-058-001$dg$, $dg$REQ-058-2$dg$, $dg$IX$dg$, $dg$58$dg$, $dg$58(2)$dg$, $dg$(a)-(g)$dg$, $dg$Section 58(2)(a)-(g) and 58(3)$dg$, $dg$Processing may be exempted from the provisions of this Act where it is held by the data subject for his personal use; in accordance with any law or court order; for safeguarding national safety and security and public interest; to prevent or detect crimes; to detect or prevent tax evasion; for investigation of misappropriation of public funds; or for vetting for appointment to a public service position. The Minister may prescribe other instances.$dg$, $dg$Documented reliance on the section 58 exemptions$dg$, $dg$Where the organisation treats processing as exempt, the specific section 58(2) limb is identified, justified and recorded, and the scope of the exemption is kept narrow.$dg$, $dg$Where you treat some processing as exempt from the Act, have you recorded exactly which exemption applies and why?$dg$, $dg$Exemptions attach to particular processing, not to whole organisations. Reading one broadly is a common and expensive mistake.$dg$, $dg$Record the limb, the processing it covers, the justification and the reviewer. Keep the boundary of the exempt processing explicit so that adjacent processing is not swept in. Take legal advice for the national security and public interest limbs.$dg$, $dg$An exemption register recording the limb, scope, justification, reviewer and date for each exempt processing activity.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you treat any of your processing as exempt from the Act?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. An over-broad exemption claim leaves substantial processing entirely uncontrolled, and the failure is systematic rather than incidental.$dg$, $dg$Build the exemption register, define the precise boundary of each exempt activity, and obtain legal review.$dg$, $dg$Record and scope every reliance on a section 58 exemption$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$Section 58(3) allows the Minister to prescribe other exempt instances. OPEN_QUESTION: section 58(1) begins nothing under this section shall exempt, which sits awkwardly with section 58(2). The safer reading, reflected at PDPA-058-002, is that the principles and security duties continue to apply to exempt processing.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Exemption Register$dg$, $dg$Legal Assessment Note$dg$, $dg$External Counsel Advice$dg$, $dg$Court Order$dg$]::text[], true, 109) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-058-002$dg$, $dg$REQ-058-1$dg$, $dg$IX$dg$, $dg$58$dg$, $dg$58(1)$dg$, NULL, $dg$Section 58(1)$dg$, $dg$Nothing under this section shall exempt the data controller or the data processor from the responsibility of complying with the principles of the law in collection and processing of personal data and taking necessary measures to ensure protection and security of the personal data.$dg$, $dg$Principles and security duties continue to apply to exempt processing$dg$, $dg$Processing treated as exempt is still subject to the personal data protection principles and to security and protection measures.$dg$, $dg$Where processing is exempt, do you still apply the data protection principles and keep the data secure?$dg$, $dg$Section 58(1) preserves the principles and the security duties. An exemption reduces the procedural obligations, not the duty to protect the data.$dg$, $dg$Apply the section 5 principles and the section 27 safeguards to exempt processing as well. Record that decision alongside the exemption entry so the two are never separated.$dg$, $dg$Exempt processing is included in the security programme and assessed against the section 5 principles.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you treat any of your processing as exempt from the Act?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Exempt processing that falls outside the security programme is often the least protected data in the organisation.$dg$, $dg$Bring exempt processing into the scope of the security programme and the principles assessment.$dg$, $dg$Apply the principles and security measures to exempt processing$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Exemption Register$dg$, $dg$Security Policy$dg$, $dg$Risk Assessment$dg$, $dg$Data Protection Policy$dg$]::text[], true, 110) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-059-001$dg$, $dg$REQ-059-1$dg$, $dg$IX$dg$, $dg$59$dg$, NULL, NULL, $dg$Section 59$dg$, $dg$The Commission may apply to a court for a preservation order for the expeditious preservation of any personal data including traffic personal data where there is reasonable ground to believe that the personal data is vulnerable to loss or modification. The order shall specify a period which shall not be more than ninety days and may be extended by the court.$dg$, $dg$Compliance with a court preservation order$dg$, $dg$The organisation can suspend deletion and modification of specified personal data on receipt of a preservation order and evidence that it has done so.$dg$, $dg$If a court ordered you to preserve specific personal data, could you stop it being deleted or changed - including by automated retention jobs?$dg$, $dg$Automated deletion routines will keep running unless someone stops them. A preservation order breached by a scheduled job is still a breached order.$dg$, $dg$Define a legal hold capability that suspends automated deletion and restricts modification for identified records, including in backups. Record the hold, its scope and its release. Sequence it ahead of the section 28 disposal process.$dg$, $dg$A tested legal hold capability covering all systems, with a hold register recording scope and release.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$ENFORCEMENT$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Breach of a court order is a serious matter, and loss through an automated job is a foreseeable and preventable failure.$dg$, $dg$Build a legal hold capability that suspends automated deletion, and test it on a sample record set.$dg$, $dg$Implement a legal hold capability that suspends automated deletion$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$The preservation duty interacts with section 28 disposal and with section 29(2) preservation of pre-amendment records. Disposal processes must yield to a preservation order.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Legal Hold Procedure$dg$, $dg$Legal Hold Register$dg$, $dg$System Capability Assessment$dg$, $dg$Court Order$dg$]::text[], true, 111) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-060-001$dg$, $dg$REQ-060-1$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$60(1)$dg$, NULL, $dg$Section 60(1)$dg$, $dg$A data controller who, without lawful excuse, discloses personal data in any manner that is incompatible with the purpose for which such personal data has been collected commits an offence.$dg$, $dg$Prevention of disclosure incompatible with the collection purpose$dg$, $dg$Controls prevent disclosure of personal data in a manner incompatible with the purpose for which it was collected, and staff understand this is a criminal offence.$dg$, $dg$Do your controls and your staff training prevent personal data being shared in ways that clash with the purpose it was collected for?$dg$, $dg$This is a criminal offence, not just a regulatory contravention, and the penalties reach five billion shillings for a company or corporation.$dg$, $dg$Combine the disclosure register from PDPA-026-001 with technical controls on data export and with staff training that names the criminal consequence. Review ad hoc disclosure requests against the recorded purpose.$dg$, $dg$Disclosure controls in place, a maintained disclosure register, and training records covering the offence.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DISCLOSURE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 60(1) is a criminal offence, and section 62 extends liability to officers who knowingly and willfully authorise or permit the contravention.$dg$, $dg$Tighten export and sharing controls, complete the disclosure register, and run targeted training for staff who handle disclosure requests.$dg$, $dg$Implement controls and training against incompatible disclosure of personal data$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 60(6) penalties: individual - fine of not less than TZS 100,000 and not exceeding TZS 20,000,000, or imprisonment not exceeding ten years, or both; company or corporation - fine of not less than TZS 1,000,000 and not exceeding TZS 5,000,000,000.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Disclosure Register$dg$, $dg$Data Protection Policy$dg$, $dg$Training Records$dg$, $dg$Access Control Procedure$dg$]::text[], true, 112) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-060-002$dg$, $dg$REQ-060-2$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$60(2)$dg$, NULL, $dg$Section 60(2)$dg$, $dg$A data processor who, without lawful excuse, discloses personal data processed by the data processor without the prior authority of the data controller commits an offence.$dg$, $dg$Processor discloses only with prior controller authority$dg$, $dg$Acting as a processor, the organisation discloses personal data only with the prior authority of the controller, and records that authority.$dg$, $dg$Where you process data for someone else, do you get their permission in advance before disclosing it to anyone, and do you keep a record?$dg$, $dg$This is a criminal offence specific to processors. It catches routine situations such as responding to a third party request without checking with the controller first.$dg$, $dg$Define an authority check before any disclosure of controller data, including responses to law enforcement and other third party requests. Record the authority obtained. Route any legal compulsion through counsel.$dg$, $dg$A disclosure authority procedure with a log of controller authorities obtained.$dg$, $dg$YES_NO$dg$, $dg$ROLE_SPECIFIC$dg$, $dg$Do you process personal data on behalf of another organisation?$dg$, $dg$PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DISCLOSURE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 60(2) creates direct criminal liability for the processor and its officers under section 62.$dg$, $dg$Implement a prior authority check for all disclosures of controller data and start the authority log.$dg$, $dg$Implement a prior controller authority check for processor disclosures$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Disclosure Authority Log$dg$, $dg$Processor Agreement$dg$, $dg$Documented Processing Instructions$dg$, $dg$Training Records$dg$]::text[], true, 113) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-060-003$dg$, $dg$REQ-060-3$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$60(3)$dg$, $dg$(a)-(b)$dg$, $dg$Section 60(3)(a)-(b)$dg$, $dg$A person who obtains personal data, or obtains any information constituting personal data, without prior authority of the data controller or data processor by whom the personal data is kept, or discloses personal data to a third party, commits an offence.$dg$, $dg$No obtaining or onward disclosure of personal data without authority$dg$, $dg$Staff and contractors do not obtain personal data from other organisations without authority, and do not disclose personal data to third parties without authority.$dg$, $dg$Are your people clear that taking personal data from another organisation without permission, or passing personal data to an outsider, is a criminal offence?$dg$, $dg$This limb catches individuals, not only organisations. It reaches situations like an employee bringing a customer list from a previous employer.$dg$, $dg$Cover this expressly in the acceptable use policy, in employment terms and in induction training. Screen third party data sources for provenance, linking to PDPA-022-004.$dg$, $dg$Policy and training in place covering obtaining and disclosing personal data without authority, with acknowledgement records.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$ANNUAL$dg$, $dg$DISCLOSURE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Individual criminal liability attaches, and the conduct is frequently committed without awareness that it is an offence.$dg$, $dg$Add explicit wording to the acceptable use policy and induction training, and screen incoming data sources.$dg$, $dg$Add unauthorised obtaining and disclosure to policy and induction training$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Acceptable Use Policy$dg$, $dg$Employment Terms$dg$, $dg$Training Records$dg$, $dg$Data Source Register$dg$]::text[], true, 114) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-060-004$dg$, $dg$REQ-060-4$dg$, $dg$IX$dg$, $dg$60$dg$, $dg$60(4)$dg$, NULL, $dg$Sections 60(4) and 60(5)$dg$, $dg$A person who offers for sale personal data of another person obtained in breach of subsection (1) commits an offence. An advertisement indicating that personal data is or may be for sale constitutes an offer for sale of the personal data.$dg$, $dg$No offering of unlawfully obtained personal data for sale$dg$, $dg$The organisation does not sell, offer for sale or advertise the sale of personal data obtained in breach of section 60(1), and monitors any commercial data activity for this risk.$dg$, $dg$Do you have any commercial arrangement that involves selling or advertising the sale of personal data, and have you checked how that data was obtained?$dg$, $dg$Section 60(5) is broad: an advertisement indicating that data is or may be for sale is itself an offer for sale.$dg$, $dg$Review any data monetisation, list rental or data brokerage activity. Confirm provenance and lawful basis before any such activity, and take legal advice.$dg$, $dg$Any data sale or monetisation activity is inventoried with provenance and lawful basis confirmed, or the organisation has confirmed it has none.$dg$, $dg$YES_NO$dg$, $dg$CONDITIONAL$dg$, $dg$Do you sell, offer for sale, or advertise the sale of personal data in any form?$dg$, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$DISCLOSURE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. This is a criminal offence carrying the section 60(6) penalties, and section 60(5) extends it to advertising alone.$dg$, $dg$Inventory any data sale activity, verify provenance, and obtain legal advice before continuing.$dg$, $dg$Review any sale or advertising of personal data for lawfulness$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$INTERPRETATION: section 60(4) refers to data obtained in breach of subsection (1), which addresses disclosure by a data controller. The precise scope of the cross-reference is not elaborated in the Act.$dg$, ARRAY[$dg$Yes$dg$, $dg$No$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Data Monetisation Register$dg$, $dg$Data Source Register$dg$, $dg$Legal Assessment Note$dg$, $dg$Data Protection Policy$dg$]::text[], true, 115) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-061-001$dg$, $dg$REQ-061-1$dg$, $dg$IX$dg$, $dg$61$dg$, NULL, NULL, $dg$Section 61$dg$, $dg$A person who unlawfully destroys, deletes, misleads, conceals or alters personal data commits an offence and shall, upon conviction, be liable to a fine of not less than one hundred thousand shillings but not exceeding ten million shillings or to imprisonment for a term not exceeding five years or both.$dg$, $dg$Prevention of unlawful destruction, deletion, concealment or alteration$dg$, $dg$Technical and organisational controls prevent unlawful destruction, deletion, concealment or alteration of personal data, and such actions are detectable after the fact.$dg$, $dg$Are you able to prevent, and to detect afterwards, anyone unlawfully deleting, hiding or altering personal data?$dg$, $dg$This is a criminal offence in its own right. It also matters during an investigation, where deleting or altering records looks like concealment whatever the intention.$dg$, $dg$Restrict destructive rights, keep tamper-evident audit logs, and monitor for bulk deletion or alteration. Reinforce during any investigation or legal hold. This builds on PDPA-027-003 and PDPA-027-004.$dg$, $dg$Destructive rights restricted, tamper-evident logging in place, and alerting on bulk deletion or alteration.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$DATA_INTEGRITY$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Section 61 creates a criminal offence with an express penalty, and undetected alteration also breaches sections 24 and 27(1).$dg$, $dg$Restrict destructive permissions, enable tamper-evident logging, and alert on bulk changes.$dg$, $dg$Restrict destructive rights and enable tamper-evident logging over personal data$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 61 penalty: fine of not less than TZS 100,000 and not exceeding TZS 10,000,000, or imprisonment not exceeding five years, or both. This penalty is specific to section 61.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Access Control Procedure$dg$, $dg$Audit Log Configuration$dg$, $dg$Monitoring and Alerting Configuration$dg$, $dg$Training Records$dg$]::text[], true, 116) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-062-001$dg$, $dg$REQ-062-1$dg$, $dg$IX$dg$, $dg$62$dg$, NULL, NULL, $dg$Section 62$dg$, $dg$Where an offence under this Act is committed by a company or corporation, the company or corporation and every officer of the company or corporation who knowingly and willfully authorises or permits the contravention shall be liable for the offence.$dg$, $dg$Officer accountability and board oversight of data protection$dg$, $dg$Officers are made aware of their personal exposure under section 62, and data protection is subject to documented board or senior management oversight.$dg$, $dg$Do your directors and senior officers know they can be personally liable, and does the board receive regular reporting on data protection?$dg$, $dg$Section 62 attaches personal liability to officers who knowingly and willfully authorise or permit a contravention. Documented oversight is how officers show they engaged with the issue.$dg$, $dg$Brief the board and senior officers on section 62. Establish periodic data protection reporting to the board, minuted, drawing on the data protection officer reports under section 27(3).$dg$, $dg$Documented officer briefing and a recurring, minuted board or senior management reporting item on data protection.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$QUARTERLY$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Personal officer liability is a distinct exposure, and the absence of oversight records makes the knowingly and willfully question harder to answer favourably.$dg$, $dg$Brief the board on section 62 and establish a standing data protection reporting item.$dg$, $dg$Establish board-level data protection oversight and brief officers on section 62$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED. Section 62 states the liability; it does not expressly require board reporting. The oversight arrangement is DataGuard implementation guidance responding to that liability.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Board Minutes$dg$, $dg$Officer Briefing Record$dg$, $dg$DPO Report$dg$, $dg$Governance Framework$dg$]::text[], true, 117) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-064-001$dg$, $dg$REQ-064-1$dg$, $dg$IX$dg$, $dg$64$dg$, $dg$64(2)$dg$, $dg$(a)-(l)$dg$, $dg$Section 64(1)-(2)$dg$, $dg$The Minister may make regulations for giving effect to the provisions of this Act, including regulations prescribing exempt instances, registration procedures, the functions of the data protection officer, the functions of the data controller representative, procedures for enforcing rights, procedures for submitting complaints, conditions for processing sensitive personal data, appropriate security standards, fees, procedures for retention and disposal, categories and cases in which transborder data flow may not be allowed, and anything necessary for the better carrying out of the Act.$dg$, $dg$Monitoring of regulations made under the Act$dg$, $dg$The organisation monitors for regulations made under section 64 and assesses their effect on its controls, because many obligations under the Act are completed by regulations.$dg$, $dg$Do you have someone responsible for watching for new regulations under the Act and working out what they mean for you?$dg$, $dg$A large part of the operational detail in this Act - registration procedure, DPO functions, security standards, retention, transfer prohibitions - is left to regulations. Controls built without them will need revisiting.$dg$, $dg$Assign an owner for regulatory monitoring, subscribe to Government Notice publications, and define how a new regulation triggers reassessment of the affected controls and of the control matrix version.$dg$, $dg$A named owner, a monitoring source, and a documented reassessment trigger for new regulations.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER_AND_PROCESSOR$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$MODERATE$dg$, $dg$QUARTERLY$dg$, $dg$GOVERNANCE$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. Missing a new regulation does not itself contravene the Act, but it leaves controls built on incomplete requirements.$dg$, $dg$Assign a regulatory monitoring owner and set a quarterly review.$dg$, $dg$Assign ownership for monitoring regulations made under the Act$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$REGULATORY_DETAIL_PENDING$dg$, $dg$ACT_DERIVED. Section 64 empowers the Minister; it imposes no monitoring duty on the organisation. Every control in this matrix marked REGULATORY_DETAIL_PENDING depends on regulations under this section.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Regulatory Change Log$dg$, $dg$Compliance Calendar$dg$, $dg$Governance Framework$dg$]::text[], true, 118) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-065-001$dg$, $dg$REQ-065-1$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$65(1)$dg$, NULL, $dg$Section 65(1)$dg$, $dg$Every data controller shall draw and put in place a code of ethics or policy for personal data protection.$dg$, $dg$Code of ethics or personal data protection policy exists$dg$, $dg$The data controller has drawn up and put in place a written code of ethics or personal data protection policy.$dg$, $dg$Have you written and put in place a code of ethics or a data protection policy for your organisation?$dg$, $dg$Section 65(1) applies to every data controller with no threshold. It is a document the Commission can ask for at any time, and section 46(2)(i) treats adherence to codes of ethics as relevant to any penalty.$dg$, $dg$Produce a written code or policy, have it approved by the accountable body, and version it. Drawn and put in place implies both adoption and operation, so accompany it with communication and training.$dg$, $dg$An approved, dated and versioned code of ethics or data protection policy, communicated to staff.$dg$, $dg$DOCUMENT_REQUIRED$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. The duty applies to every data controller, it is binary, and its absence is immediately apparent to the Commission.$dg$, $dg$Draft the code or policy, obtain formal approval, publish it internally, and prepare it for submission under section 65(2).$dg$, $dg$Draw up and adopt a code of ethics or personal data protection policy$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[]::text[], ARRAY[$dg$Code of Ethics$dg$, $dg$Data Protection Policy$dg$, $dg$Approval Record$dg$, $dg$Training Records$dg$]::text[], true, 119) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-065-002$dg$, $dg$REQ-065-1$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$65(1)$dg$, NULL, $dg$Section 65(1)$dg$, $dg$The code of ethics or policy shall prescribe for ethics and conduct to be complied with during collection or processing of personal data.$dg$, $dg$Scope of the code covers ethics and conduct in collection and processing$dg$, $dg$The code or policy addresses the ethics and conduct expected during collection and processing of personal data, not merely high-level principles.$dg$, $dg$Does your code or policy actually say how people should behave when collecting and handling personal data?$dg$, $dg$The Act specifies the subject matter: ethics and conduct during collection or processing. A document of general statements does not meet that description.$dg$, $dg$Cover conduct expectations at collection, use, disclosure, retention and disposal, together with roles, escalation and consequences of breach. Map the code sections against the Act so gaps are visible.$dg$, $dg$A code or policy with conduct provisions covering the full data lifecycle, mapped against the Act.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Section 65(3) requires the Commission to ascertain whether the draft complies with the Act and the relevant sector, so a thin code will fail at approval.$dg$, $dg$Expand the code to cover the full lifecycle and map its sections against the Act before submission.$dg$, $dg$Extend the code of ethics to cover conduct across the data lifecycle$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Code of Ethics$dg$, $dg$Data Protection Policy$dg$, $dg$Policy Coverage Mapping$dg$]::text[], true, 120) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-065-003$dg$, $dg$REQ-065-1$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$65(1)$dg$, NULL, $dg$Section 65(1)$dg$, $dg$Every data controller shall draw and put in place a code of ethics or policy, which requires formal adoption by the data controller.$dg$, $dg$Approval and adoption of the code of ethics$dg$, $dg$The code or policy has been formally approved and adopted by the accountable body within the organisation, with the approval recorded.$dg$, $dg$Has your code or policy been formally approved by your board or senior management, with the approval recorded?$dg$, $dg$A draft that has never been adopted has not been put in place. The approval record is also what connects the document to accountable officers for the purposes of section 62.$dg$, $dg$Record the approving body, the date and the version. Re-approve on material change.$dg$, $dg$An approval record naming the approving body, the date and the version approved.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$HIGH$dg$, $dg$DataGuard default risk classification: High. Without adoption the code is not in place, and the section 65(1) duty remains unmet however good the draft is.$dg$, $dg$Take the code to the board or senior management for formal approval and minute it.$dg$, $dg$Obtain and record formal approval of the code of ethics$dg$, $dg$HIGH$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_DERIVED$dg$, $dg$NONE$dg$, $dg$ACT_DERIVED from the requirement to draw and put in place. The Act does not prescribe who must approve the code within the organisation.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Board Minutes$dg$, $dg$Approval Record$dg$, $dg$Code of Ethics$dg$, $dg$Version History$dg$]::text[], true, 121) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-065-004$dg$, $dg$REQ-065-2$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$65(2)$dg$, NULL, $dg$Section 65(2)$dg$, $dg$Such codes or policies shall be submitted to the Commission for consideration and approval.$dg$, $dg$Code of ethics submitted to the Commission for approval$dg$, $dg$The code or policy has been submitted to the Commission for consideration and approval, and the submission and any response are retained.$dg$, $dg$Have you submitted your code of ethics or data protection policy to the Commission for approval, and do you have proof?$dg$, $dg$Adoption alone is not enough. Section 65(2) requires submission to the Commission for consideration and approval, and this step is frequently overlooked.$dg$, $dg$Submit the approved code to the Commission, retain proof of submission, track the response, and act on any amendments the Commission requires under section 65(3).$dg$, $dg$Proof of submission on file, with the Commission response and approval status tracked.$dg$, $dg$DOCUMENT_REQUIRED$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$REQUIRED_BY_ACT$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$CRITICAL$dg$, $dg$DataGuard default risk classification: Critical. Section 65(2) is expressed in mandatory terms, the step is binary, and an unsubmitted code leaves the section 65 duty only half discharged.$dg$, $dg$Submit the approved code to the Commission and retain proof of submission and the response.$dg$, $dg$Submit the code of ethics to the Commission for consideration and approval$dg$, $dg$CRITICAL$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$OPEN_QUESTION: the Act does not state a deadline for submission, the form of submission, or the consequence of the Commission not responding.$dg$, ARRAY[]::text[], ARRAY[$dg$Proof of Submission$dg$, $dg$Commission Correspondence$dg$, $dg$Commission Approval$dg$, $dg$Code of Ethics$dg$]::text[], true, 122) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=excluded.default_risk_level, risk_rationale=excluded.risk_rationale, remediation_guidance=excluded.remediation_guidance, suggested_task=excluded.suggested_task, suggested_task_priority=excluded.suggested_task_priority, control_status=excluded.control_status, version=excluded.version, source_type=excluded.source_type, regulatory_status=excluded.regulatory_status, notes=excluded.notes, answer_options=excluded.answer_options, evidence_examples=excluded.evidence_examples, required=excluded.required, display_order=excluded.display_order, requirement_id=excluded.requirement_id, part_number=excluded.part_number, section_number=excluded.section_number;
insert into framework_controls (framework_code, version_code, control_id, requirement_id, part_number, section_number, subsection, paragraph, legal_reference, legal_requirement, control_title, control_description, plain_language_question, why_this_matters, implementation_guidance, expected_state, response_type, applicability, applicability_question, role_scope, evidence_required, evidence_strength, evidence_review_frequency, risk_category, default_risk_level, risk_rationale, remediation_guidance, suggested_task, suggested_task_priority, control_status, version, source_type, regulatory_status, notes, answer_options, evidence_examples, required, display_order) values ($dg$TZ-PDPA$dg$, $dg$2022$dg$, $dg$PDPA-065-005$dg$, $dg$REQ-065-3$dg$, $dg$IX$dg$, $dg$65$dg$, $dg$65(3)$dg$, NULL, $dg$Section 65(3)$dg$, $dg$In considering the codes of ethics or policies, the Commission shall ascertain whether the drafts have complied with the provisions of this Act and the relevant sector and where it considers necessary, seek the views of data subjects or their representatives and consult with the data controller for the purposes of undertaking necessary amendments prior to the approval.$dg$, $dg$Engagement with Commission consideration and required amendments$dg$, $dg$The organisation engages with the Commission consultation on its code, implements required amendments, and maintains version control over the code.$dg$, $dg$If the Commission asked for changes to your code before approving it, could you respond, make the changes and track the versions?$dg$, $dg$Approval is a process, not a filing. The Commission may consult data subjects and require amendments before approving.$dg$, $dg$Name an owner for the Commission dialogue, keep a version history of the code, and record which version was submitted, which amendments were required, and which version was approved.$dg$, $dg$A version-controlled code with a record of Commission correspondence, required amendments and the approved version.$dg$, $dg$YES_PARTIAL_NO$dg$, $dg$UNIVERSAL$dg$, NULL, $dg$CONTROLLER$dg$, $dg$RECOMMENDED_BY_DATAGUARD$dg$, $dg$STRONG$dg$, $dg$ANNUAL$dg$, $dg$GOVERNANCE$dg$, $dg$MEDIUM$dg$, $dg$DataGuard default risk classification: Medium. The section directs the Commission, but failing to respond to a consultation stalls approval indefinitely.$dg$, $dg$Establish version control over the code and name an owner for Commission correspondence.$dg$, $dg$Maintain version control and Commission correspondence records for the code of ethics$dg$, $dg$MEDIUM$dg$, $dg$ACTIVE$dg$, $dg$1.0.0$dg$, $dg$ACT_EXPLICIT$dg$, $dg$NONE$dg$, $dg$Section 65(3) directs the Commission. The organisation obligation is derived: it must be able to respond and to amend. Periodic review of the code is IMPLEMENTATION_GUIDANCE; the Act imposes no review cycle.$dg$, ARRAY[$dg$Implemented$dg$, $dg$Partially implemented$dg$, $dg$Not implemented$dg$, $dg$Not applicable$dg$, $dg$I do not know$dg$]::text[], ARRAY[$dg$Version History$dg$, $dg$Commission Correspondence$dg$, $dg$Amendment Record$dg$, $dg$Code of Ethics$dg$]::text[], true, 123) on conflict (framework_code, version_code, control_id) do update set subsection=excluded.subsection, paragraph=excluded.paragraph, legal_reference=excluded.legal_reference, legal_requirement=excluded.legal_requirement, control_title=excluded.control_title, control_description=excluded.control_description, plain_language_question=excluded.plain_language_question, why_this_matters=excluded.why_this_matters, implementation_guidance=excluded.implementation_guidance, expected_state=excluded.expected_state, response_type=excluded.response_type, applicability=excluded.applicability, applicability_question=excluded.applicability_question, role_scope=excluded.role_scope, evidence_required=excluded.evidence_required, evidence_strength=excluded.evidence_strength, evidence_review_frequency=excluded.evidence_review_frequency, risk_category=excluded.risk_category, default_risk_level=exclu